_INPUTS_DEBUG_AUDIT = os.environ.get("INPUTS_DEBUG_AUDIT", "").strip().lower() in ("1", "true", "yes", "on")


def _inputs_pre_widget_trace_enabled() -> bool:
    return os.environ.get("PERF_TRACE_INPUTS", "").strip().lower() in {"1", "true", "yes", "on"}


def _inputs_pre_widget_trace(block: str, _force: bool = False, **payload) -> None:
    if not (_force or _inputs_pre_widget_trace_enabled()):
        return
    try:
        os.makedirs(os.path.join("artifacts", "performance"), exist_ok=True)
        path_key = "_inputs_pre_widget_trace_path"
        if path_key not in st.session_state:
            stamp = datetime.now().strftime("%Y-%m-%dT%H-%M-%S")
            st.session_state[path_key] = os.path.join(
                "artifacts",
                "performance",
                f"inputs_pre_widget_trace_{stamp}.jsonl",
            )
        try:
            query_params = dict(getattr(st, "query_params", {}) or {})
        except Exception:
            query_params = {}
        counts_key = "_inputs_pre_widget_trace_counts"
        counts = st.session_state.get(counts_key)
        if not isinstance(counts, dict):
            counts = {}
        count = int(counts.get(block, 0) or 0) + 1
        counts[block] = count
        st.session_state[counts_key] = counts
        row = {
            "timestamp": datetime.now().isoformat(timespec="milliseconds"),
            "recipe": query_params.get("browser_recipe") or st.session_state.get("_browser_recipe_applied_name"),
            "cid": query_params.get("cid"),
            "block": block,
            "call_count": count,
            **payload,
        }
        with open(st.session_state[path_key], "a", encoding="utf-8") as fh:
            fh.write(json.dumps(row, default=str) + "\n")
    except Exception:
        pass


def _direct_target_band_diag_enabled() -> bool:
    return _inputs_pre_widget_trace_enabled() or (
        os.environ.get("CODEX_BROWSER_TEST_MODE", "").strip().lower() in {"1", "true", "yes", "on"}
    )


def _direct_target_band_diag_trace(block: str, **payload) -> None:
    if not _direct_target_band_diag_enabled():
        return
    _inputs_pre_widget_trace(block, _force=True, **payload)


def log_debug(message, value=None):
    print(f"[INPUTS DEBUG] {message}: {value}")


def _inputs_audit_snapshot_state():
    """Best-effort snapshot of session state for diff (may skip unpickleable values)."""
    out: dict[str, object] = {}
    for k in list(st.session_state.keys()):
        try:
            out[k] = copy.deepcopy(st.session_state.get(k))
        except Exception:
            try:
                out[k] = st.session_state.get(k)
            except Exception:
                out[k] = "<unreadable>"
    return out


def _wrap_inputs_sync_callbacks(raw: dict, log_debug_fn) -> dict:
    def sync_callback_wrapper(fn, name):
        def wrapper():
            if not _INPUTS_DEBUG_AUDIT:
                fn()
                return
            log_debug_fn(f"SYNC CALLBACK TRIGGERED - {name}")
            tracked_keys = tuple(st.session_state.keys())
            before = {k: st.session_state.get(k) for k in tracked_keys}
            fn()
            changed = False
            for k in tracked_keys:
                if before.get(k) != st.session_state.get(k):
                    changed = True
                    break

            if not changed:
                return

            for k in tracked_keys:
                old = before.get(k)
                new = st.session_state.get(k)
                if old != new:
                    log_debug_fn(f"SYNC CHANGE - {k}", f"{old} -> {new}")
        return wrapper

    return {k: sync_callback_wrapper(v, k) for k, v in raw.items()}


