def _is_inputs_longitudinal_reo_widget_key(widget_key: str | None) -> bool:
    wk = str(widget_key or "").strip()
    if wk in {"inputs_bot_row_count", "inputs_top_row_count"}:
        return True
    longitudinal_prefixes = (
        "inputs_bot_row_",
        "inputs_top_row_",
    )
    return wk.startswith(longitudinal_prefixes)


def _longitudinal_reo_widget_audit_snapshot(label: str) -> dict:
    ss = st.session_state
    shared_row_model: dict[str, object] = {}
    legacy_mirror: dict[str, object] = {}
    inputs_widget_mirror: dict[str, object] = {}

    for section in ("bot", "top"):
        shared_row_model[f"{section}_row_count"] = ss.get(f"{section}_row_count")
        inputs_widget_mirror[f"inputs_{section}_row_count"] = ss.get(f"inputs_{section}_row_count")
        for row_idx in _LONGITUDINAL_REO_AUDIT_ROWS:
            for field in _LONGITUDINAL_REO_ROW_FIELDS:
                shared_key = f"{section}_row_{row_idx}_{field}"
                widget_key = f"inputs_{section}_row_{row_idx}_{field}"
                shared_row_model[shared_key] = ss.get(shared_key)
                inputs_widget_mirror[widget_key] = ss.get(widget_key)

    for key in (
        "bot1_count", "db_bot_1", "bot2_count", "db_bot_2",
        "top1_count", "db_top_1", "top2_count", "db_top_2",
        "nb_bot", "nb_top", "Ast_bot", "Ast_top",
    ):
        legacy_mirror[key] = ss.get(key)

    drift_keys: list[str] = []
    for section in ("bot", "top"):
        shared_count_key = f"{section}_row_count"
        widget_count_key = f"inputs_{section}_row_count"
        if shared_row_model.get(shared_count_key) != inputs_widget_mirror.get(widget_count_key):
            drift_keys.append(shared_count_key)
        for row_idx in _LONGITUDINAL_REO_AUDIT_ROWS:
            for field in _LONGITUDINAL_REO_ROW_FIELDS:
                shared_key = f"{section}_row_{row_idx}_{field}"
                widget_key = f"inputs_{section}_row_{row_idx}_{field}"
                if shared_row_model.get(shared_key) != inputs_widget_mirror.get(widget_key):
                    drift_keys.append(shared_key)

    snapshot = {
        "label": str(label or "").strip() or "unlabelled",
        "page_slug": str(ss.get("page_slug") or ""),
        "active_beam_id": str(ss.get("active_beam_id") or "") or None,
        "shared_row_model": shared_row_model,
        "legacy_mirror": legacy_mirror,
        "inputs_widget_mirror": inputs_widget_mirror,
        "diff_summary": {
            "drift_detected": bool(drift_keys),
            "drift_keys": list(drift_keys),
            "drift_count": len(drift_keys),
        },
    }

    audit_store = dict(ss.get("_inputs_longitudinal_reo_audit") or {})
    history = list(audit_store.get("history") or [])
    history.append(copy.deepcopy(snapshot))
    if len(history) > 24:
        history = history[-24:]
    audit_store["latest"] = copy.deepcopy(snapshot)
    audit_store["history"] = history
    ss["_inputs_longitudinal_reo_audit"] = audit_store
    ss["inputs_longitudinal_reo_widget_drift_detected"] = bool(drift_keys)
    ss["inputs_longitudinal_reo_widget_drift_keys"] = list(drift_keys)

    try:
        _agent_debug_log(
            "Inputs longitudinal reo widget audit snapshot",
            snapshot,
            location="inputs_page.py:_longitudinal_reo_widget_audit_snapshot",
            hypothesis_id="H_INPUTS_LONGITUDINAL_WIDGET_AUDIT",
        )
    except Exception:
        pass
    return snapshot


def _reseed_inputs_longitudinal_reo_widgets_from_shared(reason: str, *, force: bool = False) -> dict:
    ss = st.session_state
    reason_norm = str(reason or "").strip() or "unspecified"
    last_widget_key = str(ss.get("_last_user_widget_key") or "").strip()
    last_edit_ts = float(ss.get("_last_user_edit_ts", 0.0) or 0.0)
    active_edit_age_s = max(0.0, time.time() - last_edit_ts) if last_edit_ts > 0.0 else float("inf")
    actively_editing_longitudinal_widget = _is_inputs_longitudinal_reo_widget_key(last_widget_key) and active_edit_age_s < 2.0

    changed_widget_keys: list[str] = []
    if actively_editing_longitudinal_widget and not force:
        payload = {
            "reseed_applied": False,
            "reseed_reason": reason_norm,
            "changed_widget_keys": [],
            "skipped_due_to_active_edit": True,
            "active_edit_widget_key": last_widget_key,
        }
        ss["inputs_longitudinal_reo_reseed_applied"] = False
        ss["inputs_longitudinal_reo_reseed_reason"] = reason_norm
        ss["inputs_longitudinal_reo_reseed_changed_keys"] = []
        try:
            _agent_debug_log(
                "Skipped inputs longitudinal reo widget reseed",
                payload,
                location="inputs_page.py:_reseed_inputs_longitudinal_reo_widgets_from_shared",
                hypothesis_id="H_INPUTS_LONGITUDINAL_WIDGET_RESEED",
            )
        except Exception:
            pass
        return payload

    for section in ("bot", "top"):
        count_shared_key = f"{section}_row_count"
        count_widget_key = f"inputs_{section}_row_count"
        if count_shared_key in ss:
            shared_value = copy.deepcopy(ss.get(count_shared_key))
            if ss.get(count_widget_key) != shared_value:
                ss[count_widget_key] = shared_value
                changed_widget_keys.append(count_widget_key)
            ss.pop(f"_cached_{count_widget_key}", None)
        for row_idx in _LONGITUDINAL_REO_RESEED_ROWS:
            for field in _LONGITUDINAL_REO_ROW_FIELDS:
                shared_key = f"{section}_row_{row_idx}_{field}"
                widget_key = f"inputs_{section}_row_{row_idx}_{field}"
                if shared_key not in ss:
                    continue
                shared_value = copy.deepcopy(ss.get(shared_key))
                if ss.get(widget_key) != shared_value:
                    ss[widget_key] = shared_value
                    changed_widget_keys.append(widget_key)
                ss.pop(f"_cached_{widget_key}", None)

    hydrated_map = ss.get("_hydrated_from_shared_map")
    if isinstance(hydrated_map, dict):
        for widget_key in changed_widget_keys:
            hydrated_map.pop(widget_key, None)

    payload = {
        "reseed_applied": bool(changed_widget_keys),
        "reseed_reason": reason_norm,
        "changed_widget_keys": list(changed_widget_keys),
        "skipped_due_to_active_edit": False,
        "active_edit_widget_key": last_widget_key or None,
    }
    ss["inputs_longitudinal_reo_reseed_applied"] = bool(changed_widget_keys)
    ss["inputs_longitudinal_reo_reseed_reason"] = reason_norm
    ss["inputs_longitudinal_reo_reseed_changed_keys"] = list(changed_widget_keys)

    try:
        _agent_debug_log(
            "Inputs longitudinal reo widget reseed",
            payload,
            location="inputs_page.py:_reseed_inputs_longitudinal_reo_widgets_from_shared",
            hypothesis_id="H_INPUTS_LONGITUDINAL_WIDGET_RESEED",
        )
    except Exception:
        pass
    return payload


def _force_inputs_longitudinal_reo_hydrate_cycle(reason: str) -> dict:
    _longitudinal_reo_widget_audit_snapshot("before_inputs_hydrate")
    hydrate_active_page_widgets_from_shared("inputs", force_on_page_change=True)
    _longitudinal_reo_widget_audit_snapshot("after_inputs_hydrate")
    reseed_payload = _reseed_inputs_longitudinal_reo_widgets_from_shared(reason, force=True)
    _longitudinal_reo_widget_audit_snapshot("after_inputs_longitudinal_reseed")
    st.session_state["_inputs_longitudinal_reo_force_refresh_reason"] = str(reason or "")
    st.session_state["_inputs_longitudinal_reo_force_refresh_processed_this_run"] = True
    return reseed_payload


def _request_shear_widget_seed_from_shared(reason: str) -> dict:
    ss = st.session_state
    reason_norm = str(reason or "").strip() or "unspecified"
    shared_values = {
        "lig_d": ss.get("lig_d"),
        "lig_legs": ss.get("lig_legs"),
        "s_lig": ss.get("s_lig"),
    }
    widget_map = {
        "inputs_lig_d": shared_values["lig_d"],
        "inputs_lig_legs": shared_values["lig_legs"],
        "inputs_s_lig": shared_values["s_lig"],
        "shear_lig_d": shared_values["lig_d"],
        "shear_lig_legs": shared_values["lig_legs"],
        "shear_s_lig": shared_values["s_lig"],
    }
    widget_keys = list(widget_map.keys())
    for widget_key in widget_keys:
        ss.pop(f"_cached_{widget_key}", None)

    hydrated_map = ss.get("_hydrated_from_shared_map")
    if isinstance(hydrated_map, dict):
        for widget_key in widget_keys:
            hydrated_map.pop(widget_key, None)

    payload = {
        "seed_requested": True,
        "reason": reason_norm,
        "shared": dict(shared_values),
        "widget_keys": list(widget_keys),
        "direct_widget_writes": [],
    }
    ss["_pending_shear_widget_seed_from_shared"] = dict(payload)
    ss["inputs_shear_widget_seed_requested"] = True
    ss["inputs_shear_widget_seed_reason"] = reason_norm
    ss["_inputs_shear_widget_seed_latest"] = dict(payload)
    try:
        _agent_debug_log(
            "Inputs shear widget seed requested from shared",
            payload,
            location="inputs_page.py:_request_shear_widget_seed_from_shared",
            hypothesis_id="H_INPUTS_SHEAR_WIDGET_SEED_REQUEST",
        )
    except Exception:
        pass
    return payload


def _force_inputs_apply_refresh_cycle(reason: str) -> dict:
    _longitudinal_reo_widget_audit_snapshot("before_inputs_hydrate")
    hydrate_active_page_widgets_from_shared("inputs", force_on_page_change=True)
    _longitudinal_reo_widget_audit_snapshot("after_inputs_hydrate")
    longitudinal_payload = _reseed_inputs_longitudinal_reo_widgets_from_shared(reason, force=True)
    shear_payload = _request_shear_widget_seed_from_shared(reason)
    _longitudinal_reo_widget_audit_snapshot("after_inputs_longitudinal_reseed")
    st.session_state["_inputs_longitudinal_reo_force_refresh_reason"] = str(reason or "")
    st.session_state["_inputs_longitudinal_reo_force_refresh_processed_this_run"] = True
    st.session_state["_inputs_shear_force_refresh_processed_this_run"] = True
    combined_payload = {
        "reason": str(reason or ""),
        "longitudinal_payload": longitudinal_payload,
        "shear_payload": shear_payload,
    }
    st.session_state["_inputs_apply_refresh_cycle_latest"] = dict(combined_payload)
    return combined_payload


