def _browser_recipe_action_already_applied_on_inputs() -> bool:
    last_apply_route = st.session_state.get(DESIGN_GUIDE_LAST_APPLY_ROUTE_KEY)
    return bool(
        st.session_state.get("pending_recommendation_applied_id")
        or st.session_state.get("_inputs_action_apply_recommendation")
        or last_apply_route
    )


def _browser_recipe_hydrate_inputs_reo_widget_mirrors(reason: str) -> dict:
    """Test-mode audit for browser-recipe Inputs reo widget alignment.

    Streamlit disallows mutating widget keys after the widget is instantiated.
    The corresponding pre-widget hook below performs any required recipe reseed;
    this render-time hook only records drift and asks the normal pre-widget
    refresh path to reseed on the next natural rerun if needed.
    """
    if os.environ.get("CODEX_BROWSER_TEST_MODE", "").strip().lower() not in {"1", "true", "yes", "on"}:
        return {"applied": False, "reason": "browser_test_mode_disabled"}

    ss = st.session_state
    applied_state = ss.get("_browser_recipe_applied_state")
    if not isinstance(applied_state, dict) or not applied_state:
        return {"applied": False, "reason": "no_browser_recipe_applied_state"}

    if _browser_recipe_action_already_applied_on_inputs():
        return {"applied": False, "reason": "design_guide_action_already_applied"}

    widget_mirrors = _browser_recipe_inputs_reo_widget_mirror_map()
    drift: dict[str, dict[str, object]] = {}
    for shared_key, widget_keys in widget_mirrors.items():
        if shared_key not in applied_state:
            continue
        expected = copy.deepcopy(applied_state.get(shared_key))
        if shared_key in SHARED_DEFAULTS and ss.get(shared_key) != expected:
            drift[shared_key] = {
                "before": ss.get(shared_key),
                "after": expected,
                "kind": "shared",
            }
        for widget_key in widget_keys:
            before = ss.get(widget_key)
            if before != expected:
                drift[widget_key] = {
                    "before": before,
                    "after": expected,
                    "kind": "widget",
                    "shared_key": shared_key,
                }
    if drift:
        ss["_force_inputs_widget_reseed_once"] = True

    payload = {
        "applied": False,
        "reason": str(reason or "browser_recipe_inputs_widget_hydration"),
        "recipe": ss.get("_browser_recipe_applied_name"),
        "changed": {},
        "drift": drift,
        "mutation_skipped_after_render_start": True,
        "queued_pre_widget_reseed": bool(drift),
        "bottom_row_1": {
            "shared_db_bot_1": ss.get("db_bot_1"),
            "shared_bot_row_1_dia": ss.get("bot_row_1_dia"),
            "widget_inputs_db_bot_1": ss.get("inputs_db_bot_1"),
            "widget_inputs_bot_row_1_dia": ss.get("inputs_bot_row_1_dia"),
        },
    }
    ss["_browser_recipe_inputs_widget_hydration_audit"] = payload
    return payload


def _browser_recipe_reseed_inputs_reo_widget_mirrors_before_widgets(reason: str) -> dict:
    """Dev/test recipe reseed that runs before Inputs widgets are instantiated."""
    if os.environ.get("CODEX_BROWSER_TEST_MODE", "").strip().lower() not in {"1", "true", "yes", "on"}:
        return {"applied": False, "reason": "browser_test_mode_disabled"}

    ss = st.session_state
    applied_state = ss.get("_browser_recipe_applied_state")
    if not isinstance(applied_state, dict) or not applied_state:
        return {"applied": False, "reason": "no_browser_recipe_applied_state"}
    if _browser_recipe_action_already_applied_on_inputs():
        return {"applied": False, "reason": "design_guide_action_already_applied"}

    changed: dict[str, dict[str, object]] = {}
    drift: dict[str, dict[str, object]] = {}
    widget_mirrors = _browser_recipe_inputs_reo_widget_mirror_map()
    for shared_key, widget_keys in widget_mirrors.items():
        if shared_key not in applied_state:
            continue
        expected = copy.deepcopy(applied_state.get(shared_key))
        if shared_key in SHARED_DEFAULTS and ss.get(shared_key) != expected:
            before_shared = ss.get(shared_key)
            ss[shared_key] = expected
            changed[shared_key] = {
                "before": before_shared,
                "after": expected,
                "kind": "shared",
            }
        for widget_key in widget_keys:
            before = ss.get(widget_key)
            if before != expected:
                ss[widget_key] = copy.deepcopy(expected)
                changed[widget_key] = {
                    "before": before,
                    "after": expected,
                    "kind": "widget",
                    "shared_key": shared_key,
                }
            ss.pop(f"_cached_{widget_key}", None)
            drift[widget_key] = {
                "before": before,
                "after": expected,
                "kind": "widget",
                "shared_key": shared_key,
                "matched": before == expected,
            }

    hydrated_map = ss.get("_hydrated_from_shared_map")
    if isinstance(hydrated_map, dict):
        for key in changed:
            hydrated_map.pop(str(key), None)

    if changed:
        ss["_force_inputs_widget_reseed_once"] = False

    payload = {
        "applied": bool(changed),
        "reason": str(reason or "browser_recipe_inputs_pre_widget_reseed"),
        "recipe": ss.get("_browser_recipe_applied_name"),
        "changed": changed,
        "drift": drift,
        "mutation_skipped_after_render_start": False,
        "pre_widget_reseed": True,
        "bottom_row_1": {
            "shared_db_bot_1": ss.get("db_bot_1"),
            "shared_nb_or_s_bot_1": ss.get("nb_or_s_bot_1"),
            "shared_bot_row_1_bars": ss.get("bot_row_1_bars"),
            "shared_bot_row_1_dia": ss.get("bot_row_1_dia"),
            "widget_inputs_db_bot_1": ss.get("inputs_db_bot_1"),
            "widget_inputs_nb_or_s_bot_1": ss.get("inputs_nb_or_s_bot_1"),
            "widget_inputs_bot_row_1_bars": ss.get("inputs_bot_row_1_bars"),
            "widget_inputs_bot_row_1_dia": ss.get("inputs_bot_row_1_dia"),
        },
    }
    ss["_browser_recipe_inputs_widget_hydration_audit"] = payload
    return payload


def _wrap_longitudinal_reo_sync_callbacks(sync_callbacks: dict) -> dict:
    wrapped = dict(sync_callbacks or {})

    def _make_wrapper(widget_key: str, fn):
        def _wrapped_callback():
            fn()
            snapshot = _longitudinal_reo_widget_audit_snapshot(f"after_longitudinal_sync_callback:{widget_key}")
            callback_record = {
                "changed_widget": widget_key,
                "shared_row_model": dict(snapshot.get("shared_row_model") or {}),
                "inputs_widget_mirror": dict(snapshot.get("inputs_widget_mirror") or {}),
                "diff_summary": dict(snapshot.get("diff_summary") or {}),
            }
            callback_store = dict(st.session_state.get("_inputs_longitudinal_reo_callback_audit") or {})
            callback_history = list(callback_store.get("history") or [])
            callback_history.append(copy.deepcopy(callback_record))
            if len(callback_history) > 24:
                callback_history = callback_history[-24:]
            callback_store["latest"] = copy.deepcopy(callback_record)
            callback_store["history"] = callback_history
            st.session_state["_inputs_longitudinal_reo_callback_audit"] = callback_store
            try:
                _agent_debug_log(
                    "Inputs longitudinal reo sync callback audit",
                    callback_record,
                    location="inputs_page.py:_wrap_longitudinal_reo_sync_callbacks",
                    hypothesis_id="H_INPUTS_LONGITUDINAL_WIDGET_CALLBACK",
                )
            except Exception:
                pass
        return _wrapped_callback

    for widget_key, fn in list(wrapped.items()):
        if callable(fn) and _is_inputs_longitudinal_reo_widget_key(widget_key):
            wrapped[widget_key] = _make_wrapper(str(widget_key), fn)
    return wrapped

# s_lig / lig_d / lig_legs: active-page widget mirrors (inputs_* vs shear_*), not generic inputs_ overlay order.
_SHEAR_TRIPLE_DEFERRED_OVERLAY_KEYS = frozenset({"s_lig", "lig_d", "lig_legs"})


def _apply_active_page_shear_widget_mirror_overlay(
    working: dict,
    base: dict,
    overlay_applied: dict,
) -> dict:
    """
    Overlay live shear detailing mirrors onto lightweight state (summary / Design Guide).
    Render-only: does not write canonical shared s_lig / lig_d / lig_legs.

    Precedence: Inputs page -> inputs_*; Shear page -> shear_*; otherwise shared snapshot only.
    """
    slug = str(st.session_state.get("page_slug") or "")
    dbg = {
        "shear_widget_overlay_applied": False,
        "shear_widget_overlay_source": "shared_only",
        "overlay_s_lig": None,
        "overlay_lig_d": None,
        "overlay_lig_legs": None,
    }
    if slug == "inputs":
        pairs = (
            ("s_lig", "inputs_s_lig"),
            ("lig_d", "inputs_lig_d"),
            ("lig_legs", "inputs_lig_legs"),
        )
        dbg["shear_widget_overlay_source"] = "inputs"
    elif slug == "shear":
        pairs = (
            ("s_lig", "shear_s_lig"),
            ("lig_d", "shear_lig_d"),
            ("lig_legs", "shear_lig_legs"),
        )
        dbg["shear_widget_overlay_source"] = "shear"
    else:
        for sk in ("s_lig", "lig_d", "lig_legs"):
            working[sk] = base.get(sk)
        dbg["overlay_s_lig"] = working.get("s_lig")
        dbg["overlay_lig_d"] = working.get("lig_d")
        dbg["overlay_lig_legs"] = working.get("lig_legs")
        return dbg

    _read_any = False
    raw_widget_shear: dict[str, object] = {}
    for sk, wk in pairs:
        if wk not in st.session_state:
            continue
        wval = st.session_state.get(wk)
        if isinstance(wval, (dict, list, tuple, set)):
            continue
        _read_any = True
        raw_widget_shear[sk] = wval
        bval = base.get(sk)
        working[sk] = wval
        if bval != wval:
            overlay_applied[sk] = {"from": bval, "to": wval, "widget_key": wk}
    try:
        base_no_links = _int_from_state(base, "lig_legs", 0) <= 0 and _int_from_state(base, "lig_d", 0) <= 0
        candidate_lig_legs = _int_from_state(working, "lig_legs", 0)
        candidate_lig_d = _int_from_state(working, "lig_d", 0)
        if (
            slug == "inputs"
            and _read_any
            and base_no_links
            and (
                candidate_lig_legs > 0
                or candidate_lig_d > 0
                or float(_float_from_state(working, "s_lig", 0.0) or 0.0) > 0.0
            )
        ):
            for sk in ("s_lig", "lig_d", "lig_legs"):
                working[sk] = base.get(sk)
                overlay_applied.pop(sk, None)
            dbg["shear_widget_overlay_applied"] = False
            dbg["shear_widget_overlay_source"] = "inputs_stale_shear_overlay_suppressed_shared_no_links"
            dbg["overlay_s_lig"] = working.get("s_lig")
            dbg["overlay_lig_d"] = working.get("lig_d")
            dbg["overlay_lig_legs"] = working.get("lig_legs")
            return dbg
    except Exception:
        pass
    dbg["shear_widget_overlay_applied"] = bool(_read_any)
    dbg["overlay_s_lig"] = working.get("s_lig")
    dbg["overlay_lig_d"] = working.get("lig_d")
    dbg["overlay_lig_legs"] = working.get("lig_legs")
    return dbg


def _inputs_summary_should_use_shared_only() -> tuple[bool, str]:
    if bool(st.session_state.get("_applying_auto_design")):
        return True, "applying_auto_design"
    if bool(st.session_state.get("_force_inputs_widget_reseed_once")):
        return True, "force_inputs_widget_reseed_once"
    if bool(st.session_state.get("_pending_inputs_apply_refresh")):
        return True, "pending_inputs_apply_refresh"
    if bool(st.session_state.get("_inputs_longitudinal_reo_force_refresh_processed_this_run")):
        return True, "post_force_refresh_this_run"
    return False, "normal_overlay"


def _recompute_summary_local_derived_fields(state: dict) -> dict:
    """Pure local derived refresh for summary builders only (no shared/session writes)."""
    working = dict(state or {})
    working.update(build_legacy_longitudinal_mirrors_from_rows(working))
    ctx = _build_design_actions_context_isolated(working)
    resolved = dict(ctx.get("state") or _guidance_state_snapshot(working))
    resolved.update(build_legacy_longitudinal_mirrors_from_rows(resolved))
    bottom_updates = _candidate_bottom_updates(resolved)
    resolved = _candidate_state_with_effective_bottom_for_overview(resolved, bottom_updates)
    resolved.update(build_legacy_longitudinal_mirrors_from_rows(resolved))
    return resolved


def _design_guide_lightweight_guidance_state(incoming: dict | None) -> dict:
    """
    Resolved state for Design Guide / guidance overview without
    ``_build_canonical_design_state_pack`` (no deep reo layout + bar resolution).
    """
    base_line = _guidance_state_snapshot(_shared_state_snapshot())
    raw = _guidance_state_snapshot(dict(incoming or {}))
    working = dict(raw)
    working.update(build_legacy_longitudinal_mirrors_from_rows(working))
    shared_only_mode, _shared_only_reason = _inputs_summary_should_use_shared_only()
    if not shared_only_mode:
        _apply_active_page_shear_widget_mirror_overlay(working, base_line, {})
    resolved = _recompute_summary_local_derived_fields(working)
    resolved.update(build_legacy_longitudinal_mirrors_from_rows(resolved))
    return _overlay_current_normalized_shear_truth(resolved)


def _resolved_inputs_summary_state() -> tuple[dict, dict]:
    """
    Pure summary-only state: shared snapshot + current inputs_* widget overlays.
    Returns (summary_state, compact_debug).
    """
    base = _guidance_state_snapshot(_shared_state_snapshot())
    working = dict(base)
    shared_only_mode, shared_only_reason = _inputs_summary_should_use_shared_only()
    overlay_applied: dict[str, dict] = {}
    if not shared_only_mode:
        for shared_key, widget_key in INPUTS_PAGE_TAB_KEYS.items():
            sk = str(shared_key or "")
            wk = str(widget_key or "")
            if not sk or not wk.startswith("inputs_"):
                continue
            if (
                sk.startswith("_")
                or sk in _SUMMARY_OVERLAY_SKIP_SHARED_KEYS
                or sk in _SUMMARY_OVERLAY_SKIP_LONGITUDINAL_KEYS
                or sk.startswith(_SUMMARY_OVERLAY_SKIP_PREFIXES)
            ):
                continue
            if sk in _SHEAR_TRIPLE_DEFERRED_OVERLAY_KEYS:
                continue
            if wk not in st.session_state:
                continue
            wval = st.session_state.get(wk)
            if isinstance(wval, (dict, list, tuple, set)):
                continue
            bval = base.get(sk)
            if bval != wval:
                overlay_applied[sk] = {"from": bval, "to": wval, "widget_key": wk}
            working[sk] = wval

    if shared_only_mode:
        _shear_ov_dbg = {
            "shear_widget_overlay_applied": False,
            "shear_widget_overlay_source": "shared_only_suppressed",
            "overlay_s_lig": working.get("s_lig"),
            "overlay_lig_d": working.get("lig_d"),
            "overlay_lig_legs": working.get("lig_legs"),
        }
    else:
        _shear_ov_dbg = _apply_active_page_shear_widget_mirror_overlay(working, base, overlay_applied)
    working.update(build_legacy_longitudinal_mirrors_from_rows(working))
    resolved = _recompute_summary_local_derived_fields(working)
    resolved.update(build_legacy_longitudinal_mirrors_from_rows(resolved))
    resolved = _overlay_current_normalized_shear_truth(resolved)

    subset_keys = (
        "b", "D", "fc", "fsy",
        "uls_Mstar", "Mu_star", "uls_Vstar", "Vu_star", "Tu_star",
        "bot1_count", "bot2_count", "db_bot_1", "db_bot_2",
        "lig_d", "lig_legs", "s_lig",
        "Ast_bot", "d",
    )
    compact_diffs: dict[str, dict] = {}
    for k in subset_keys:
        if k in overlay_applied:
            compact_diffs[k] = dict(overlay_applied[k])
        elif base.get(k) != resolved.get(k):
            compact_diffs[k] = {"from": base.get(k), "to": resolved.get(k), "widget_key": None}

    debug_payload = {
        "summary_uses_resolved_inputs_state": True,
        "summary_state_source": "shared_only_canonical_state" if shared_only_mode else "shared_plus_inputs_widget_overlay",
        "summary_render_state_source": "lightweight_overlay_state",
        "summary_cache_fp_source": "resolved_inputs_summary_state",
        "summary_shared_vs_widget_diffs": compact_diffs,
        "overlay_count": len(overlay_applied),
        "summary_shared_only_mode": bool(shared_only_mode),
        "summary_shared_only_reason": shared_only_reason,
        "summary_overlay_suppressed": bool(shared_only_mode),
        "shear_widget_overlay_applied": _shear_ov_dbg.get("shear_widget_overlay_applied"),
        "shear_widget_overlay_source": _shear_ov_dbg.get("shear_widget_overlay_source"),
        "overlay_s_lig": _shear_ov_dbg.get("overlay_s_lig"),
        "overlay_lig_d": _shear_ov_dbg.get("overlay_lig_d"),
        "overlay_lig_legs": _shear_ov_dbg.get("overlay_lig_legs"),
        "summary_shear_widget_overlay_applied": _shear_ov_dbg.get("shear_widget_overlay_applied"),
        "summary_overlay_s_lig": _shear_ov_dbg.get("overlay_s_lig"),
        "summary_overlay_lig_d": _shear_ov_dbg.get("overlay_lig_d"),
        "summary_overlay_lig_legs": _shear_ov_dbg.get("overlay_lig_legs"),
        "summary_pack_cache_design_guide_fp": _get_design_guide_fp(resolved),
        "longitudinal_reo_truth_source": resolved.get("longitudinal_reo_truth_source"),
        "row_model_legacy_sync_applied": bool(resolved.get("row_model_legacy_sync_applied")),
        "row_model_legacy_sync_diff_keys": list(resolved.get("row_model_legacy_sync_diff_keys") or []),
    }
    st.session_state["_inputs_summary_state_mode"] = {
        "shared_only_mode": bool(shared_only_mode),
        "reason": shared_only_reason,
        "overlay_count": len(overlay_applied),
        "shared_shear": {
            "s_lig": base.get("s_lig"),
            "lig_d": base.get("lig_d"),
            "lig_legs": base.get("lig_legs"),
        },
        "widget_shear": {
            "inputs_s_lig": st.session_state.get("inputs_s_lig"),
            "inputs_lig_d": st.session_state.get("inputs_lig_d"),
            "inputs_lig_legs": st.session_state.get("inputs_lig_legs"),
        },
    }
    ux_probe_record(
        "inputs_page.summary_state_build",
        fingerprint=stable_fingerprint_for_payload(resolved),
        meta={
            "shared_only_mode": bool(shared_only_mode),
            "overlay_count": len(overlay_applied),
        },
    )
    return resolved, debug_payload


def _resolved_inputs_model_state() -> tuple[dict, dict]:
    """
    Overlay-aware current Inputs model state for fast model rendering.
    Mirrors the same current-state truth rules used by summary / Design Guide.
    """
    resolved, summary_debug = _resolved_inputs_summary_state()
    resolved, model_widget_debug = _overlay_inputs_reo_widget_mirrors_for_model(
        resolved,
        summary_debug=summary_debug,
    )
    debug_payload = {
        "model_state_source": "resolved_inputs_model_state",
        "model_overlay_s_lig": summary_debug.get("summary_overlay_s_lig"),
        "model_overlay_lig_d": summary_debug.get("summary_overlay_lig_d"),
        "model_overlay_lig_legs": summary_debug.get("summary_overlay_lig_legs"),
        "model_shared_only_mode": bool(summary_debug.get("summary_shared_only_mode")),
        "model_shared_only_reason": summary_debug.get("summary_shared_only_reason"),
        "fast_model_uses_overlay_state": True,
        "fast_model_overlay_lig_d": summary_debug.get("summary_overlay_lig_d"),
        "fast_model_overlay_lig_legs": summary_debug.get("summary_overlay_lig_legs"),
        "fast_model_overlay_s_lig": summary_debug.get("summary_overlay_s_lig"),
        "fast_model_fingerprint_includes_shear": True,
        **dict(model_widget_debug or {}),
    }
    return dict(resolved), debug_payload


def _overlay_inputs_reo_widget_mirrors_for_model(
    state: dict,
    *,
    summary_debug: dict | None = None,
) -> tuple[dict, dict]:
    """Use current Inputs row widgets for the visual model only.

    Summary and Design Guide intentionally keep their stricter refresh guards.
    The fast SVG model is a live visual mirror, so it can safely use the current
    row widgets after those widgets have mounted without publishing guidance truth.
    """
    working = dict(state or {})
    debug = {
        "fast_model_reo_widget_overlay_applied": False,
        "fast_model_reo_widget_overlay_count": 0,
        "fast_model_reo_widget_overlay_keys": [],
        "fast_model_reo_widget_overlay_suppressed": False,
    }
    if str(st.session_state.get("page_slug") or "") != "inputs":
        debug["fast_model_reo_widget_overlay_suppressed"] = True
        debug["fast_model_reo_widget_overlay_reason"] = "not_inputs_page"
        return working, debug
    summary_shared_only_reason = str(
        (summary_debug or {}).get("summary_shared_only_reason") or ""
    )
    if (
        bool((summary_debug or {}).get("summary_shared_only_mode"))
        and summary_shared_only_reason != "post_force_refresh_this_run"
    ):
        debug["fast_model_reo_widget_overlay_suppressed"] = True
        debug["fast_model_reo_widget_overlay_reason"] = summary_shared_only_reason or "summary_shared_only_mode"
        return working, debug

    overlay_keys: list[str] = []

    def _overlay_scalar(shared_key: str, widget_key: str, coerce):
        if widget_key not in st.session_state:
            return
        raw_value = st.session_state.get(widget_key)
        if isinstance(raw_value, (dict, list, tuple, set)):
            return
        try:
            value = coerce(raw_value)
        except Exception:
            return
        if working.get(shared_key) != value:
            overlay_keys.append(shared_key)
        working[shared_key] = value

    for section in ("bot", "top"):
        _overlay_scalar(
            f"{section}_row_count",
            f"inputs_{section}_row_count",
            lambda value: max(1, int(float(value or 1))),
        )
        for row_index in range(1, 5):
            prefix = f"{section}_row_{row_index}"
            widget_prefix = f"inputs_{section}_row_{row_index}"
            _overlay_scalar(f"{prefix}_mode", f"{widget_prefix}_mode", lambda value: str(value or "Count"))
            _overlay_scalar(f"{prefix}_bars", f"{widget_prefix}_bars", lambda value: max(0, int(float(value or 0))))
            _overlay_scalar(f"{prefix}_spacing", f"{widget_prefix}_spacing", lambda value: max(0.0, float(value or 0.0)))
            _overlay_scalar(f"{prefix}_dia", f"{widget_prefix}_dia", lambda value: max(0.0, float(value or 0.0)))

    def _coords_stale_for(section: str, legacy_prefix: str) -> bool:
        coord_key = "bot_bar_coords" if section == "bot" else "top_bar_coords"
        coords = working.get(coord_key)
        if not isinstance(coords, list):
            coords = []
        try:
            b_current = max(0.0, float(working.get("b", 0.0) or 0.0))
            d_current = max(0.0, float(working.get("D", 0.0) or 0.0))
        except Exception:
            b_current = 0.0
            d_current = 0.0
        row_count = max(1, int(float(working.get(f"{section}_row_count", 1) or 1)))
        expected_total = 0
        expected_dias: set[float] = set()
        for row_index in range(1, min(row_count, 4) + 1):
            count = max(
                0,
                int(
                    float(
                        working.get(
                            f"{section}_row_{row_index}_bars",
                            working.get(f"{legacy_prefix}{row_index}_count", 0),
                        )
                        or 0
                    )
                ),
            )
            expected_total += count
            if count > 0:
                try:
                    expected_dias.add(
                        float(
                            working.get(
                                f"{section}_row_{row_index}_dia",
                                working.get(f"db_{legacy_prefix}_{row_index}", 0.0),
                            )
                            or 0.0
                        )
                    )
                except Exception:
                    pass
        if expected_total > 0 and len(coords) != expected_total:
            return True
        if expected_dias and coords:
            coord_dias = {
                float((coord or {}).get("db", 0.0) or 0.0)
                for coord in coords
                if isinstance(coord, dict)
            }
            if coord_dias and not coord_dias.issubset(expected_dias):
                return True
        for coord in coords:
            if not isinstance(coord, dict):
                continue
            try:
                x = float(coord.get("x", 0.0) or 0.0)
                y = float(coord.get("y", 0.0) or 0.0)
                db = max(0.0, float(coord.get("db", 0.0) or 0.0))
            except Exception:
                return True
            if (
                x - db / 2.0 < -1e-6
                or x + db / 2.0 > b_current + 1e-6
                or y - db / 2.0 < -1e-6
                or y + db / 2.0 > d_current + 1e-6
            ):
                return True
        return False

    coord_stale_keys: list[str] = []
    if _coords_stale_for("bot", "bot"):
        coord_stale_keys.append("bot_bar_coords_stale")
    if _coords_stale_for("top", "top"):
        coord_stale_keys.append("top_bar_coords_stale")
    overlay_keys.extend(coord_stale_keys)

    if overlay_keys:
        working.update(build_legacy_longitudinal_mirrors_from_rows(working))
        pack_failed = False
        try:
            canonical_pack = _build_canonical_design_state_pack(working)
            if isinstance(canonical_pack, dict):
                working.update(canonical_pack)
        except Exception:
            pack_failed = True
            debug["fast_model_reo_widget_overlay_pack_failed"] = True
        working.update(build_legacy_longitudinal_mirrors_from_rows(working))
        for section, legacy_prefix in (("bot", "bot"), ("top", "top")):
            for row_index in (1, 2):
                bars_key = f"{section}_row_{row_index}_bars"
                dia_key = f"{section}_row_{row_index}_dia"
                working[f"{legacy_prefix}{row_index}_count"] = max(
                    0,
                    int(float(working.get(bars_key, working.get(f"{legacy_prefix}{row_index}_count", 0)) or 0)),
                )
                working[f"db_{legacy_prefix}_{row_index}"] = max(
                    0.0,
                    float(working.get(dia_key, working.get(f"db_{legacy_prefix}_{row_index}", 0.0)) or 0.0),
                )
        if pack_failed and any(str(key).startswith("bot_row_") or key == "bot_bar_coords_stale" for key in overlay_keys):
            working["bot_bar_coords"] = []
        if pack_failed and any(str(key).startswith("top_row_") or key == "top_bar_coords_stale" for key in overlay_keys):
            working["top_bar_coords"] = []
        debug["fast_model_reo_widget_overlay_applied"] = True
        debug["fast_model_reo_widget_overlay_count"] = len(set(overlay_keys))
        debug["fast_model_reo_widget_overlay_keys"] = sorted(set(overlay_keys))
    return working, debug

def _canonical_shape_name_and_dims(state: dict) -> tuple[str, dict]:
    sec_shape = str(state.get("sec_shape", "RECT") or "RECT")
    if sec_shape == "T":
        return "T-Section", {
            "bf": float(state.get("bf", state.get("b", 0.0)) or 0.0),
            "tf": float(state.get("tf", 0.0) or 0.0),
            "bw": float(state.get("bw", state.get("b", 0.0)) or 0.0),
            "D": float(state.get("D", 0.0) or 0.0),
        }
    if sec_shape == "I":
        return "I-Section", {
            "bf_top": float(state.get("bf", state.get("b", 0.0)) or 0.0),
            "tf_top": float(state.get("tf", 0.0) or 0.0),
            "bf_bot": float(state.get("bf_bot", state.get("bf", state.get("b", 0.0))) or 0.0),
            "tf_bot": float(state.get("tf_bot", state.get("tf", 0.0)) or 0.0),
            "bw": float(state.get("tw", state.get("bw", state.get("b", 0.0))) or 0.0),
            "D": float(state.get("D", 0.0) or 0.0),
        }
    return "Rectangle (b × D)", {
        "b": float(state.get("b", 0.0) or 0.0),
        "D": float(state.get("D", 0.0) or 0.0),
    }


def _canonical_rows_from_reo_layout(reo_layout: dict, layer_name: str) -> list[dict]:
    rows: list[dict] = []
    for idx, layer_data in enumerate((reo_layout.get(layer_name) or []), start=1):
        if not isinstance(layer_data, dict):
            continue
        xs = [float(x) for x in (layer_data.get("x") or [])]
        db = float(layer_data.get("db", 0.0) or 0.0)
        yv = layer_data.get("y", 0.0)
        y = float((yv[0] if isinstance(yv, list) and yv else yv) or 0.0)
        rows.append(
            {
                "active": bool(xs and db > 0.0),
                "row_index": int(layer_data.get("row_index", idx) or idx),
                "mode": str(layer_data.get("mode", "Count") or "Count"),
                "dia": db,
                "bar_count_resolved": len(xs),
                "spacing_resolved": float(layer_data.get("spacing_actual", 0.0) or 0.0),
                "x_positions": xs,
                "y_position": y,
                "steel_area_row": float(layer_data.get("steel_area", len(xs) * math.pi * db**2 / 4.0) or 0.0),
                "fit_ok": bool(layer_data.get("fit_ok", True)),
                "warning": layer_data.get("warning"),
            },
        )
    return rows


def _invalid_canonical_design_state_pack(
    raw: dict,
    *,
    error: str,
    error_stage: str,
) -> dict:
    """Fail-soft canonical pack for malformed / no-bars design states."""
    out = dict(raw or {})
    D = float(raw.get("D", 0.0) or 0.0)
    cover_top = float(raw.get("cover_top", 0.0) or 0.0)
    cover_bot = float(raw.get("cover_bot", 0.0) or 0.0)
    lig_d = float(raw.get("lig_d", 0.0) or 0.0)
    out.update(
        {
            "bot_rows_resolved": [],
            "top_rows_resolved": [],
            "bot_bar_coords": [],
            "top_bar_coords": [],
            "resolved_longitudinal_bars": [],
            "Ast_top_web": 0.0,
            "Ast_top_flange": 0.0,
            "Ast_bottom_web": 0.0,
            "Ast_bottom_flange": 0.0,
            "Ast_top": 0.0,
            "Ast_bot": 0.0,
            "nb_bot": 0,
            "nb_top": 0,
            "db_bot": 0.0,
            "db_top": 0.0,
            "d": effective_depth_with_links_mm(
                D_mm=D,
                cover_to_ligs_mm=cover_bot,
                lig_diameter_mm=lig_d,
                bar_diameter_mm=0.0,
            ),
            "do": float(D - cover_top),
            "canonical_pack_built": False,
            "canonical_pack_valid": False,
            "canonical_pack_source": "shared_rebuilt_failed",
            "canonical_pack_error": str(error),
            "canonical_pack_error_stage": str(error_stage),
        },
    )
    return out


def _canonical_pack_is_valid(pack: dict | None) -> bool:
    p = dict(pack or {})
    if "canonical_pack_valid" in p:
        return bool(p.get("canonical_pack_valid"))
    return bool(p.get("canonical_pack_built", False))


def _build_canonical_design_state_pack(state: dict) -> dict:
    """Pure canonical design-state pack from raw/shared-like state."""
    raw = _guidance_state_snapshot(dict(state or {}))
    raw_synced = dict(raw)
    raw_synced.update(build_legacy_longitudinal_mirrors_from_rows(raw_synced))
    out = dict(raw_synced)
    shape_name, dims = _canonical_shape_name_and_dims(raw_synced)
    cover_top = float(raw_synced.get("cover_top", 0.0) or 0.0)
    cover_bot = float(raw_synced.get("cover_bot", 0.0) or 0.0)
    cover_side = float(raw_synced.get("cover_side", 0.0) or 0.0)
    rowgap_top = float(raw_synced.get("rowgap_top", 0.0) or 0.0)
    rowgap_bot = float(raw_synced.get("rowgap_bot", 0.0) or 0.0)
    lig_d = float(raw_synced.get("lig_d", 0.0) or 0.0)
    lig_legs = int(raw_synced.get("lig_legs", 2) or 2)
    min_clear_spacing = float(raw_synced.get("min_clear_spacing", 20.0) or 20.0)
    reo_layout: dict = {}
    try:
        if shape_name in ("T-Section", "I-Section"):
            reo_layout = compute_longitudinal_reo_layout_T_I(
                shape_name=shape_name,
                dims=dims,
                cover_side=cover_side,
                cover_top=cover_top,
                cover_bot=cover_bot,
                min_clear_spacing=min_clear_spacing,
                rowgap_top=rowgap_top,
                rowgap_bot=rowgap_bot,
                reo=raw_synced,
            )
        else:
            sec = compute_section_layout_pure(
                b=float(raw_synced.get("b", 0.0) or 0.0),
                D=float(raw_synced.get("D", 0.0) or 0.0),
                cover_bot=cover_bot,
                cover_top=cover_top,
                cover_side=cover_side,
                nb_or_s_bot_1=float(raw_synced.get("bot1_count", raw_synced.get("nb_bot_1", 0.0)) or 0.0),
                db_bot_1=float(raw_synced.get("db_bot_1", 0.0) or 0.0),
                nb_or_s_bot_2=float(raw_synced.get("bot2_count", raw_synced.get("nb_bot_2", 0.0)) or 0.0),
                db_bot_2=float(raw_synced.get("db_bot_2", raw_synced.get("db_bot_1", 0.0)) or 0.0),
                nb_or_s_top_1=float(raw_synced.get("top1_count", raw_synced.get("nb_top_1", 0.0)) or 0.0),
                db_top_1=float(raw_synced.get("db_top_1", 0.0) or 0.0),
                nb_or_s_top_2=float(raw_synced.get("top2_count", raw_synced.get("nb_top_2", 0.0)) or 0.0),
                db_top_2=float(raw_synced.get("db_top_2", raw_synced.get("db_top_1", 0.0)) or 0.0),
                rowgap_bot=rowgap_bot,
                rowgap_top=rowgap_top,
                lig_legs=lig_legs,
                lig_d=lig_d,
                bottom_rows=get_longitudinal_row_inputs("bot", source=raw_synced),
                top_rows=get_longitudinal_row_inputs("top", source=raw_synced),
            )
            reo_layout = dict(sec.get("reo_layout", {}) or {})
    except Exception:
        reo_layout = {}
    if not isinstance(reo_layout, dict):
        reo_layout = {}
    if not reo_layout:
        return _invalid_canonical_design_state_pack(
            raw_synced,
            error="no_bars_resolved",
            error_stage="reo_layout_empty",
        )
    try:
        bars = resolve_longitudinal_bars_from_layout(shape_name=shape_name, dims=dims, reo_layout=reo_layout)
    except AssertionError as exc:
        if "no bars resolved" in str(exc).lower():
            return _invalid_canonical_design_state_pack(
                raw_synced,
                error="no_bars_resolved",
                error_stage="resolve_longitudinal_bars",
            )
        return _invalid_canonical_design_state_pack(
            raw_synced,
            error="canonical_pack_failed",
            error_stage="resolve_longitudinal_bars",
        )
    except Exception:
        return _invalid_canonical_design_state_pack(
            raw_synced,
            error="canonical_pack_failed",
            error_stage="resolve_longitudinal_bars",
        )
    if not bars:
        return _invalid_canonical_design_state_pack(
            raw_synced,
            error="no_bars_resolved",
            error_stage="resolve_longitudinal_bars",
        )
    bot_rows = _canonical_rows_from_reo_layout(reo_layout, "bottom")
    top_rows = _canonical_rows_from_reo_layout(reo_layout, "top")
    out["bot_rows_resolved"] = bot_rows
    out["top_rows_resolved"] = top_rows
    out["bot_bar_coords"] = [{"x": x, "y": r["y_position"], "db": r["dia"], "row_index": r["row_index"]} for r in bot_rows for x in r.get("x_positions", [])]
    out["top_bar_coords"] = [{"x": x, "y": r["y_position"], "db": r["dia"], "row_index": r["row_index"]} for r in top_rows for x in r.get("x_positions", [])]
    out["resolved_longitudinal_bars"] = list(bars or [])
    top_bars = [bar for bar in bars if str(bar.get("face")) == "top"]
    bottom_bars = [bar for bar in bars if str(bar.get("face")) == "bottom"]
    out["Ast_top_web"] = float(sum(float(bar.get("area_mm2", 0.0) or 0.0) for bar in top_bars if "web" in str(bar.get("zone", ""))))
    out["Ast_top_flange"] = float(sum(float(bar.get("area_mm2", 0.0) or 0.0) for bar in top_bars if "flange" in str(bar.get("zone", ""))))
    out["Ast_bottom_web"] = float(sum(float(bar.get("area_mm2", 0.0) or 0.0) for bar in bottom_bars if "web" in str(bar.get("zone", ""))))
    out["Ast_bottom_flange"] = float(sum(float(bar.get("area_mm2", 0.0) or 0.0) for bar in bottom_bars if "flange" in str(bar.get("zone", ""))))
    out["Ast_top"] = float(out["Ast_top_web"] + out["Ast_top_flange"])
    out["Ast_bot"] = float(out["Ast_bottom_web"] + out["Ast_bottom_flange"])
    out["nb_bot"] = int(sum(int(r.get("bar_count_resolved", 0) or 0) for r in bot_rows))
    out["nb_top"] = int(sum(int(r.get("bar_count_resolved", 0) or 0) for r in top_rows))
    out["db_bot"] = float(max((float(bar.get("dia_mm", 0.0) or 0.0) for bar in bottom_bars), default=0.0))
    out["db_top"] = float(max((float(bar.get("dia_mm", 0.0) or 0.0) for bar in top_bars), default=0.0))
    primary_bot = next((r for r in bot_rows if r.get("active")), None)
    primary_top = next((r for r in top_rows if r.get("active")), None)
    bar_dia = float(primary_bot.get("dia", out.get("db_bot_1", 0.0)) if primary_bot else out.get("db_bot_1", 0.0) or 0.0)
    D = float(raw_synced.get("D", 0.0) or 0.0)
    out["d"] = effective_depth_with_links_mm(D_mm=D, cover_to_ligs_mm=cover_bot, lig_diameter_mm=lig_d, bar_diameter_mm=bar_dia)
    out["do"] = float(D - float(primary_top.get("y_position", 0.0) if primary_top else (cover_top + float(out.get("db_top_1", 0.0) or 0.0) / 2.0)))
    out["canonical_pack_built"] = True
    out["canonical_pack_valid"] = True
    out["canonical_pack_source"] = "shared_rebuilt"
    out["canonical_pack_error"] = None
    out["canonical_pack_error_stage"] = None
    return out


def _design_state_coherence_check(state: dict) -> dict:
    """Compact coherence checker for raw vs derived/resolved reinforcement state."""
    s = dict(state or {})
    hard_invalid_issues: list[str] = []
    soft_mismatch_issues: list[str] = []

    def _append_issue(bucket: list[str], issue: str | None) -> None:
        label = str(issue or "").strip()
        if label and label not in bucket:
            bucket.append(label)

    canonical_pack_error = str(s.get("canonical_pack_error") or "").strip()
    if "canonical_pack_valid" in s and not _canonical_pack_is_valid(s):
        _append_issue(hard_invalid_issues, canonical_pack_error or "canonical_pack_invalid")
    elif canonical_pack_error:
        _append_issue(hard_invalid_issues, canonical_pack_error)

    positive_required_fields = (
        ("b", "missing_or_invalid_b"),
        ("D", "missing_or_invalid_D"),
        ("fc", "missing_or_invalid_fc"),
        ("fsy", "missing_or_invalid_fsy"),
    )
    for field_name, issue_name in positive_required_fields:
        try:
            field_value = float(s.get(field_name, 0.0) or 0.0)
        except (TypeError, ValueError):
            field_value = 0.0
        if field_value <= 0.0:
            _append_issue(hard_invalid_issues, issue_name)

    nonnegative_required_fields = (
        ("cover_top", "negative_cover_top"),
        ("cover_bot", "negative_cover_bot"),
        ("lig_d", "negative_lig_d"),
    )
    for field_name, issue_name in nonnegative_required_fields:
        try:
            field_value = float(s.get(field_name, 0.0) or 0.0)
        except (TypeError, ValueError):
            field_value = 0.0
        if field_value < 0.0:
            _append_issue(hard_invalid_issues, issue_name)

    raw_bottom_signature = {
        "bot1_count": int(s.get("bot1_count", 0) or 0),
        "bot2_count": int(s.get("bot2_count", 0) or 0),
        "db_bot_1": float(s.get("db_bot_1", 0.0) or 0.0),
        "db_bot_2": float(s.get("db_bot_2", s.get("db_bot_1", 0.0)) or 0.0),
        "raw_total_bars": int(s.get("bot1_count", 0) or 0) + int(s.get("bot2_count", 0) or 0),
    }
    raw_top_signature = {
        "top1_count": int(s.get("top1_count", 0) or 0),
        "top2_count": int(s.get("top2_count", 0) or 0),
        "db_top_1": float(s.get("db_top_1", 0.0) or 0.0),
        "db_top_2": float(s.get("db_top_2", s.get("db_top_1", 0.0)) or 0.0),
        "raw_total_bars": int(s.get("top1_count", 0) or 0) + int(s.get("top2_count", 0) or 0),
    }
    bot_rows = list(s.get("bot_rows_resolved") or [])
    top_rows = list(s.get("top_rows_resolved") or [])
    resolved_total = int(sum(int((r or {}).get("bar_count_resolved", 0) or 0) for r in bot_rows))
    resolved_top_total = int(sum(int((r or {}).get("bar_count_resolved", 0) or 0) for r in top_rows))
    resolved_bottom_signature = {
        "resolved_total_bars": resolved_total,
        "resolved_dias": [float((r or {}).get("dia", 0.0) or 0.0) for r in bot_rows if int((r or {}).get("bar_count_resolved", 0) or 0) > 0],
        "Ast_bot": float(s.get("Ast_bot", 0.0) or 0.0),
    }
    resolved_top_signature = {
        "resolved_total_bars": resolved_top_total,
        "resolved_dias": [float((r or {}).get("dia", 0.0) or 0.0) for r in top_rows if int((r or {}).get("bar_count_resolved", 0) or 0) > 0],
        "Ast_top": float(s.get("Ast_top", 0.0) or 0.0),
    }
    is_canonical_state = bool(s.get("canonical_pack_built")) or ("canonical_pack_valid" in s) or bool(canonical_pack_error)
    if is_canonical_state:
        has_any_resolved_bars = bool(
            list(s.get("resolved_longitudinal_bars") or [])
            or resolved_total > 0
            or resolved_top_total > 0
        )
        if not has_any_resolved_bars:
            _append_issue(hard_invalid_issues, "no_bars_resolved")
    if raw_bottom_signature["raw_total_bars"] > 0 and resolved_total != raw_bottom_signature["raw_total_bars"]:
        _append_issue(soft_mismatch_issues, "bottom_bar_count_mismatch_raw_vs_resolved")
    if raw_top_signature["raw_total_bars"] > 0 and resolved_top_total != raw_top_signature["raw_total_bars"]:
        _append_issue(soft_mismatch_issues, "top_bar_count_mismatch_raw_vs_resolved")
    bars = list(s.get("resolved_longitudinal_bars") or [])
    bottom_bars = [bar for bar in bars if str(bar.get("face")) == "bottom"]
    top_bars = [bar for bar in bars if str(bar.get("face")) == "top"]
    resolved_ast = float(sum(float(bar.get("area_mm2", 0.0) or 0.0) for bar in bottom_bars))
    resolved_ast_top = float(sum(float(bar.get("area_mm2", 0.0) or 0.0) for bar in top_bars))
    if bottom_bars and abs(float(s.get("Ast_bot", 0.0) or 0.0) - resolved_ast) > 1e-3:
        _append_issue(soft_mismatch_issues, "Ast_bot_mismatch_vs_resolved_longitudinal_bars")
    if top_bars and abs(float(s.get("Ast_top", 0.0) or 0.0) - resolved_ast_top) > 1e-3:
        _append_issue(soft_mismatch_issues, "Ast_top_mismatch_vs_resolved_longitudinal_bars")
    if bars and bot_rows and resolved_total != len(bottom_bars):
        _append_issue(soft_mismatch_issues, "resolved_longitudinal_bars_mismatch_vs_row_model")
    if bars and top_rows and resolved_top_total != len(top_bars):
        _append_issue(soft_mismatch_issues, "resolved_top_longitudinal_bars_mismatch_vs_row_model")
    expected_d = effective_depth_with_links_mm(
        D_mm=float(s.get("D", 0.0) or 0.0),
        cover_to_ligs_mm=float(s.get("cover_bot", 0.0) or 0.0),
        lig_diameter_mm=float(s.get("lig_d", 0.0) or 0.0),
        bar_diameter_mm=float(s.get("db_bot_1", 0.0) or 0.0),
    )
    try:
        actual_d = float(s.get("d", 0.0) or 0.0)
    except (TypeError, ValueError):
        actual_d = 0.0
    if actual_d <= 0.0:
        _append_issue(hard_invalid_issues, "missing_or_invalid_effective_depth_d")
    if abs(actual_d - expected_d) > 1.0:
        _append_issue(soft_mismatch_issues, "effective_depth_d_inconsistent")
    D = float(s.get("D", 0.0) or 0.0)
    primary_top_y = next((float((r or {}).get("y_position", 0.0) or 0.0) for r in top_rows if (r or {}).get("active")), None)
    if primary_top_y is not None:
        expected_do = float(D - primary_top_y)
    else:
        expected_do = float(D - float(s.get("cover_top", 0.0) or 0.0) - float(s.get("db_top_1", 0.0) or 0.0) / 2.0)
    try:
        actual_do = float(s.get("do", 0.0) or 0.0)
    except (TypeError, ValueError):
        actual_do = 0.0
    if actual_do <= 0.0:
        _append_issue(hard_invalid_issues, "missing_or_invalid_do")
    if abs(actual_do - expected_do) > 1.0:
        _append_issue(soft_mismatch_issues, "do_inconsistent")
    issues = list(hard_invalid_issues) + list(soft_mismatch_issues)
    return {
        "coherence_ok": len(issues) == 0,
        "issues": issues,
        "hard_invalid_issues": list(hard_invalid_issues),
        "soft_mismatch_issues": list(soft_mismatch_issues),
        "coherence_blocking_issues": list(hard_invalid_issues),
        "coherence_nonblocking_issues": list(soft_mismatch_issues),
        "coherence_should_block": len(hard_invalid_issues) > 0,
        "state_coherence_warning": len(soft_mismatch_issues) > 0,
        "state_coherence_warning_issues": list(soft_mismatch_issues),
        "raw_bottom_signature": raw_bottom_signature,
        "resolved_bottom_signature": resolved_bottom_signature,
        "raw_top_signature": raw_top_signature,
        "resolved_top_signature": resolved_top_signature,
    }


def _coherence_debug_fields(coherence: dict | None) -> dict:
    c = dict(coherence or {})
    blocking_issues = list(c.get("coherence_blocking_issues") or [])
    nonblocking_issues = list(c.get("coherence_nonblocking_issues") or [])
    should_block = bool(c.get("coherence_should_block"))
    return {
        "state_coherence_ok": bool(c.get("coherence_ok")),
        "state_coherence_issues": list(c.get("issues") or []),
        "hard_invalid_issues": list(c.get("hard_invalid_issues") or blocking_issues),
        "soft_mismatch_issues": list(c.get("soft_mismatch_issues") or nonblocking_issues),
        "coherence_blocking_issues": blocking_issues,
        "coherence_nonblocking_issues": nonblocking_issues,
        "coherence_should_block": should_block,
        "state_coherence_warning": bool(nonblocking_issues),
        "state_coherence_warning_issues": list(c.get("state_coherence_warning_issues") or nonblocking_issues),
        "blocked_state_class": "hard_invalid" if should_block else None,
        "raw_bottom_signature": dict(c.get("raw_bottom_signature") or {}),
        "resolved_bottom_signature": dict(c.get("resolved_bottom_signature") or {}),
        "raw_top_signature": dict(c.get("raw_top_signature") or {}),
        "resolved_top_signature": dict(c.get("resolved_top_signature") or {}),
    }


RESULT_CACHE_KEY = "cached_results"

# Landing card (empty dashboard) — scroll handoff for "Go to Design Inputs"
_INPUTS_SCROLL_DESIGN_ACTIONS_FLAG = "_inputs_pending_scroll_design_actions"
# Must match app.PENDING_NAV_PAGE_SLUG_KEY (inputs_page cannot import app — circular).
_INPUTS_PENDING_NAV_PAGE_SLUG_KEY = "_pending_nav_page_slug"
_INPUTS_DESIGN_ACTIONS_ANCHOR_ID = "inputs_design_actions_anchor"
# Local launch-card view state only. It lets users inspect capacity summaries
# without writing design-action inputs or invoking Design Mode/apply paths.
_INPUTS_CAPACITY_ONLY_VIEW_KEY = "inputs_capacity_only_view_enabled"


def inputs_show_landing_dashboard() -> bool:
    """
    True when there are no ULS design actions and no line UDL loads (g+q).
    Design mode (Fast vs Detailed) does not hide the card.
    Uses existing session / shared state via get_param (no new state keys for detection).
    """
    M_u = float(get_param("uls_Mstar", 0.0) or 0.0)
    V_u = float(get_param("uls_Vstar", 0.0) or 0.0)
    Tu = float(get_param("Tu_star", 0.0) or 0.0)
    Nu = float(get_param("uls_Nstar", 0.0) or get_param("N_star", 0.0) or 0.0)
    Pu = float(get_param("P_star", 0.0) or 0.0)
    sigma_raw = get_param("sigma_sr", None)
    if sigma_raw is None:
        sigma_raw = get_param("sigma_s_sls", 0.0)
    sigma_sr = float(sigma_raw or 0.0)
    g_udl = float(get_param("g_udl_kNm_per_m", 0.0) or 0.0)
    q_udl = float(get_param("q_udl_kNm_per_m", 0.0) or 0.0)

    no_design_actions = (
        abs(M_u) < 1e-15 and
        abs(V_u) < 1e-15 and
        abs(sigma_sr) < 1e-15 and
        abs(Tu) < 1e-15 and
        abs(Nu) < 1e-15 and
        abs(Pu) < 1e-15
    )
    no_loads = abs(g_udl) < 1e-15 and abs(q_udl) < 1e-15
    return bool(no_design_actions and no_loads and not st.session_state.get(_INPUTS_CAPACITY_ONLY_VIEW_KEY, False))


def inputs_has_design_actions_or_loads() -> bool:
    """True once the Inputs page has real actions or generated/applied loads."""
    def _num(value) -> float:
        try:
            return float(value or 0.0)
        except Exception:
            return 0.0

    action_keys = (
        "uls_Mstar",
        "uls_Mstar_pos_manual",
        "uls_Mstar_neg_manual",
        "uls_Vstar",
        "uls_Nstar",
        "Tu_star",
        "N_star",
        "P_star",
        "sigma_sr",
        "sigma_s_sls",
        "sls_Mstar",
        "sls_Vstar",
        "g_udl_kNm_per_m",
        "q_udl_kNm_per_m",
        "load_Mstar_proxy",
        "load_Mstar_pos_proxy",
        "load_Mstar_neg_proxy",
        "load_Vstar_proxy",
        "load_Nstar_proxy",
        "inputs_load_Mstar_proxy",
        "inputs_load_Mstar_pos_proxy",
        "inputs_load_Mstar_neg_proxy",
        "inputs_load_Vstar_proxy",
        "inputs_load_Nstar_proxy",
        "inputs_Tu_star",
        "inputs_P_star",
    )
    return any(abs(_num(st.session_state.get(key, get_param(key, 0.0)))) >= 1e-15 for key in action_keys)


