@speed_profiled("ui_render.inputs_page.section_2d_diagram_block", category="render")
def _render_section_2d_diagram_block(*, compact: bool = False, model_state: dict | None = None):
    """Render the 2D section diagram only (UI order/presentation helper)."""
    diagram_started_at = time.perf_counter()
    sec_shape = st.session_state.get("sec_shape", "RECT")

    if sec_shape == "RECT":
        _required = ["b", "D"]
    elif sec_shape == "T":
        _required = ["bf", "tf", "bw", "D"]
    else:  # "I"
        _required = ["bf", "tf", "tw", "D"]

    _missing = [k for k in _required if st.session_state.get(k) in (None, "", 0)]
    if _missing:
        st.info("2D section diagram not available right now (inputs are still saved).")
        return

    fig_sec = None
    try:
        geo_fp = _inputs_geometry_fingerprint(model_state)
        cached_fp = st.session_state.get("_inputs_model_2d_geo_fp")
        cached_fig = st.session_state.get("_inputs_model_2d_fig")
        if cached_fp == geo_fp and cached_fig is not None:
            fig_sec = copy.deepcopy(cached_fig)
        else:
            fig_sec = make_summary_cross_section_figure()
            if fig_sec is None:
                raise ValueError("2D section diagram function returned None (fig is None)")
            st.session_state["_inputs_model_2d_fig"] = copy.deepcopy(fig_sec)
            st.session_state["_inputs_model_2d_geo_fp"] = geo_fp
    except Exception as e:
        st.warning(f"2D section diagram failed: {e}")
        with st.expander("Diagram debug details"):
            st.exception(e)
        return

    if fig_sec is not None:
        try:
            # ~12% shorter than legacy 540/620 to limit vertical overflow
            fig_sec.update_layout(
                autosize=True,
                height=(475 if compact else 545),
                margin=dict(l=4, r=4, t=4, b=4),
            )
        except Exception:
            pass
        st.markdown('<div class="inputs-page-main-diagram-wrap">', unsafe_allow_html=True)
        st.plotly_chart(
            fig_sec,
            use_container_width=True,
            config={"displayModeBar": False},
        )
        st.markdown("</div>", unsafe_allow_html=True)


def _render_3d_diagram_block(*, compact: bool = False, model_state: dict | None = None):
    """Render the 3D diagram only (UI order/presentation helper)."""
    diagram_started_at = time.perf_counter()
    geo_fp = _inputs_geometry_fingerprint(model_state)
    cache_payload = st.session_state.get("_inputs_model_3d_cache", {})
    cached_fp = cache_payload.get("geo_fp")
    cached_shape = cache_payload.get("shape_name")
    cached_fig = cache_payload.get("fig")
    if cached_fp == geo_fp and cached_fig is not None and isinstance(cached_shape, str):
        shape_name = cached_shape
        fig3d = copy.deepcopy(cached_fig)
    else:
        layout = compute_section_layout()
        shape_name = layout.get("shape_name", "Rectangle (b × D)")
        dims = layout.get("dims", {})
        reo = dict(layout.get("reo", {}))
        shared_state = dict(model_state) if isinstance(model_state, dict) else _shared_state_snapshot()
        reo["lig_d"] = float(shared_state.get("lig_d", reo.get("lig_d", 0.0)) or 0.0)
        reo["lig_legs"] = int(shared_state.get("lig_legs", reo.get("lig_legs", 0)) or 0)
        reo["s_lig"] = float(shared_state.get("s_lig", reo.get("s_lig", 200.0)) or 200.0)
        reo_layout = layout.get("reo_layout", {})
        if shape_name.startswith(("T-Section", "I-Section")):
            if not isinstance(reo_layout, dict):
                reo_layout = {"top": [], "bottom": []}
            fig3d = cached_make_section_3d_figure(
                shape_name=shape_name,
                dims_json=_cache_json(dims),
                reo_layout_json=_cache_json(reo_layout),
                reo_inputs_json=_cache_json(reo),
                show_shear=True,
                L_vis=900.0,
            )
        else:
            fig3d = make_beam_3d_figure()
        st.session_state["_inputs_model_3d_cache"] = {
            "geo_fp": geo_fp,
            "shape_name": shape_name,
            "fig": copy.deepcopy(fig3d),
        }

    st.markdown(
        """
        <style>
        div[data-testid="stPlotlyChart"] {
          border: 1px solid rgba(0,0,0,0.12);
          border-radius: 8px;
          background: #fff;
          overflow: hidden;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

    if shape_name.startswith(("T-Section", "I-Section")):
        BASE_H = 360 if compact else 420
        fig3d.update_layout(
            height=int(int(BASE_H * 7 / 5) * 0.88),
            margin=dict(l=4, r=4, t=4, b=4),
        )
        st.markdown('<div class="inputs-page-main-diagram-wrap">', unsafe_allow_html=True)
        st.plotly_chart(
            fig3d,
            use_container_width=True,
            config={"displayModeBar": False}
        )
        st.markdown("</div>", unsafe_allow_html=True)
    else:
        BASE_H = 410 if compact else 480
        _h3d = int(int(BASE_H * 7 / 5) * 0.88)
        fig3d.update_layout(
            height=_h3d,
            margin=dict(l=4, r=4, t=4, b=4),
        )
        st.markdown('<div class="inputs-page-main-diagram-wrap">', unsafe_allow_html=True)
        st.plotly_chart(
            fig3d,
            width="stretch",
            height=_h3d,
            config={"displayModeBar": True}
        )
        st.markdown("</div>", unsafe_allow_html=True)


def _shared_toggle(
    label: str,
    widget_key: str,
    shared_key: str,
    default: bool,
    sync_callbacks: dict,
    *,
    help_text: str | None = None,
) -> bool:
    _register_rendered_key(widget_key)
    seed_widget_from_shared(widget_key, shared_key, bool(default))
    return st.toggle(
        label,
        key=widget_key,
        help=help_text,
        on_change=sync_callbacks.get(widget_key),
    )


