            shear_repair_statuses = dict(shear_repair_overview.get("statuses") or {})
            shear_repair_util = _parse_util_value(shear_repair_utils.get("shear"))
            current_shear_util = _parse_util_value(
                dict((current_overview_for_active_shear or {}).get("utils") or {}).get("shear")
            )
