def _combined_underdesign_shear_strengthening_truth_gate_payload(
    working_state: dict,
    *,
    overview: dict | None,
    efficiency_classification: str | None = None,
) -> dict:
    """
    Safety gate: when (efficiency failing or not all key checks pass) and published
    shear truth is unresolved, shear strengthening paths must not be trusted.
    Caller must not invoke compute_efficiency_tightening_state from inside nested
    efficiency recomputation; pass efficiency_classification when known.
    """
    ov = overview if isinstance(overview, dict) else {}
    ws = _overlay_current_normalized_shear_truth(_guidance_state_snapshot(working_state))
    truth_resolved = ws.get("final_shear_truth_resolved")
    fail_reason = str(ws.get("final_shear_truth_failure_reason") or "").strip()
    cls = str(efficiency_classification or "").strip().lower()
    if not cls and bool(ov.get("any_fail")):
        cls = "failing"
    all_key_pass = bool(ov.get("all_key_pass"))
    combined_cond = (cls == "failing") or (not all_key_pass)
    block = bool(combined_cond and truth_resolved is False)
    reason = (fail_reason or "final_shear_truth_unresolved") if block else None
    out = {
        "combined_underdesign_shear_truth_block_active": block,
        "combined_underdesign_shear_truth_block_reason": reason,
        "combined_underdesign_shear_strengthening_suppressed": block,
        "combined_underdesign_truth_gate_source": "combined_underdesign_shear_truth_gate",
        "combined_underdesign_truth_gate_classification": cls or None,
        "combined_underdesign_truth_gate_all_key_pass": all_key_pass,
        "combined_underdesign_truth_gate_final_shear_truth_resolved": truth_resolved,
    }
    return out


def _stage3_remaining_issue_class_from_overview_state(
    state: dict | None,
    overview: dict | None,
) -> str | None:
    """Optional audit classifier; set only when evidence is unambiguous."""
    if not isinstance(overview, dict):
        return None
    s = dict(state or {})
    st_sh = str(((overview.get("statuses") or {}).get("shear") or "")).strip().upper()
    design_st = str(s.get("shear_design_status") or "").strip().upper()
    truth_res = s.get("final_shear_truth_resolved")
    fail_r = str(s.get("final_shear_truth_failure_reason") or "").strip()
    truth_st = str(s.get("shear_truth_status") or "").strip()
    if design_st == "INVALID" and st_sh == "PASS":
        return "truth"
    if truth_res is False and bool(fail_r or truth_st) and st_sh == "PASS":
        return "truth"
    return None


@speed_profiled("inputs_page.summary_overview_build", category="compute")
def _collect_design_overview(state: dict, context: dict | None = None) -> dict:
    _overview_trace_started = time.perf_counter()
    design_context = context or _build_design_actions_context(state)
    overview_state = dict(design_context.get("state") or _state_with_resolved_design_actions(state))
    actions = dict(design_context.get("actions") or _resolve_design_actions_from_state(overview_state))
    overview_cache_disabled = os.environ.get("DISABLE_OVERVIEW_CACHE", "").strip().lower() in {"1", "true", "yes", "on"}
    overview_fp = stable_fingerprint_for_payload(
        {
            "version": "design_overview_cache_v1",
            "state": overview_state,
            "actions": actions,
        }
    )
    _direct_diag = st.session_state.get("_direct_target_band_diag_active")
    if _direct_target_band_diag_enabled() and isinstance(_direct_diag, dict):
        try:
            _direct_diag["overview_calls"] = int(_direct_diag.get("overview_calls", 0) or 0) + 1
            _fp_key = str(overview_fp)
            _fp_counts = _direct_diag.setdefault("overview_fingerprints", {})
            if not isinstance(_fp_counts, dict):
                _fp_counts = {}
                _direct_diag["overview_fingerprints"] = _fp_counts
            _fp_counts[_fp_key] = int(_fp_counts.get(_fp_key, 0) or 0) + 1
            _max_fp_count = max((int(v or 0) for v in _fp_counts.values()), default=0)
            _direct_diag["max_repeated_overview_fingerprint_count"] = int(_max_fp_count)
            if (
                int(_direct_diag["overview_calls"]) >= DIRECT_TARGET_BAND_PROOF_MAX_OVERVIEW_CALLS
                or _max_fp_count >= DIRECT_TARGET_BAND_PROOF_MAX_OVERVIEW_CALLS
            ):
                _direct_diag["abort"] = True
                _direct_diag["abort_reason"] = (
                    "direct_target_band_proof_budget_exhausted:"
                    f"overview_calls={_direct_diag['overview_calls']}:"
                    f"max_repeated_fingerprint={_max_fp_count}"
                )
            if (
                int(_direct_diag["overview_calls"]) <= 5
                or int(_direct_diag["overview_calls"]) % 250 == 0
                or bool(_direct_diag.get("abort"))
            ):
                _direct_target_band_diag_trace(
                    "direct_target_band.collect_design_overview",
                    call_id=_direct_diag.get("call_id"),
                    depth=_direct_diag.get("depth"),
                    overview_calls=int(_direct_diag.get("overview_calls", 0) or 0),
                    unique_overview_fingerprints=len(_fp_counts),
                    max_repeated_overview_fingerprint_count=int(_max_fp_count),
                    latest_overview_fingerprint=_fp_key,
                    abort=bool(_direct_diag.get("abort")),
                    abort_reason=_direct_diag.get("abort_reason"),
                )
        except Exception:
            pass
    cached_overview = None if overview_cache_disabled else get_rerun_pure_cache("collect_design_overview", overview_fp)
    if isinstance(cached_overview, dict):
        # Per-rerun only: the key includes the exact resolved state/actions and
        # callers treat the returned overview as immutable-by-convention.
        _inputs_pre_widget_trace(
            "_collect_design_overview",
            duration_ms=round((time.perf_counter() - _overview_trace_started) * 1000.0, 2),
            cache_hit=True,
            cache_disabled=False,
            worst_util=cached_overview.get("worst_util"),
            governing_check=cached_overview.get("governing_check"),
        )
        ux_probe_record(
            "inputs_page.summary_overview_build",
            fingerprint=overview_fp,
            cache_hit=True,
            meta={
                "governing_check": cached_overview.get("governing_check"),
                "worst_util": cached_overview.get("worst_util"),
            },
        )
        speed_profile_record(
            "inputs_page.summary_overview_build.cache_hit",
            0.0,
            category="compute",
        )
        return cached_overview
    bend_pack = build_bending_check_rows_from_state(overview_state) or {}
    shear_pack = build_shear_check_rows_from_state(overview_state) or {}
    crack_pack = _build_crack_pack_from_state(overview_state)
    defl_pack = _build_deflection_pack_from_state(overview_state)

    crack_rows = crack_pack.get("rows") or []
    crack_utils = [_parse_util_value(row.get("util")) for row in crack_rows]
    crack_util_values = [util for util in crack_utils if util is not None]

    def _max_row_util(rows: list[dict] | None) -> float | None:
        values = [
            util for util in (_parse_util_value((row or {}).get("util")) for row in list(rows or []))
            if util is not None
        ]
        return max(values) if values else None

    bending_status, _ = _overall_status_from_rows(bend_pack.get("rows") or [])
    shear_status, _ = _overall_status_from_rows(shear_pack.get("rows") or [])
    crack_status, _ = _overall_status_from_rows(crack_rows)
    deflection_status, _ = _overall_status_from_rows(defl_pack.get("rows") or [])

    def _failed_row_details(rows: list[dict] | None) -> list[dict]:
        out: list[dict] = []
        for row in list(rows or []):
            if not isinstance(row, dict) or row.get("is_informational"):
                continue
            status_text = str(row.get("status") or "").strip().upper()
            util_value = _parse_util_value(row.get("util"))
            if status_text not in {"FAIL", "NG"} and not (util_value is not None and util_value > 1.0 + 1e-9):
                continue
            title = str(row.get("title") or "Detailed check").strip() or "Detailed check"
            calculated = str(row.get("calculated") or row.get("capacity") or row.get("value") or "").strip()
            requirement = str(row.get("requirement") or row.get("action") or row.get("limit") or "").strip()
            detail_text = title
            if calculated or requirement:
                detail_text = f"{title}: {calculated} vs {requirement}".strip()
            out.append(
                {
                    "uid": row.get("uid"),
                    "title": title,
                    "status": "FAIL",
                    "util": util_value,
                    "calculated": calculated,
                    "requirement": requirement,
                    "text": detail_text,
                }
            )
        return out

    failure_details_by_family = {
        "bending": _failed_row_details(bend_pack.get("rows") or []),
        "shear": _failed_row_details(shear_pack.get("rows") or []),
        "crack": _failed_row_details(crack_rows),
        "deflection": _failed_row_details(defl_pack.get("rows") or []),
    }

    bending_util = _parse_util_value(bend_pack.get("summary_util"))
    if bending_util is None:
        bending_util = _max_row_util(bend_pack.get("rows") or [])
    shear_util = _parse_util_value(shear_pack.get("summary_util"))
    if shear_util is None:
        shear_util = _max_row_util(
            (shear_pack.get("summary_rows") or [])
            or (shear_pack.get("rows") or []),
        )
    shear_governing_status = str(shear_pack.get("summary_governing_status") or "").strip()
    shear_governing_util = shear_pack.get("summary_governing_util")
    shear_truth_status = str(shear_pack.get("shear_truth_status") or "").strip()
    shear_truth_util = shear_pack.get("shear_truth_util_governing")
    final_shear_truth_resolved = shear_pack.get("final_shear_truth_resolved")
    final_shear_truth_failure_reason = str(shear_pack.get("final_shear_truth_failure_reason") or "").strip()
    shear_detail_rows = [
        row for row in list(shear_pack.get("rows") or [])
        if isinstance(row, dict) and not row.get("is_informational")
    ]
    shear_detail_statuses = {
        str(row.get("status") or "").strip().upper()
        for row in shear_detail_rows
    }
    shear_detail_util = _max_row_util(shear_detail_rows)
    if shear_governing_status:
        shear_status = shear_governing_status
    elif shear_truth_status:
        shear_status = shear_truth_status
    elif final_shear_truth_resolved is False or final_shear_truth_failure_reason:
        shear_status = "FAIL"
    if shear_governing_util is not None:
        try:
            shear_util = float(shear_governing_util)
        except Exception:
            pass
    elif shear_truth_util is not None:
        try:
            shear_util = float(shear_truth_util)
        except Exception:
            pass
    if (
        failure_details_by_family.get("shear")
        or
        "FAIL" in shear_detail_statuses
        or "NG" in shear_detail_statuses
        or (shear_detail_util is not None and float(shear_detail_util) > 1.0 + 1e-9)
        or (shear_util is not None and float(shear_util) > 1.0 + 1e-9)
    ):
        shear_status = "FAIL"
        if shear_detail_util is not None:
            shear_util = float(shear_detail_util)
    if failure_details_by_family.get("bending"):
        bending_status = "FAIL"
        failed_utils = [
            detail.get("util")
            for detail in failure_details_by_family.get("bending", [])
            if detail.get("util") is not None
        ]
        if failed_utils:
            bending_util = max(float(u) for u in failed_utils)
    crack_util = max(crack_util_values) if crack_util_values else None
    deflection_util = _parse_util_value(defl_pack.get("summary_util_total"))
    if not _has_meaningful_crack_sls_demand(overview_state):
        crack_status = "PASS"
        crack_util = 0.0
    if not _has_meaningful_deflection_sls_demand(overview_state):
        deflection_status = "PASS"
        deflection_util = 0.0

    statuses = {
        "bending": bending_status,
        "shear": shear_status,
        "crack": crack_status,
        "deflection": deflection_status,
    }
    util_map = {
        "bending": bending_util,
        "shear": shear_util,
        "crack": crack_util,
        "deflection": deflection_util,
    }
    tracked_statuses = [status for status in statuses.values() if status not in ("—", "")]
    any_fail = any(status == "FAIL" for status in tracked_statuses)
    any_warn = any(status == "NEAR LIMIT" for status in tracked_statuses)
    all_key_pass = bool(tracked_statuses) and all(status == "PASS" for status in tracked_statuses)
    worst_util = max((util for util in util_map.values() if util is not None), default=0.0)
    governing_check = None
    governing_source = "overview_worst_util"
    governing_candidates = [
        (check_key, util)
        for check_key, util in util_map.items()
        if util is not None
    ]
    if governing_candidates:
        governing_check, _ = max(governing_candidates, key=lambda item: float(item[1]))
    if governing_check == "shear" and str(shear_pack.get("summary_governing_source") or "").strip():
        governing_source = f"shear:{str(shear_pack.get('summary_governing_source') or '').strip()}"
    overview_out = {
        "packs": {
            "bending": bend_pack,
            "shear": shear_pack,
            "crack": crack_pack,
            "deflection": defl_pack,
        },
        "statuses": statuses,
        "utils": util_map,
        "any_fail": any_fail,
        "any_warn": any_warn,
        "all_key_pass": all_key_pass,
        "worst_util": worst_util,
        "governing_util": worst_util,
        "governing_check": governing_check,
        "governing_util_source": governing_source,
        "actions_used": actions,
        "overview_shear_governing_check_name": shear_pack.get("summary_governing_check_name"),
        "overview_shear_governing_reason": shear_pack.get("summary_governing_reason"),
        "overview_shear_governing_source": shear_pack.get("summary_governing_source"),
        "overview_shear_truth_source": "shear_pack.summary_governing",
        "overview_shear_selection_origin": shear_pack.get("summary_governing_selection_origin"),
        "failure_details_by_family": failure_details_by_family,
    }
    overview_out["stage3_shear_truth_debug"] = _stage3_final_published_shear_truth_bundle(overview_state)
    overview_out["design_guide_shear_truth_source"] = "final_published_shear_truth"
    overview_out["stage3_remaining_issue_class"] = _stage3_remaining_issue_class_from_overview_state(
        overview_state,
        overview_out,
    )
    ux_probe_record(
        "inputs_page.summary_overview_build",
        fingerprint=overview_fp,
        cache_hit=False,
        meta={
            "governing_check": governing_check,
            "worst_util": worst_util,
        },
    )
    _inputs_pre_widget_trace(
        "_collect_design_overview",
        duration_ms=round((time.perf_counter() - _overview_trace_started) * 1000.0, 2),
        cache_hit=False,
        cache_disabled=overview_cache_disabled,
        worst_util=overview_out.get("worst_util"),
        governing_check=overview_out.get("governing_check"),
    )
    if not overview_cache_disabled:
        set_rerun_pure_cache("collect_design_overview", overview_fp, overview_out)
    return overview_out


def _state_with_overrides(state: dict, **updates) -> dict:
    new_state = dict(state)
    new_state.update(updates)
    return new_state


def _resolve_geometry_width_context(state: dict) -> tuple[str, str, float]:
    sec_shape = str(state.get("sec_shape", "RECT") or "RECT")
    if sec_shape == "T":
        return "bw", "Web width bw (mm)", float(state.get("bw", state.get("b", 300.0)) or 300.0)
    if sec_shape == "I":
        return "tw", "Web thickness tw (mm)", float(state.get("tw", state.get("b", 200.0)) or 200.0)
    return "b", "Width b (mm)", float(state.get("b", 400.0) or 400.0)


def _design_width_value(state: dict) -> float:
    _, _, width = _resolve_geometry_width_context(state)
    return float(width)


def _float_from_state(state: dict, key: str, default: float) -> float:
    value = state.get(key)
    if value is None:
        return float(default)
    try:
        return float(value)
    except Exception:
        return float(default)


def _int_from_state(state: dict, key: str, default: int) -> int:
    value = state.get(key)
    if value is None:
        return int(default)
    try:
        return int(value)
    except Exception:
        return int(default)


def _mode_value_from_state(
    state: dict,
    mode_key: str,
    count_key: str,
    spacing_key: str,
    default_count: float,
    default_spacing: float = 200.0,
) -> float:
    mode = str(state.get(mode_key, "Count") or "Count")
    if mode == "Spacing":
        value = state.get(spacing_key)
        return float(default_spacing if value is None else value)
    value = state.get(count_key)
    return float(default_count if value is None else value)


def _uls_action_from_state(state: dict, action: str) -> float:
    resolved_actions = _resolve_design_actions_from_state(state)
    resolved_map = {
        "M": "Mu",
        "V": "Vu",
        "N": "Nu",
        "T": "Tu",
        "P": "Pu",
    }
    resolved_key = resolved_map.get(action)
    if resolved_key is not None:
        mapped = resolved_actions.get(resolved_key)
        if mapped is not None:
            return float(mapped)

    shared_map = {
        "M": "uls_Mstar",
        "V": "uls_Vstar",
        "N": "uls_Nstar",
    }
    if action in shared_map:
        return _float_from_state(state, shared_map[action], 0.0)
    if action == "T":
        return _float_from_state(state, "Tu_star", 0.0)
    if action == "P":
        return _float_from_state(state, "P_star", 0.0)
    return 0.0


def _resolve_design_actions_from_state(state: dict) -> dict:
    return resolve_design_actions(state)


def _state_with_resolved_design_actions(state: dict, actions: dict | None = None) -> dict:
    resolved = _guidance_state_snapshot(state)
    actions = dict(actions or _resolve_design_actions_from_state(resolved))
    resolved["uls_Mstar"] = float(actions.get("Mu", _float_from_state(resolved, "uls_Mstar", 0.0)) or 0.0)
    resolved["uls_Vstar"] = float(actions.get("Vu", _float_from_state(resolved, "uls_Vstar", 0.0)) or 0.0)
    resolved["uls_Nstar"] = float(actions.get("Nu", _float_from_state(resolved, "uls_Nstar", 0.0)) or 0.0)
    resolved["Mu_star"] = float(actions.get("Mu", _float_from_state(resolved, "Mu_star", 0.0)) or 0.0)
    resolved["Vu_star"] = float(actions.get("Vu", _float_from_state(resolved, "Vu_star", 0.0)) or 0.0)
    resolved["N_star"] = float(actions.get("Nu", _float_from_state(resolved, "N_star", 0.0)) or 0.0)
    resolved["sls_Mstar"] = float(actions.get("SLS_M", _float_from_state(resolved, "sls_Mstar", 0.0)) or 0.0)
    resolved["uls_Mstar_pos_manual"] = float(
        _float_from_state(
            resolved,
            "uls_Mstar_pos_manual",
            max(0.0, _float_from_state(resolved, "uls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["uls_Mstar_neg_manual"] = float(
        _float_from_state(
            resolved,
            "uls_Mstar_neg_manual",
            max(0.0, -_float_from_state(resolved, "uls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["sls_Mstar_pos_manual"] = float(
        _float_from_state(
            resolved,
            "sls_Mstar_pos_manual",
            max(0.0, _float_from_state(resolved, "sls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["sls_Mstar_neg_manual"] = float(
        _float_from_state(
            resolved,
            "sls_Mstar_neg_manual",
            max(0.0, -_float_from_state(resolved, "sls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["sls_Vstar"] = float(actions.get("SLS_V", _float_from_state(resolved, "sls_Vstar", 0.0)) or 0.0)
    resolved["Tu_star"] = float(actions.get("Tu", _float_from_state(resolved, "Tu_star", 0.0)) or 0.0)
    resolved["P_star"] = float(actions.get("Pu", _float_from_state(resolved, "P_star", 0.0)) or 0.0)
    resolved["actions_uls"] = {
        "M": resolved["uls_Mstar"],
        "V": resolved["uls_Vstar"],
        "N": resolved["uls_Nstar"],
        "T": resolved["Tu_star"],
        "P": resolved["P_star"],
    }
    return resolved


def _state_with_resolved_design_actions_isolated(state: dict, actions: dict | None = None) -> dict:
    """Like _state_with_resolved_design_actions but does NOT merge st.session_state (candidate-only)."""
    resolved = dict(state)
    for key, default in SHARED_DEFAULTS.items():
        resolved.setdefault(key, default)
    actions = dict(actions or _resolve_design_actions_from_state(resolved))
    resolved["uls_Mstar"] = float(actions.get("Mu", _float_from_state(resolved, "uls_Mstar", 0.0)) or 0.0)
    resolved["uls_Vstar"] = float(actions.get("Vu", _float_from_state(resolved, "uls_Vstar", 0.0)) or 0.0)
    resolved["uls_Nstar"] = float(actions.get("Nu", _float_from_state(resolved, "uls_Nstar", 0.0)) or 0.0)
    resolved["Mu_star"] = float(actions.get("Mu", _float_from_state(resolved, "Mu_star", 0.0)) or 0.0)
    resolved["Vu_star"] = float(actions.get("Vu", _float_from_state(resolved, "Vu_star", 0.0)) or 0.0)
    resolved["N_star"] = float(actions.get("Nu", _float_from_state(resolved, "N_star", 0.0)) or 0.0)
    resolved["sls_Mstar"] = float(actions.get("SLS_M", _float_from_state(resolved, "sls_Mstar", 0.0)) or 0.0)
    resolved["uls_Mstar_pos_manual"] = float(
        _float_from_state(
            resolved,
            "uls_Mstar_pos_manual",
            max(0.0, _float_from_state(resolved, "uls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["uls_Mstar_neg_manual"] = float(
        _float_from_state(
            resolved,
            "uls_Mstar_neg_manual",
            max(0.0, -_float_from_state(resolved, "uls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["sls_Mstar_pos_manual"] = float(
        _float_from_state(
            resolved,
            "sls_Mstar_pos_manual",
            max(0.0, _float_from_state(resolved, "sls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["sls_Mstar_neg_manual"] = float(
        _float_from_state(
            resolved,
            "sls_Mstar_neg_manual",
            max(0.0, -_float_from_state(resolved, "sls_Mstar", 0.0)),
        )
        or 0.0
    )
    resolved["sls_Vstar"] = float(actions.get("SLS_V", _float_from_state(resolved, "sls_Vstar", 0.0)) or 0.0)
    resolved["Tu_star"] = float(actions.get("Tu", _float_from_state(resolved, "Tu_star", 0.0)) or 0.0)
    resolved["P_star"] = float(actions.get("Pu", _float_from_state(resolved, "P_star", 0.0)) or 0.0)
    resolved["actions_uls"] = {
        "M": resolved["uls_Mstar"],
        "V": resolved["uls_Vstar"],
        "N": resolved["uls_Nstar"],
        "T": resolved["Tu_star"],
        "P": resolved["P_star"],
    }
    return resolved


def _build_design_actions_context_isolated(state: dict) -> dict:
    """Design actions + resolved ULS/SLS fields from the given dict only (no session overlay)."""
    source_state = dict(state)
    for key, default in SHARED_DEFAULTS.items():
        source_state.setdefault(key, default)
    actions = _resolve_design_actions_from_state(source_state)
    return {
        "state": _state_with_resolved_design_actions_isolated(source_state, actions),
        "actions": dict(actions),
        "action_signature": tuple(actions.get("signature", ())),
    }


def _build_design_actions_context(state: dict) -> dict:
    source_state = _guidance_state_snapshot(state)
    actions = _resolve_design_actions_from_state(source_state)
    return {
        "state": _state_with_resolved_design_actions(source_state, actions),
        "actions": dict(actions),
        "action_signature": tuple(actions.get("signature", ())),
    }


