def _rescue_mode_default_debug() -> dict:
    return {
        "rescue_mode_entered": False,
        "rescue_mode_entry_reason": None,
        "rescue_mode_family": None,
        "rescue_mode_tier_requested": None,
        "rescue_mode_tier_used": None,
        "rescue_mode_seed_key": None,
        "rescue_mode_seed_legal": None,
        "rescue_mode_seed_illegal_reason": None,
        "rescue_mode_fallback_count": 0,
        "rescue_mode_ineffective_seeds": [],
        "rescue_mode_effective_seed_found": False,
        "rescue_mode_exit_reason": None,
    }


def _rescue_mode_action_tier(state: dict, family: str) -> str | None:
    mu = abs(float(_uls_action_from_state(state, "M") or 0.0))
    vu = abs(float(_uls_action_from_state(state, "V") or 0.0))
    action_value = mu
    if family == "shear":
        action_value = vu
    elif family == "combined":
        action_value = max(mu, vu)
    if action_value >= 850.0:
        return "extreme"
    if action_value >= 650.0:
        return "very_high"
    if action_value >= 400.0:
        return "high"
    if action_value >= 250.0:
        return "medium"
    return None


def _rescue_mode_util_tier(eval_obj: dict | None) -> str | None:
    util = _candidate_objective_util(eval_obj or {})
    try:
        u = float(util)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(u):
        return None
    if u > 10.0:
        return "extreme"
    if u >= 6.0:
        return "very_high"
    if u >= 3.0:
        return "high"
    if u >= 1.5:
        return "medium"
    return None


def _rescue_mode_both_domains_fail_meanfully(eval_obj: dict | None, mode_config: dict) -> bool:
    bend = _one_click_domain_score(eval_obj, "bending", mode_config)
    shear = _one_click_domain_score(eval_obj, "shear", mode_config)
    bend_fail = not bool(bend.get("pass"))
    shear_fail = not bool(shear.get("pass"))
    try:
        bend_util = float(bend.get("util"))
    except (TypeError, ValueError):
        bend_util = None
    try:
        shear_util = float(shear.get("util"))
    except (TypeError, ValueError):
        shear_util = None
    return bool(
        bend_fail
        and shear_fail
        and bend_util is not None
        and shear_util is not None
        and math.isfinite(bend_util)
        and math.isfinite(shear_util)
        and bend_util >= 1.10
        and shear_util >= 1.10
    )


def _rescue_mode_choose_family(eval_obj: dict | None, mode_config: dict) -> str | None:
    bend = _one_click_domain_score(eval_obj, "bending", mode_config)
    shear = _one_click_domain_score(eval_obj, "shear", mode_config)
    bend_fail = not bool(bend.get("pass"))
    shear_fail = not bool(shear.get("pass"))
    if _rescue_mode_both_domains_fail_meanfully(eval_obj, mode_config):
        return "combined"
    if bend_fail and not shear_fail:
        return "bending"
    if shear_fail and not bend_fail:
        return "shear"
    return None


def _rescue_mode_choose_tier(state: dict, eval_obj: dict | None, family: str) -> str | None:
    action_tier = _rescue_mode_action_tier(state, family)
    util_tier = _rescue_mode_util_tier(eval_obj)
    indices = [
        RESCUE_MODE_TIER_ORDER.index(tier)
        for tier in (action_tier, util_tier)
        if tier in RESCUE_MODE_TIER_ORDER
    ]
    if not indices:
        return None
    return RESCUE_MODE_TIER_ORDER[max(indices)]


def _rescue_mode_seed_order(requested_tier: str | None) -> list[str]:
    if requested_tier not in RESCUE_MODE_TIER_ORDER:
        return []
    if requested_tier == "extreme":
        return ["very_high", "extreme"]
    idx = RESCUE_MODE_TIER_ORDER.index(requested_tier)
    out = list(RESCUE_MODE_TIER_ORDER[idx:])
    if "extreme" in out and requested_tier != "very_high":
        return [tier for tier in out if tier != "extreme"] + ["extreme"]
    return out


def _rescue_mode_current_beam_plausible(state: dict, *, family: str, tier: str | None) -> bool:
    if tier not in RESCUE_MODE_TIER_ORDER:
        return True
    seed = dict(((RESCUE_SEED_LIBRARY.get(family) or {}).get(tier)) or {})
    updates = dict(seed.get("updates") or {})
    try:
        cur_b = float(state.get("b", 0.0) or 0.0)
        cur_D = float(state.get("D", 0.0) or 0.0)
        seed_b = float(updates.get("b", 0.0) or 0.0)
        seed_D = float(updates.get("D", 0.0) or 0.0)
    except (TypeError, ValueError):
        return False
    if seed_b <= 0.0 or seed_D <= 0.0:
        return False
    return bool(cur_b >= 0.85 * seed_b and cur_D >= 0.85 * seed_D)


def _rescue_mode_validate_seed(base_state: dict, seed_updates: dict) -> tuple[bool, str | None, dict]:
    trial_state = _guidance_state_snapshot(dict(base_state or {}))
    trial_state.update(dict(seed_updates or {}))
    trial_pack = _build_canonical_design_state_pack(_overlay_current_normalized_shear_truth(trial_state))
    coherence = _design_state_coherence_check(trial_pack)
    if not _canonical_pack_is_valid(trial_pack):
        return False, str(trial_pack.get("canonical_pack_error") or "canonical_pack_invalid"), trial_state
    if bool(coherence.get("coherence_should_block")):
        issues = list(coherence.get("coherence_blocking_issues") or [])
        return False, str(issues[0] if issues else "state_incoherent_after_rebuild"), trial_state
    try:
        ev = evaluate_candidate_full(
            trial_pack,
            source="rescue_mode_seed_validation",
            label="Rescue seed validation",
            action_type="rescue_seed_validation",
            updates={},
        )
    except Exception:
        ev = None
    if not isinstance(ev, dict):
        return False, "seed_evaluation_failed", trial_state
    return True, None, trial_state


def _rescue_mode_should_enter(
    *,
    state: dict,
    init_eval: dict | None,
    final_eval: dict | None,
    final_pass: bool,
    final_updates: dict,
    stop_reason: str,
    mode_config: dict,
) -> tuple[bool, str | None, str | None, str | None, dict]:
    section_kind = str(state.get("section_shape") or state.get("section_type") or "RECT").strip().upper()
    initial_all_pass = bool((init_eval.get("overview") or {}).get("all_key_pass"))
    debug = {
        "section_kind": section_kind,
        "initial_all_pass": initial_all_pass,
        "final_pass": bool(final_pass),
        "final_updates_present": bool(final_updates),
        "stop_reason": str(stop_reason or ""),
        "initial_objective_util": None,
        "final_objective_util": None,
        "severe_fail": False,
        "both_fail_meaningfully": False,
        "family": None,
        "requested_tier": None,
        "current_beam_plausible": None,
    }
    if section_kind not in {"RECT", "RECTANGULAR", ""}:
        return False, "non_rectangular_section", None, None, debug
    if initial_all_pass:
        return False, "initial_state_already_passing", None, None, debug
    if final_pass:
        return False, "normal_one_click_found_all_pass_path", None, None, debug
    family = _rescue_mode_choose_family(init_eval, mode_config)
    debug["family"] = family
    if not family:
        return False, "family_not_rescue_eligible", None, None, debug
    requested_tier = _rescue_mode_choose_tier(state, init_eval, family)
    debug["requested_tier"] = requested_tier
    if requested_tier is None:
        return False, "tier_not_rescue_eligible", family, None, debug
    current_beam_plausible = _rescue_mode_current_beam_plausible(state, family=family, tier=requested_tier)
    debug["current_beam_plausible"] = bool(current_beam_plausible)
    if current_beam_plausible:
        return False, "current_beam_already_plausible", family, requested_tier, debug
    if str(stop_reason or "") in {"already_in_band", "reached_target_band"}:
        return False, "normal_one_click_retained_control", family, requested_tier, debug
    init_util = _candidate_objective_util(init_eval or {})
    try:
        init_u = float(init_util)
    except (TypeError, ValueError):
        init_u = None
    debug["initial_objective_util"] = init_u
    severe_fail = bool(
        init_u is not None
        and math.isfinite(init_u)
        and init_u >= 3.0
    )
    final_util = _candidate_objective_util(final_eval or {})
    try:
        final_u = float(final_util)
    except (TypeError, ValueError):
        final_u = None
    debug["final_objective_util"] = final_u
    both_fail = _rescue_mode_both_domains_fail_meanfully(init_eval, mode_config)
    debug["severe_fail"] = bool(severe_fail)
    debug["both_fail_meaningfully"] = bool(both_fail)
    if not severe_fail and not both_fail:
        return False, "severity_below_rescue_threshold", family, requested_tier, debug
    if (
        final_updates
        and not final_pass
        and final_u is not None
        and math.isfinite(final_u)
        and final_u > 1.10
        and str(stop_reason or "") == "best_available_out_of_band_candidate"
    ):
        return True, "normal_one_click_best_available_still_far_from_band", family, requested_tier, debug
    if not final_updates and str(stop_reason or "") in {
        "no_actionable_candidates",
        "no_actionable_candidates_after_full_tightening_search",
        "no_improving_candidate",
        "no_full_coverage_candidate",
        "no_multi_domain_target_candidate",
        "non_material_remaining_candidates",
    }:
        return True, "normal_one_click_no_direct_path_from_implausible_seed", family, requested_tier, debug
    if str(stop_reason or "") in {"no_full_coverage_candidate", "no_multi_domain_target_candidate"}:
        return True, "normal_one_click_stopped_outside_practical_neighborhood", family, requested_tier, debug
    return False, "normal_one_click_keep_control", family, requested_tier, debug


def _rescue_mode_eval_for_result(result: dict | None) -> dict | None:
    preview = dict((result or {}).get("final_state_preview") or {})
    if not preview:
        return None
    try:
        return evaluate_candidate_full(
            _build_canonical_design_state_pack(preview),
            source="rescue_mode_result_eval",
            label="Rescue result",
            action_type="rescue_mode",
            updates={},
        )
    except Exception:
        return None


def _rescue_mode_path_improved(rescue_eval: dict | None, base_eval: dict | None, mode_config: dict) -> bool:
    if not isinstance(rescue_eval, dict) or not isinstance(base_eval, dict):
        return False
    return bool(_one_click_step_improves(rescue_eval, base_eval, mode_config))


def _one_click_required_domain_progress(eval_obj: dict | None, mode_config: dict) -> dict:
    """
    Canonical solver-layer summary for required target domains.

    Distances describe how far the domain util is from the target band, but they do not
    by themselves mean the domain is satisfied. A domain can sit numerically inside the
    target band while still carrying FAIL status from the published truth layer. This
    summary keeps those concerns separate so ranking and improvement checks can prefer
    clearing required FAIL statuses before chasing smaller distance-only wins.
    """
    scores = _one_click_eval_domain_scores(eval_obj, mode_config)
    if not scores:
        util = _candidate_objective_util(eval_obj or {})
        try:
            util = float(util)
        except (TypeError, ValueError):
            util = None
        try:
            target_min = float(mode_config.get("target_util_min", EFFICIENCY_TARGET_UTIL_MIN) or EFFICIENCY_TARGET_UTIL_MIN)
            target_max = float(mode_config.get("target_util_max", EFFICIENCY_TARGET_UTIL_MAX) or EFFICIENCY_TARGET_UTIL_MAX)
        except (TypeError, ValueError, KeyError):
            target_min = float(EFFICIENCY_TARGET_UTIL_MIN)
            target_max = float(EFFICIENCY_TARGET_UTIL_MAX)
        overview = dict((eval_obj or {}).get("overview") or {})
        statuses = dict(overview.get("statuses") or {})
        all_key_pass = bool(overview.get("all_key_pass"))
        any_fail = any(
            status == BEAM_STATUS_FAIL or str(status or "").strip().upper() == "FAIL"
            for status in statuses.values()
        )
        ok_status = bool(all_key_pass and not any_fail)
        in_band = bool(util is not None and math.isfinite(float(util)) and target_min <= float(util) <= target_max and ok_status)
        distance = (
            float("inf")
            if util is None or not math.isfinite(float(util))
            else _distance_to_target_band(float(util), target_min, target_max)
        )
        return {
            "scores": {},
            "required_domain_count": 0,
            "required_fail_count": 0 if ok_status else 1,
            "required_unsatisfied_count": 0 if in_band else 1,
            "required_satisfied_count": 1 if in_band else 0,
            "required_fail_domains": [] if ok_status else ["objective"],
            "required_unsatisfied_domains": [] if in_band else ["objective"],
            "required_satisfied_domains": ["objective"] if in_band else [],
            "domain_total_distance": float(distance),
            "domain_max_distance": float(distance),
        }

    fail_domains: list[str] = []
    unsatisfied_domains: list[str] = []
    satisfied_domains: list[str] = []
    total = 0.0
    max_distance = float("-inf")

    for domain, score in scores.items():
        if not bool(score.get("pass")):
            fail_domains.append(domain)
        if bool(score.get("pass")) and bool(score.get("in_band")):
            satisfied_domains.append(domain)
        else:
            unsatisfied_domains.append(domain)
        dist = score.get("distance")
        if dist is None or not math.isfinite(float(dist)):
            total = float("inf")
            max_distance = float("inf")
            continue
        fd = float(dist)
        if not math.isfinite(total):
            continue
        total += fd
        max_distance = max(max_distance, fd)

    if max_distance == float("-inf"):
        max_distance = float("inf")

    return {
        "scores": scores,
        "required_domain_count": len(scores),
        "required_fail_count": len(fail_domains),
        "required_unsatisfied_count": len(unsatisfied_domains),
        "required_satisfied_count": len(satisfied_domains),
        "required_fail_domains": fail_domains,
        "required_unsatisfied_domains": unsatisfied_domains,
        "required_satisfied_domains": satisfied_domains,
        "domain_total_distance": float(total),
        "domain_max_distance": float(max_distance),
    }


def _one_click_domain_total_distance(eval_obj: dict | None, mode_config: dict) -> float:
    progress = _one_click_required_domain_progress(eval_obj, mode_config)
    return float(progress.get("domain_total_distance", float("inf")))


def _one_click_domain_max_distance(eval_obj: dict | None, mode_config: dict) -> float:
    progress = _one_click_required_domain_progress(eval_obj, mode_config)
    return float(progress.get("domain_max_distance", float("inf")))


def _one_click_required_domains_satisfied(eval_obj: dict | None, mode_config: dict) -> bool:
    if not isinstance(eval_obj, dict):
        return False
    progress = _one_click_required_domain_progress(eval_obj, mode_config)
    if int(progress.get("required_domain_count", 0) or 0) > 0:
        return int(progress.get("required_unsatisfied_count", 0) or 0) == 0
    return int(progress.get("required_unsatisfied_count", 0) or 0) == 0


def _one_click_domain_needs_cleanup(eval_obj: dict | None, domain: str, mode_config: dict) -> bool:
    score = _one_click_domain_score(eval_obj, domain, mode_config)
    return bool(score.get("pass") and score.get("under"))


def _one_click_bending_outcome_materially_preserved(
    current_eval: dict | None,
    candidate_eval: dict | None,
    mode_config: dict,
    *,
    distance_tolerance: float = 0.015,
) -> bool:
    current_bending = _one_click_domain_score(current_eval, "bending", mode_config)
    candidate_bending = _one_click_domain_score(candidate_eval, "bending", mode_config)
    if bool(current_bending.get("pass")) and not bool(candidate_bending.get("pass")):
        return False
    current_distance = float(current_bending.get("distance", float("inf")))
    candidate_distance = float(candidate_bending.get("distance", float("inf")))
    if not math.isfinite(current_distance):
        current_distance = float("inf")
    if not math.isfinite(candidate_distance):
        return False
    return bool(candidate_distance <= current_distance + float(max(distance_tolerance, 0.0)))


def _one_click_in_band_shear_cleanup_deferral(
    state: dict,
    eval_obj: dict | None,
    mode_config: dict,
) -> dict:
    snap = _guidance_state_snapshot(dict(state or {}))
    overview = dict((eval_obj or {}).get("overview") or {})
    actions_ctx = _build_design_actions_context_isolated(snap)
    actions = dict(actions_ctx.get("actions") or {})
    result = {
        "active": False,
        "reason": "not_applicable",
        "recommendation": None,
        "candidate_eval": None,
    }
    if not _shear_reinforcement_is_active(snap):
        result["reason"] = "inactive_links"
        return result
    shear_non_governing = bool(
        _shear_demands_negligible(actions)
        or _governing_focus_from_overview(overview) != "shear"
    )
    if not shear_non_governing:
        result["reason"] = "shear_still_governing"
        return result

    rec = _compute_shear_tightening_recommendation(snap, out_debug={})
    if not isinstance(rec, dict) or not dict(rec.get("updates") or {}):
        result["reason"] = "no_legal_shear_cleanup_path"
        return result

    updates = dict(rec.get("updates") or {})
    if not bool(set(updates) & _COMPOUND_SHEAR_UPDATE_KEYS):
        result["reason"] = "cleanup_not_shear_only"
        return result

    trial_state = dict(snap)
    trial_state.update(updates)
    candidate_eval = evaluate_candidate_full(
        _guidance_state_snapshot(trial_state),
        source="one_click_in_band_shear_cleanup_probe",
        updates=updates,
    )
    if candidate_eval is None or not bool((candidate_eval.get("overview") or {}).get("all_key_pass")):
        result["reason"] = "cleanup_candidate_not_all_pass"
        return result
    if not _one_click_bending_outcome_materially_preserved(eval_obj, candidate_eval, mode_config):
        result["reason"] = "cleanup_worsens_bending_materially"
        return result

    result.update(
        {
            "active": True,
            "reason": "blocked_non_governing_shear_cleanup_available",
            "recommendation": dict(rec),
            "candidate_eval": candidate_eval,
        },
    )
    return result


def _one_click_in_band_shear_cleanup_candidate_allowed(
    current_eval: dict | None,
    candidate_eval: dict | None,
    updates: dict | None,
    mode_config: dict,
) -> bool:
    resolved_updates = dict(updates or {})
    if not bool(set(resolved_updates) & _COMPOUND_SHEAR_UPDATE_KEYS):
        return False
    if not bool((candidate_eval or {}).get("overview", {}).get("all_key_pass")):
        return False
    if not _candidate_in_target_band(candidate_eval or {}, mode_config):
        return False
    return _one_click_bending_outcome_materially_preserved(current_eval, candidate_eval, mode_config)


def _one_click_best_next_hop_improving_candidate(
    current_eval: dict | None,
    mode_config: dict,
) -> dict | None:
    if not isinstance(current_eval, dict):
        return None
    overview = dict((current_eval.get("overview") or {}))
    if not bool(overview.get("all_key_pass")):
        return None
    if _one_click_strict_target_band_ok(overview, mode_config):
        return None
    current_distance = _candidate_target_band_distance(current_eval, mode_config)
    if current_distance is None or not math.isfinite(float(current_distance)):
        return None
    current_state = dict(current_eval.get("state") or {})
    if not current_state:
        return None
    current_target_domains = list(_candidate_target_domains_for_band(current_eval) or [])
    context = _build_auto_design_context(
        current_state,
        mode_config,
        reference_overview=overview,
    )
    candidate_states = generate_compliant_refinement_candidates(current_eval, mode_config, context)
    best_payload: dict | None = None
    for candidate_state in candidate_states:
        candidate_eval = evaluate_candidate_full(
            _build_canonical_design_state_pack(candidate_state),
            source="one_click_budget_stop_probe",
            label="Budget stop probe",
            action_type="one_click",
            updates={},
        )
        if candidate_eval is None:
            continue
        candidate_updates = _one_click_diff_accumulated_updates(current_state, candidate_state)
        if current_target_domains:
            candidate_target_domains = _one_click_target_domains_for_eval(
                current_target_domains,
                candidate_updates,
            )
            _one_click_attach_eval_target_domains(candidate_eval, candidate_target_domains, mode_config)
        candidate_overview = dict((candidate_eval.get("overview") or {}))
        if not bool(candidate_overview.get("all_key_pass")):
            continue
        if _one_click_has_unresolved_spacing_envelope_fail(candidate_eval):
            continue
        candidate_distance = _candidate_target_band_distance(candidate_eval, mode_config)
        if candidate_distance is None or not math.isfinite(float(candidate_distance)):
            continue
        if float(candidate_distance) + 1e-9 >= float(current_distance):
            continue
        if not _one_click_step_improves(candidate_eval, current_eval, mode_config):
            continue
        payload = {
            "state": dict(candidate_state),
            "eval": candidate_eval,
            "distance": float(candidate_distance),
            "updates": dict(candidate_updates),
        }
        if best_payload is None or float(payload["distance"]) < float(best_payload["distance"]) - 1e-9:
            best_payload = payload
    return best_payload


def _one_click_budget_stop_has_better_next_hop(
    current_eval: dict | None,
    mode_config: dict,
) -> bool:
    return _one_click_best_next_hop_improving_candidate(current_eval, mode_config) is not None


def _one_click_exhaustion_next_hop_allowed(
    current_eval: dict | None,
    next_hop_payload: dict | None,
    mode_config: dict,
) -> bool:
    if not isinstance(current_eval, dict) or not isinstance(next_hop_payload, dict):
        return False
    if not bool((current_eval.get("overview") or {}).get("all_key_pass")):
        return False
    current_domains = list(_candidate_target_domains_for_band(current_eval) or [])
    if len(current_domains) < 2:
        return False
    current_progress = _one_click_required_domain_progress(current_eval, mode_config)
    if int(current_progress.get("required_fail_count", 0) or 0) != 0:
        return False
    if int(current_progress.get("required_unsatisfied_count", 0) or 0) <= 1:
        return False
    candidate_eval = next_hop_payload.get("eval")
    if not isinstance(candidate_eval, dict):
        return False
    if not bool((candidate_eval.get("overview") or {}).get("all_key_pass")):
        return False
    candidate_progress = _one_click_required_domain_progress(candidate_eval, mode_config)
    if int(candidate_progress.get("required_fail_count", 0) or 0) != 0:
        return False
    if int(candidate_progress.get("required_unsatisfied_count", 0) or 0) > int(
        current_progress.get("required_unsatisfied_count", 0) or 0
    ):
        return False
    current_max = float(current_progress.get("domain_max_distance", float("inf")))
    candidate_max = float(candidate_progress.get("domain_max_distance", float("inf")))
    current_total = float(current_progress.get("domain_total_distance", float("inf")))
    candidate_total = float(candidate_progress.get("domain_total_distance", float("inf")))
    if not (
        math.isfinite(current_max)
        and math.isfinite(candidate_max)
        and math.isfinite(current_total)
        and math.isfinite(candidate_total)
    ):
        return False
    if candidate_max > current_max + 1e-6:
        return False
    if candidate_total >= current_total - 1e-6:
        return False
    return bool(_one_click_step_improves(candidate_eval, current_eval, mode_config))


def _candidate_in_target_band(candidate: dict, mode_config: dict) -> bool:
    if not isinstance(candidate, dict):
        return False
    return _one_click_required_domains_satisfied(candidate, mode_config)


def _one_click_strict_target_band_ok(overview: dict | None, mode_config: dict) -> bool:
    if not isinstance(overview, dict):
        return False
    try:
        lo = float(mode_config.get("target_util_min", EFFICIENCY_TARGET_UTIL_MIN) or EFFICIENCY_TARGET_UTIL_MIN)
        hi = float(mode_config.get("target_util_max", EFFICIENCY_TARGET_UTIL_MAX) or EFFICIENCY_TARGET_UTIL_MAX)
    except Exception:
        lo = float(EFFICIENCY_TARGET_UTIL_MIN)
        hi = float(EFFICIENCY_TARGET_UTIL_MAX)
    try:
        worst = float(
            overview.get("governing_util", overview.get("worst_util", 0.0)) or 0.0,
        )
    except (TypeError, ValueError):
        return False
    statuses = dict(overview.get("statuses") or {})
    any_fail = any(
        value == BEAM_STATUS_FAIL or str(value or "").strip().upper() == "FAIL"
        for value in statuses.values()
    )
    return bool(not any_fail and lo <= worst <= hi)


def _candidate_target_band_distance(candidate: dict, mode_config: dict) -> float:
    domains = _candidate_target_domains_for_band(candidate)
    if not domains:
        return _one_click_objective_distance_to_band(_candidate_objective_util(candidate), mode_config)
    return _one_click_domain_max_distance(candidate, mode_config)


def _candidate_target_band_total_distance(candidate: dict, mode_config: dict) -> float:
    return _one_click_domain_total_distance(candidate, mode_config)


def _candidate_target_band_under_domains(candidate: dict, mode_config: dict, *, margin: float = 0.0) -> bool:
    domains = _candidate_target_domains_for_band(candidate)
    if not domains:
        return False
    try:
        lo = float(mode_config.get("target_util_min", EFFICIENCY_TARGET_UTIL_MIN) or EFFICIENCY_TARGET_UTIL_MIN)
    except Exception:
        lo = float(EFFICIENCY_TARGET_UTIL_MIN)
    m = float(max(0.0, margin))
    for dom in domains:
        u = _candidate_domain_util(candidate, dom)
        if u is None or not math.isfinite(float(u)):
            continue
        if float(u) < lo - m:
            return True
    return False


def _candidate_target_domain_needing_work(candidate: dict, mode_config: dict) -> str:
    domains = _candidate_target_domains_for_band(candidate)
    if not domains:
        return ""
    scored: list[tuple[int, float, int, str]] = []
    for dom in domains:
        score = _one_click_domain_score(candidate, dom, mode_config)
        if bool(score.get("in_band")):
            continue
        try:
            dist = float(score.get("distance"))
        except (TypeError, ValueError):
            dist = float("inf")
        if not math.isfinite(dist):
            dist = float("inf")
        status_weight = 1 if not bool(score.get("pass")) else 0
        order_weight = 1 if str(dom).strip().lower() == "shear" else 0
        scored.append((status_weight, dist, order_weight, str(dom).strip().lower()))
    if scored:
        scored.sort(key=lambda item: (item[0], item[1], item[2]), reverse=True)
        return scored[0][3]
    return ""


def _distance_to_target_band(util: float, target_min: float, target_max: float) -> float:
    try:
        u = float(util)
        lo = float(target_min)
        hi = float(target_max)
    except (TypeError, ValueError):
        return float("inf")
    if lo <= u <= hi:
        return 0.0
    if u < lo:
        return lo - u
    return u - hi


def _candidate_reaches_target_band_one_step(candidate: dict, mode_config: dict) -> bool:
    if not candidate or not bool(candidate.get("is_compliant")):
        return False
    return _candidate_in_target_band(candidate, mode_config)


def _annotate_candidate_target_band_metrics(candidate: dict, mode_config: dict) -> None:
    if not candidate:
        return
    try:
        util = float(_candidate_objective_util(candidate))
    except Exception:
        util = float(candidate.get("worst_util", 0.0) or 0.0)
    tmin = float(mode_config.get("target_util_min", EFFICIENCY_TARGET_UTIL_MIN) or EFFICIENCY_TARGET_UTIL_MIN)
    tmax = float(mode_config.get("target_util_max", EFFICIENCY_TARGET_UTIL_MAX) or EFFICIENCY_TARGET_UTIL_MAX)
    candidate["candidate_post_util"] = util
    candidate["candidate_distance_to_target_band"] = _distance_to_target_band(util, tmin, tmax)
    candidate["candidate_reaches_target_band"] = _candidate_reaches_target_band_one_step(candidate, mode_config)


def _candidate_in_target_zone(candidate: dict, mode_config: dict) -> bool:
    if not candidate:
        return False
    if not bool(candidate.get("is_compliant")):
        return False

    util = float(candidate.get("worst_util", 0.0) or 0.0)
    target_min = float(mode_config.get("target_util_min", 0.80) or 0.80)
    target_max = float(mode_config.get("target_util_max", 0.90) or 0.90)
    return target_min <= util <= target_max


def _candidate_violation_score(candidate: dict) -> float:
    util = float(candidate.get("worst_util", 0.0) or 0.0)
    overflow = max(util - 1.0, 0.0)
    fail_count = int(candidate.get("fail_count", 0) or 0)
    return overflow * 100.0 + fail_count * 25.0


def _score_auto_design_candidate_components(candidate: dict, mode_config: dict, seed_candidate: dict) -> dict:
    shear_practicality = _shear_candidate_practicality_metrics(
        candidate,
        dict(seed_candidate.get("state") or {}),
    )
    candidate.update(shear_practicality)
    util = _candidate_objective_util(candidate)
    target_min = float(mode_config["target_util_min"])
    target_max = float(mode_config["target_util_max"])
    target_mid = _mode_target_midpoint(mode_config)
    if util < target_min:
        util_penalty = (target_min - util) * 80.0
    elif util > target_max:
        util_penalty = (util - target_max) * 120.0
    else:
        util_penalty = abs(util - target_mid) * 24.0

    depth = float(candidate.get("depth", 0.0) or 0.0)
    width = float(candidate.get("width", 0.0) or 0.0)
    seed_depth = float(seed_candidate.get("depth", depth) or depth)
    depth_growth = max(depth - seed_depth, 0.0)
    depth_penalty = (depth / 50.0) * float(mode_config["geometry_penalty"])
    depth_penalty += (depth_growth / 25.0) * float(mode_config.get("depth_growth_multiplier", 1.0))
    width_penalty = (width / 50.0) * float(mode_config.get("width_penalty", 0.4))

    steel_area = float(candidate.get("Ast_bot", 0.0) or 0.0) + float(candidate.get("Ast_top", 0.0) or 0.0)
    steel_penalty = (steel_area / 100.0) * float(mode_config["steel_penalty"])
    congestion_penalty = float(candidate.get("reo_congestion_index", 0.0) or 0.0) * float(mode_config["reo_congestion_penalty"])
    row_penalty = max(int(candidate.get("row_count", 1) or 1) - 1, 0) * 2.0
    if mode_config.get("prefer_lower_reo_congestion"):
        row_penalty *= 1.75

    shear_density_penalty = 0.0
    if mode_config["label"] == "Less shear reinforcement":
        shear_density_penalty = float(candidate.get("shear_density", 0.0) or 0.0) * 0.08
    shallow_metrics = _shallower_beam_metrics(candidate, seed_candidate)
    shallowness_score = 0.0
    width_growth_penalty = 0.0
    reinforcement_growth_penalty = 0.0
    non_material_shallow_penalty = 0.0
    if str(mode_config.get("search_strategy", "balanced") or "balanced") == "shallow":
        shallowness_score = float(shallow_metrics.get("shallowness_score", 0.0) or 0.0)
        width_growth_penalty = float(shallow_metrics.get("width_growth", 0.0) or 0.0) * 0.9
        reinforcement_growth_penalty = float(shallow_metrics.get("reinforcement_growth", 0.0) or 0.0) * 0.06
        if not bool(shallow_metrics.get("materially_shallower")) and (
            float(shallow_metrics.get("width_growth", 0.0) or 0.0) >= 100.0
            or float(shallow_metrics.get("reinforcement_growth", 0.0) or 0.0) >= 150.0
        ):
            non_material_shallow_penalty = 60.0

    ductility_priority = _candidate_ductility_governs(seed_candidate)
    candidate["_ductility_priority"] = bool(ductility_priority)
    if ductility_priority:
        tier = _ductility_fix_tier(candidate, seed_candidate)
        candidate["_ductility_tier"] = int(tier)
        candidate["_ductility_tier_label"] = _ductility_tier_label(tier)
        candidate["_ductility_reason"] = _candidate_ductility_reason(candidate, seed_candidate)
    else:
        candidate.pop("_ductility_tier", None)
        candidate.pop("_ductility_tier_label", None)
        candidate.pop("_ductility_reason", None)

    if not bool(candidate.get("is_compliant")):
        total_score = (
            10000.0
            + _candidate_violation_score(candidate)
            + float(shear_practicality.get("shear_candidate_total_practicality_penalty", 0.0) or 0.0)
        )
        return {
            "util_penalty": util_penalty,
            "geometry_penalty": depth_penalty + width_penalty,
            "depth_penalty": depth_penalty,
            "width_penalty": width_penalty,
            "steel_penalty": steel_penalty,
            "congestion_penalty": congestion_penalty,
            "row_penalty": row_penalty,
            "shear_density_penalty": shear_density_penalty,
            "goal_bias_penalty": 0.0,
            "shear_improvement_contribution": util_penalty,
            "bending_efficiency_contribution": steel_penalty + row_penalty,
            "shear_candidate_odd_leg_penalty": shear_practicality.get("shear_candidate_odd_leg_penalty"),
            "shear_candidate_total_practicality_penalty": shear_practicality.get("shear_candidate_total_practicality_penalty"),
            "shallowness_score": shallowness_score,
            "width_growth_penalty": width_growth_penalty,
            "reinforcement_growth_penalty": reinforcement_growth_penalty,
            "total_score": total_score,
        }
    if ductility_priority:
        tier = int(candidate.get("_ductility_tier", 4) or 4)
        ductility_util = _candidate_ductility_util(candidate)
        seed_ductility_util = _candidate_ductility_util(seed_candidate)
        ductility_overflow = max((float(ductility_util) if ductility_util is not None else 999.0) - 1.0, 0.0)
        ductility_penalty = ductility_overflow * 1200.0
        if ductility_util is None:
            ductility_penalty += 200.0
        else:
            ductility_penalty += float(ductility_util) * 120.0
        if ductility_util is not None and seed_ductility_util is not None and float(ductility_util) >= float(seed_ductility_util) - 1e-6:
            ductility_penalty += 140.0
        ast_growth = max(float(candidate.get("Ast_bot", 0.0) or 0.0) - float(seed_candidate.get("Ast_bot", 0.0) or 0.0), 0.0)
        steel_growth_penalty = ast_growth * 0.06
        depth_growth_penalty = max(depth - seed_depth, 0.0) * 0.9
        width_growth_penalty = max(width - float(seed_candidate.get("width", width) or width), 0.0) * 0.15
        tier_penalty = {1: 0.0, 2: 10.0, 3: 30.0, 4: 55.0}.get(int(tier), 55.0)
        total_score = (
            (util_penalty * 0.3)
            + ductility_penalty
            + tier_penalty
            + (steel_penalty * 0.4)
            + steel_growth_penalty
            + (congestion_penalty * 0.8)
            + row_penalty
            + width_growth_penalty
            + depth_growth_penalty
            + shear_density_penalty
            + non_material_shallow_penalty
            + float(shear_practicality.get("shear_candidate_total_practicality_penalty", 0.0) or 0.0)
            - max(shallowness_score, 0.0) * 0.1
        )
        return {
            "util_penalty": util_penalty * 0.3,
            "geometry_penalty": width_growth_penalty + depth_growth_penalty,
            "depth_penalty": depth_growth_penalty,
            "width_penalty": width_growth_penalty,
            "steel_penalty": (steel_penalty * 0.4) + steel_growth_penalty,
            "congestion_penalty": congestion_penalty * 0.8,
            "row_penalty": row_penalty,
            "shear_density_penalty": shear_density_penalty,
            "goal_bias_penalty": tier_penalty,
            "shear_improvement_contribution": util_penalty * 0.3,
            "bending_efficiency_contribution": ductility_penalty,
            "shear_candidate_odd_leg_penalty": shear_practicality.get("shear_candidate_odd_leg_penalty"),
            "shear_candidate_total_practicality_penalty": shear_practicality.get("shear_candidate_total_practicality_penalty"),
            "shallowness_score": shallowness_score,
            "width_growth_penalty": width_growth_penalty,
            "reinforcement_growth_penalty": reinforcement_growth_penalty,
            "total_score": total_score,
        }

    shallow_delta_d_extra = 0.0
    shallow_same_d_bonus = 0.0
    if str(mode_config.get("search_strategy", "balanced") or "balanced") == "shallow":
        sd = float(seed_candidate.get("depth", depth) or depth)
        delta_d_grow = max(depth - sd, 0.0)
        shallow_delta_d_extra = delta_d_grow * 3.4
        if delta_d_grow <= 1e-9:
            shallow_same_d_bonus = -48.0

    compound_width_reo_bonus = 0.0
    if (
        str(mode_config.get("search_strategy", "balanced") or "balanced") == "shallow"
        and bool(candidate.get("recommendation_compound"))
        and str(candidate.get("compound_geo_axis") or "") == "width"
    ):
        sd = float(seed_candidate.get("depth", depth) or depth)
        if depth <= sd + 1e-9:
            compound_width_reo_bonus = -18.0

    total_score = (
        util_penalty
        + depth_penalty
        + width_penalty
        + steel_penalty
        + congestion_penalty
        + row_penalty
        + shear_density_penalty
        + width_growth_penalty
        + reinforcement_growth_penalty
        + non_material_shallow_penalty
        + shallow_delta_d_extra
        + shallow_same_d_bonus
        + compound_width_reo_bonus
        + float(shear_practicality.get("shear_candidate_total_practicality_penalty", 0.0) or 0.0)
        - max(shallowness_score, 0.0) * 0.6
    )
    return {
        "util_penalty": util_penalty,
        "geometry_penalty": depth_penalty + width_penalty,
        "depth_penalty": depth_penalty,
        "width_penalty": width_penalty,
        "steel_penalty": steel_penalty,
        "congestion_penalty": congestion_penalty,
        "row_penalty": row_penalty,
        "shear_density_penalty": shear_density_penalty,
        "goal_bias_penalty": 0.0,
        "shear_improvement_contribution": util_penalty,
        "bending_efficiency_contribution": steel_penalty + row_penalty,
        "shear_candidate_odd_leg_penalty": shear_practicality.get("shear_candidate_odd_leg_penalty"),
        "shear_candidate_total_practicality_penalty": shear_practicality.get("shear_candidate_total_practicality_penalty"),
        "shallowness_score": shallowness_score,
        "width_growth_penalty": width_growth_penalty,
        "reinforcement_growth_penalty": reinforcement_growth_penalty,
        "shallow_delta_d_extra": shallow_delta_d_extra,
        "shallow_same_d_bonus": shallow_same_d_bonus,
        "compound_width_reo_bonus": compound_width_reo_bonus,
        "total_score": total_score,
    }


def _score_auto_design_candidate(candidate: dict, mode_config: dict, seed_candidate: dict) -> float:
    components = _score_auto_design_candidate_components(candidate, mode_config, seed_candidate)
    candidate["_score_components"] = dict(components)
    return float(components.get("total_score", 0.0) or 0.0)


def _shear_candidate_practicality_metrics(candidate: dict, current_state: dict) -> dict[str, float | int]:
    cs = dict(candidate.get("state") or {})
    cur_legs = max(int(_int_from_state(current_state, "lig_legs", 0) or 0), 0)
    cand_legs = max(int(_int_from_state(cs, "lig_legs", cur_legs) or cur_legs), 0)
    cur_s = float(_float_from_state(current_state, "s_lig", 0.0) or 0.0)
    cand_s = float(_float_from_state(cs, "s_lig", cur_s) or cur_s)
    cur_dia = max(int(_int_from_state(current_state, "lig_d", 0) or 0), 0)
    cand_dia = max(int(_int_from_state(cs, "lig_d", cur_dia) or cur_dia), 0)
    cur_depth = float(_float_from_state(current_state, "D", 0.0) or 0.0)
    cand_depth = float(_float_from_state(cs, "D", cur_depth) or cur_depth)
    cur_width = float(_design_width_value(current_state) or 0.0)
    cand_width = float(_design_width_value(cs) or cur_width)
    cur_ast_bot = float(_float_from_state(current_state, "Ast_bot", 0.0) or 0.0)
    cur_ast_top = float(_float_from_state(current_state, "Ast_top", 0.0) or 0.0)
    cur_ast = cur_ast_bot + cur_ast_top
    cand_ast = (
        float(candidate.get("Ast_bot", _float_from_state(cs, "Ast_bot", cur_ast_bot)) or 0.0)
        + float(candidate.get("Ast_top", _float_from_state(cs, "Ast_top", cur_ast_top)) or 0.0)
    )

    leg_delta = abs(int(cand_legs) - int(cur_legs))
    spacing_delta = abs(float(cand_s) - float(cur_s))
    dia_delta = abs(int(cand_dia) - int(cur_dia))
    depth_delta = abs(float(cand_depth) - float(cur_depth))
    width_delta = abs(float(cand_width) - float(cur_width))
    steel_delta = abs(float(cand_ast) - float(cur_ast))
    odd_leg_penalty = 0.015 if cand_legs > 0 and cand_legs % 2 == 1 else 0.0
    total_practicality_penalty = odd_leg_penalty + (float(leg_delta) * 0.01)
    geometry_escalation_flag = 1 if (depth_delta > 1e-9 or width_delta > 1e-9) else 0
    geometry_delta = depth_delta + width_delta
    engineering_change = (
        (5.0 if geometry_escalation_flag else 0.0)
        + float(leg_delta)
        + (spacing_delta / 100.0)
        + (dia_delta / 2.0)
        + (geometry_delta / 100.0)
        + (steel_delta / 500.0)
        + total_practicality_penalty
    )
    return {
        "shear_candidate_leg_count": int(cand_legs),
        "shear_candidate_leg_delta": int(leg_delta),
        "shear_candidate_spacing_delta": float(spacing_delta),
        "shear_candidate_dia_delta": int(dia_delta),
        "shear_candidate_depth_delta": float(depth_delta),
        "shear_candidate_width_delta": float(width_delta),
        "shear_candidate_geometry_delta": float(geometry_delta),
        "shear_candidate_geometry_escalation_flag": int(geometry_escalation_flag),
        "shear_candidate_steel_delta": float(steel_delta),
        "shear_candidate_odd_leg_penalty": float(odd_leg_penalty),
        "shear_candidate_total_practicality_penalty": float(total_practicality_penalty),
        "shear_candidate_engineering_change": float(engineering_change),
    }


def _score_band_reaching_candidate_for_goal(
    candidate: dict,
    goal: str,
    current_state: dict,
    mode_config: dict,
) -> tuple[float, str]:
    cs = dict(candidate.get("state") or {})
    d0 = float(_float_from_state(current_state, "D", 0.0) or 0.0)
    d1 = float(_float_from_state(cs, "D", d0) or d0)
    w0 = float(_design_width_value(current_state) or 0.0)
    w1 = float(_design_width_value(cs) or w0)
    ast0 = float(_float_from_state(current_state, "Ast_bot", 0.0) or 0.0)
    ast1 = float(candidate.get("Ast_bot", _float_from_state(cs, "Ast_bot", ast0)) or ast0)
    delta_d = max(d1 - d0, 0.0)
    delta_w = max(w1 - w0, 0.0)
    delta_ast = max(ast1 - ast0, 0.0)
    post_util = float(candidate.get("candidate_post_util", _candidate_objective_util(candidate)) or 0.0)
    target_mid = _mode_target_midpoint(mode_config)
    congestion = float(candidate.get("reo_congestion_index", 0.0) or 0.0)
    row_pen = max(int(candidate.get("row_count", 1) or 1) - 2, 0)

    if goal == "shallower_beam":
        score = (
            (delta_d * 2000.0)
            + (d1 * 0.6)
            + (delta_ast * 0.08)
            + (delta_w * 0.04)
            + (congestion * 20.0)
            + (row_pen * 8.0)
        )
        if (
            bool(candidate.get("recommendation_compound"))
            and str(candidate.get("compound_geo_axis") or "") == "width"
            and delta_d <= 1e-6
        ):
            score -= 30.0
        return score, "shallower_prefers_min_depth_then_steel_then_width"

    score = (
        (abs(post_util - target_mid) * 90.0)
        + (delta_d * 0.3)
        + (delta_w * 0.25)
        + (delta_ast * 0.04)
        + (congestion * 18.0)
        + (row_pen * 8.0)
    )
    return score, "balanced_prefers_practical_low_congestion_near_target_mid"


def _band_reacher_delta_metrics(candidate: dict, current_state: dict) -> dict:
    cs = dict(candidate.get("state") or {})
    d0 = float(_float_from_state(current_state, "D", 0.0) or 0.0)
    d1 = float(_float_from_state(cs, "D", d0) or d0)
    w0 = float(_design_width_value(current_state) or 0.0)
    w1 = float(_design_width_value(cs) or w0)
    ast0 = float(_float_from_state(current_state, "Ast_bot", 0.0) or 0.0)
    ast1 = float(candidate.get("Ast_bot", _float_from_state(cs, "Ast_bot", ast0)) or ast0)
    return {
        "result_depth": d1,
        "delta_d": max(d1 - d0, 0.0),
        "delta_w": max(w1 - w0, 0.0),
        "delta_ast": max(ast1 - ast0, 0.0),
        "congestion": float(candidate.get("reo_congestion_index", 0.0) or 0.0),
        "row_pen": max(int(candidate.get("row_count", 1) or 1) - 2, 0),
    }


def _select_best_auto_design_candidate(candidates: list[dict], mode_config: dict, seed_candidate: dict) -> dict | None:
    if not candidates:
        return None
    valid_candidates: list[dict] = []
    for candidate in candidates:
        cs = dict(candidate.get("state") or {})
        beam_width = float(_design_width_value(cs) or 0.0)
        cover = float(_float_from_state(cs, "cover_side", 40.0) or 40.0)
        bot1_count = int(_int_from_state(cs, "bot1_count", 0) or 0)
        bot2_count = int(_int_from_state(cs, "bot2_count", 0) or 0)
        db_bot_1 = float(_float_from_state(cs, "db_bot_1", 0.0) or 0.0)
        db_bot_2 = float(_float_from_state(cs, "db_bot_2", db_bot_1) or db_bot_1)

        row1_valid = is_valid_reo_layout(
            bot1_count,
            db_bot_1,
            beam_width,
            cover,
            max(db_bot_1, 25.0),
        )
        row2_valid = True
        if bot2_count > 0:
            row2_valid = is_valid_reo_layout(
                bot2_count,
                db_bot_2,
                beam_width,
                cover,
                max(db_bot_2, 25.0),
            )
        if not row1_valid or not row2_valid:
            continue  # reject immediately

        _annotate_candidate_target_band_metrics(candidate, mode_config)
        candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
        valid_candidates.append(candidate)
    candidates = valid_candidates
    if not candidates:
        return None
    strategy = str(mode_config.get("search_strategy", "balanced") or "balanced")
    compliant = [candidate for candidate in candidates if candidate.get("is_compliant")]
    band_reachers = [candidate for candidate in compliant if candidate.get("candidate_reaches_target_band")]
    one_click_available = len(band_reachers) > 0
    current_in_band = bool(seed_candidate.get("is_compliant")) and _candidate_in_target_band(seed_candidate, mode_config)
    in_band = [candidate for candidate in compliant if _candidate_in_target_band(candidate, mode_config)]
    best_scored_compliant = (
        (
            min(compliant, key=lambda item: _shallower_beam_selection_key(item, seed_candidate, mode_config))
            if strategy == "shallow" else
            min(compliant, key=lambda item: (item["score"], item["depth"], item["width"]))
        )
        if compliant else None
    )
    best_scored_in_band = (
        (
            min(in_band, key=lambda item: _shallower_beam_selection_key(item, seed_candidate, mode_config))
            if strategy == "shallow" else
            min(in_band, key=lambda item: (item["score"], item["depth"], item["width"]))
        )
        if in_band else None
    )
    if _ACTIVE_GUIDANCE_RANK_TRACE is not None:
        local_only = bool(compliant) and not one_click_available
        reason = (
            "at_least_one_compliant_candidate_reaches_target_band_in_one_move"
            if one_click_available
            else (
                "no_compliant_candidate_reaches_target_band_in_one_move"
                if compliant
                else "no_compliant_candidates"
            )
        )
        _merge_design_guide_rank_trace(
            {
                "auto_design_convergence_selection": {
                    "one_click_convergence_available": one_click_available,
                    "one_click_convergence_reason": reason,
                    "local_step_selected_only_because_no_band_reaching_candidate": local_only,
                    "compliant_count": len(compliant),
                    "band_reacher_count": len(band_reachers),
                    "winner_pool_mode": (
                        "band_reachers_only"
                        if (not current_in_band and bool(band_reachers))
                        else "all_compliant"
                    ),
                    "band_reacher_labels_considered": [
                        str(c.get("label") or "")[:100]
                        for c in band_reachers[:24]
                    ],
                },
            },
        )
    winner: dict | None = None
    selected_because_band = False
    winner_pool_mode = "all_compliant"
    winner_goal_score: float | None = None
    runner_up_goal_score: float | None = None
    goal_tie_break_reason: str | None = None
    if compliant:
        force_band_reacher_pool = bool((not current_in_band) and band_reachers)
        if force_band_reacher_pool:
            pool = band_reachers
            selected_because_band = True
            winner_pool_mode = "band_reachers_only"
        else:
            pool = compliant
            selected_because_band = False
            winner_pool_mode = "all_compliant"
        if selected_because_band:
            goal = _design_optimisation_goal(dict(seed_candidate.get("state") or {}))
            pref = "shallower" if goal == "shallower_beam" else "balanced"
            current_state = dict(seed_candidate.get("state") or {})
            ranked_pool: list[tuple[tuple, dict]] = []
            for item in pool:
                gscore, greason = _score_band_reaching_candidate_for_goal(
                    item,
                    goal,
                    current_state,
                    mode_config,
                )
                deltas = _band_reacher_delta_metrics(item, current_state)
                item["winning_candidate_goal_preference"] = pref
                item["candidate_goal_score"] = gscore
                item["candidate_goal_tie_break_reason"] = greason
                item["candidate_goal_delta_d_mm"] = deltas.get("delta_d")
                item["candidate_goal_delta_ast_mm2"] = deltas.get("delta_ast")
                item["candidate_goal_delta_w_mm"] = deltas.get("delta_w")
                if goal == "shallower_beam":
                    rank_key = (
                        float(gscore),
                        float(deltas.get("result_depth", item.get("depth", 0.0)) or 0.0),
                        float(deltas.get("delta_ast", 0.0) or 0.0),
                        float(deltas.get("delta_w", 0.0) or 0.0),
                        _shallower_beam_selection_key(item, seed_candidate, mode_config) if strategy == "shallow" else (),
                        float(item.get("score", 0.0) or 0.0),
                        float(item.get("depth", 0.0) or 0.0),
                        float(item.get("width", 0.0) or 0.0),
                    )
                else:
                    rank_key = (
                        float(gscore),
                        float(item.get("score", 0.0) or 0.0),
                        float(deltas.get("congestion", 0.0) or 0.0),
                        float(deltas.get("row_pen", 0.0) or 0.0),
                        float(deltas.get("delta_d", 0.0) or 0.0),
                        float(deltas.get("delta_w", 0.0) or 0.0),
                        float(deltas.get("delta_ast", 0.0) or 0.0),
                        float(item.get("depth", 0.0) or 0.0),
                        float(item.get("width", 0.0) or 0.0),
                    )
                ranked_pool.append((rank_key, item))
            ranked_pool.sort(key=lambda row: row[0])
            winner = ranked_pool[0][1]
            winner_goal_score = float(winner.get("candidate_goal_score", 0.0) or 0.0)
            goal_tie_break_reason = str(winner.get("candidate_goal_tie_break_reason") or "")
            if len(ranked_pool) > 1:
                runner = ranked_pool[1][1]
                runner_up_goal_score = float(runner.get("candidate_goal_score", 0.0) or 0.0)
                winner["runner_up_goal_score"] = runner_up_goal_score
        else:
            if strategy == "shallow":
                winner = min(pool, key=lambda item: _shallower_beam_selection_key(item, seed_candidate, mode_config))
            else:
                winner = min(
                    pool,
                    key=lambda item: (
                        item["score"],
                        float(item.get("candidate_distance_to_target_band") or 0.0),
                        item["depth"],
                        item["width"],
                    ),
                )
    else:
        winner = min(
            candidates,
            key=lambda item: (
                _candidate_violation_score(item),
                _shallower_beam_selection_key(item, seed_candidate, mode_config) if strategy == "shallow" else (),
                item["score"],
                item["depth"],
                item["width"],
            ),
        )
        selected_because_band = False
    if winner is not None:
        winner["winning_candidate_post_util"] = winner.get("candidate_post_util")
        winner["winning_candidate_reaches_target_band"] = winner.get("candidate_reaches_target_band")
        winner["winning_candidate_distance_to_target_band"] = winner.get("candidate_distance_to_target_band")
        winner["winning_candidate_selected_because_reaches_band"] = selected_because_band
        winner["winning_candidate_selected_from_band_reachers"] = selected_because_band
        winner["winner_pool_mode"] = winner_pool_mode
        winner["band_reacher_labels_considered"] = [str(c.get("label") or "")[:100] for c in band_reachers[:24]]
        winner["winning_candidate_goal_score"] = winner_goal_score
        winner["runner_up_goal_score"] = runner_up_goal_score
        winner["goal_tie_break_reason"] = goal_tie_break_reason
        winner["winning_candidate_goal_preference"] = (
            "shallower"
            if _design_optimisation_goal(dict(seed_candidate.get("state") or {})) == "shallower_beam"
            else "balanced"
        )
        _wl = str(winner.get("label") or "").strip()
        if _wl:
            winner["canonical_winner_label"] = _wl
            winner["title_locked_from_final_winner"] = True
        if _ACTIVE_GUIDANCE_RANK_TRACE is not None:
            _merge_design_guide_rank_trace(
                {
                    "auto_design_goal_tie_break": {
                        "winning_candidate_goal_score": winner_goal_score,
                        "runner_up_goal_score": runner_up_goal_score,
                        "goal_tie_break_reason": goal_tie_break_reason,
                        "winning_candidate_goal_preference": winner.get("winning_candidate_goal_preference"),
                        "winner_label": str(winner.get("label") or ""),
                    },
                    "auto_design_final_selector": {
                        "winner_pool_mode": winner_pool_mode,
                        "selected_because_band": selected_because_band,
                        "final_winner_label": str(winner.get("label") or ""),
                        "final_winner_reaches_target_band": bool(winner.get("candidate_reaches_target_band")),
                        "final_winner_post_util": winner.get("candidate_post_util"),
                        "final_winner_goal_score": winner_goal_score,
                    },
                },
            )
    return winner


def _shear_candidate_selector_key(candidate: dict, seed_candidate: dict, mode_config: dict) -> tuple:
    current_state = dict(seed_candidate.get("state") or {})
    _annotate_candidate_target_band_metrics(candidate, mode_config)
    metrics = _shear_candidate_practicality_metrics(candidate, current_state)
    candidate.update(metrics)
    post_util = candidate.get("candidate_post_util", candidate.get("worst_util"))
    try:
        post_util_f = float(post_util) if post_util is not None else float("inf")
    except (TypeError, ValueError):
        post_util_f = float("inf")
    return (
        0 if bool(candidate.get("is_compliant")) else 1,
        0 if _candidate_in_target_band(candidate, mode_config) else 1,
        float(candidate.get("candidate_distance_to_target_band") or _candidate_util_distance(candidate, mode_config) or 0.0),
        float(metrics.get("shear_candidate_engineering_change", 0.0) or 0.0),
        int(metrics.get("shear_candidate_leg_delta", 0) or 0),
        float(metrics.get("shear_candidate_spacing_delta", 0.0) or 0.0),
        int(metrics.get("shear_candidate_dia_delta", 0) or 0),
        int(metrics.get("shear_candidate_geometry_escalation_flag", 0) or 0),
        float(metrics.get("shear_candidate_geometry_delta", 0.0) or 0.0),
        float(metrics.get("shear_candidate_steel_delta", 0.0) or 0.0),
        float(metrics.get("shear_candidate_total_practicality_penalty", 0.0) or 0.0),
        float(candidate.get("score", 0.0) or 0.0),
        post_util_f,
        float(candidate.get("depth", 0.0) or 0.0),
        float(candidate.get("width", 0.0) or 0.0),
    )


def _shear_change_magnitude(candidate: dict, state: dict) -> tuple:
    cs = dict(candidate.get("state") or {})
    cur_legs = max(_int_from_state(state, "lig_legs", 2), 2)
    cur_s = float(_float_from_state(state, "s_lig", 0.0) or 0.0)
    cur_dia = max(_int_from_state(state, "lig_d", 10), 10)
    _, _, cur_w = _resolve_geometry_width_context(state)
    cur_d = float(_float_from_state(state, "D", 600.0) or 600.0)

    cand_legs = max(_int_from_state(cs, "lig_legs", cur_legs), 0)
    cand_s = float(_float_from_state(cs, "s_lig", cur_s) or cur_s)
    cand_dia = max(_int_from_state(cs, "lig_d", cur_dia), 0)
    _, _, cand_w = _resolve_geometry_width_context(cs)
    cand_d = float(_float_from_state(cs, "D", cur_d) or cur_d)

    leg_delta = abs(cand_legs - cur_legs)
    spacing_delta = abs(cand_s - cur_s)
    dia_delta = abs(cand_dia - cur_dia)
    depth_delta = abs(cand_d - cur_d)
    width_delta = abs(cand_w - cur_w)

    return (
        int(depth_delta > 1e-9 or width_delta > 1e-9),
        leg_delta,
        spacing_delta,
        dia_delta,
        depth_delta,
        width_delta,
    )


def _shortlist_smallest_successful_shear_candidates(
    candidates: list[dict],
    state: dict,
    *,
    target_hi: float | None,
) -> list[dict]:
    if not candidates:
        return []

    acceptable: list[dict] = []
    for cand in candidates:
        if not bool(cand.get("is_compliant")):
            continue
        su = _shear_util_from_overview_candidate(cand)
        if su is None:
            continue
        if target_hi is not None and float(su) > float(target_hi) + 1e-9:
            continue
        acceptable.append(cand)

    if not acceptable:
        return list(candidates)

    ranked = sorted(
        acceptable,
        key=lambda c: (
            _shear_change_magnitude(c, state),
            float(c.get("score", 0.0) or 0.0),
        ),
    )

    keep = [
        c for c in ranked
        if _shear_change_magnitude(c, state) == _shear_change_magnitude(ranked[0], state)
        or float(c.get("score", 999999.0) or 999999.0)
        <= float(ranked[0].get("score", 999999.0) or 999999.0) + 0.25
    ]
    return keep


def _candidate_is_within_smallest_fix_band(
    candidate: dict,
    smallest_mag: tuple | None,
    state: dict,
) -> bool:
    if smallest_mag is None:
        return True
    cand_mag = _shear_change_magnitude(candidate, state)
    return cand_mag <= smallest_mag


def _reinforcement_options_remain(state: dict) -> bool:
    count_1 = _int_from_state(state, "bot1_count", 0)
    count_2 = _int_from_state(state, "bot2_count", 0)
    dia_1 = _int_from_state(state, "db_bot_1", 0)
    dia_2 = _int_from_state(state, "db_bot_2", dia_1 or 0)
    can_increase_bar_count = count_1 < max(REO_COUNTS_0_12)
    can_grow_second_row = count_2 < max(REO_COUNTS_0_12)
    can_add_row = count_1 > 0 and count_2 <= 0
    can_increase_bar_dia = dia_1 < max(REO_BAR_DIAS) or dia_2 < max(REO_BAR_DIAS)
    can_rebalance = count_1 > 2 and count_1 != count_2
    return any((
        can_increase_bar_count,
        can_grow_second_row,
        can_add_row,
        can_increase_bar_dia,
        can_rebalance,
    ))


def _candidate_materially_improves(current_candidate: dict, trial_candidate: dict) -> bool:
    if not trial_candidate:
        return False
    current_worst = float(current_candidate.get("worst_util", float("inf")) or float("inf"))
    trial_worst = float(trial_candidate.get("worst_util", float("inf")) or float("inf"))
    if bool(trial_candidate.get("is_compliant")) and not bool(current_candidate.get("is_compliant")):
        return True
    return trial_worst < current_worst - 1e-6


def _geometry_changes_allowed(
    candidate: dict,
    goal: str,
    *,
    bottom_candidates: list[dict] | None = None,
    shear_candidates: list[dict] | None = None,
) -> bool:
    if _geometry_lock_enabled((candidate or {}).get("state") or {}):
        return False
    return True


def _generate_bottom_reo_candidates(state: dict, mode_config: dict) -> list[dict]:
    from section_layout import compute_bar_layout_pure
    started_at = time.perf_counter()


    b = _design_width_value(state)
    cover_side = _float_from_state(state, "cover_side", 40.0)
    rowgap_bot = _float_from_state(state, "rowgap_bot", 60.0)
    candidates: list[dict] = []
    seed_candidate = _evaluate_auto_design_candidate(state, source="seed")
    arrangement_attempts = 0
    bending_preview_total_ms = 0.0
    full_eval_total_ms = 0.0
    required_ast_total_ms = 0.0
    updates_and_label_total_ms = 0.0
    layout_cache: dict[tuple[int, int], dict] = {}

    for dia in REO_BAR_DIAS:
        s_min = max(float(dia), 25.0)

        def _layout_for_count(count: int) -> dict:
            cache_key = (int(dia), int(count))
            cached = layout_cache.get(cache_key)
            if cached is not None:
                return cached
            layout = compute_bar_layout_pure(
                b=b,
                cover_side=cover_side,
                nb_or_s=float(count),
                db=float(dia),
                s_min=s_min,
                rowgap=rowgap_bot,
            )
            layout_cache[cache_key] = layout
            return layout

        for count_1 in range(2, 13):
            layout_1 = _layout_for_count(count_1)
            if not layout_1.get("fits_single_row", False):
                continue
            for count_2 in range(0, 13):
                if count_2 > 0:
                    layout_2 = _layout_for_count(count_2)
                    if not layout_2.get("fits_single_row", False):
                        continue
                arrangement = _normalise_bottom_layer_order({
                    "bot1_layout_mode": "Count",
                    "bot1_count": count_1,
                    "db_bot_1": dia,
                    "bot2_layout_mode": "Count",
                    "bot2_count": count_2,
                    "db_bot_2": dia,
                })
                arrangement_attempts += 1
                bending_started_at = time.perf_counter()
                bending = _evaluate_bending_with_bottom_state(state, arrangement)
                bending_preview_total_ms += (time.perf_counter() - bending_started_at) * 1000
                if not bending:
                    continue
                as_min = float(bending.get("As_min", 0.0) or 0.0)
                actual_ast = float(bending.get("Ast_bot", 0.0) or 0.0)
                if actual_ast < as_min:
                    continue
                updates_started_at = time.perf_counter()
                updates = _bottom_arrangement_to_shared_updates(arrangement)
                label = _practical_bottom_reo_label(
                    int(arrangement.get("bot1_count", 0)),
                    int(arrangement.get("bot2_count", 0)),
                    int(arrangement.get("db_bot_1", dia)),
                )
                updates_and_label_total_ms += (time.perf_counter() - updates_started_at) * 1000
                eval_started_at = time.perf_counter()
                candidate = _evaluate_auto_design_candidate(
                    state,
                    updates=updates,
                    source="bottom_reo",
                    label=label,
                    action_type="apply_bottom_recommendation",
                )
                full_eval_total_ms += (time.perf_counter() - eval_started_at) * 1000
                if candidate is None:
                    continue
                candidate["arrangement"] = arrangement
                candidate["actual_ast"] = actual_ast
                candidates.append(candidate)
    score_total_ms = 0.0
    for candidate in candidates:
        score_started_at = time.perf_counter()
        candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
        score_total_ms += (time.perf_counter() - score_started_at) * 1000
    return candidates


def _generate_shear_candidates(state: dict, mode_config: dict) -> list[dict]:
    candidates: list[dict] = []
    current_active = _shear_reinforcement_is_active(state)
    seed_candidate = _evaluate_auto_design_candidate(state, source="seed")
    seed_shear_util = (((seed_candidate or {}).get("overview") or {}).get("utils") or {}).get("shear")
    severity_band = _shear_severity_band(seed_shear_util)
    candidate_state_items: list[tuple[str, dict]] = []
    if current_active:
        candidate_legs = [2, 4, 6]
        candidate_dias = [dia for dia in REO_BAR_DIAS if dia <= 16]
        spacing_values = sorted(REO_SPACINGS, reverse=True)
    else:
        candidate_legs = [2]
        candidate_dias = [_starter_shear_diameter(state)]
        spacing_values = [_starter_shear_spacing(state)]
    for dia in candidate_dias:
        for legs in candidate_legs:
            for spacing in spacing_values:
                candidate_state = dict(state)
                candidate_state.update({
                    "lig_d": dia,
                    "lig_legs": legs,
                    "s_lig": float(spacing),
                })
                candidate_state_items.append((_shear_candidate_type(state, candidate_state), candidate_state))
    if _severe_shear_failure(seed_shear_util):
        candidate_state_items.extend(_generate_escalated_shear_states(state, severity_band=severity_band))
    deduped_items: dict[tuple, tuple[str, dict]] = {}
    for candidate_type, candidate_state in candidate_state_items:
        deduped_items[_make_auto_design_candidate_key(candidate_state)] = (candidate_type, candidate_state)
    for candidate_type, candidate_state in deduped_items.values():
        updates = {
            key: value
            for key, value in candidate_state.items()
            if key in SHARED_DEFAULTS and state.get(key) != value
        }
        if _invalid_shear_spacing_change_without_activation(
            state,
            candidate_state,
            source="_generate_shear_candidates",
        ):
            continue
        candidate = _evaluate_auto_design_candidate(
            state,
            updates=updates,
            source="shear",
            label=f"{candidate_type.title()}: {_shear_state_label(candidate_state)}",
            action_type="apply_shear_recommendation",
        )
        if candidate is None:
            _log_shear_candidate_debug(
                source="_generate_shear_candidates",
                candidate_state=candidate_state,
                candidate=None,
            )
            continue
        candidate["shear_candidate_type"] = candidate_type
        if seed_candidate is not None:
            candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
        _log_shear_candidate_debug(
            source="_generate_shear_candidates",
            candidate_state=candidate_state,
            candidate=candidate,
        )
        candidates.append(candidate)
    if _severe_shear_failure(seed_shear_util) and seed_candidate is not None:
        existing_keys = {_make_auto_design_candidate_key(dict(candidate.get("state") or {})) for candidate in candidates}
        ranked_base = sorted(
            candidates,
            key=lambda item: _shear_recommendation_rank_key(
                item,
                base_state=state,
                severity_band=severity_band,
                seed_shear_util=seed_shear_util,
            ),
        )[:4]
        for base_candidate in ranked_base:
            for combined_state in _generate_secondary_bending_tightening_states(base_candidate, limit=3):
                combined_key = _make_auto_design_candidate_key(combined_state)
                if combined_key in existing_keys:
                    continue
                combined_updates = {
                    key: value
                    for key, value in combined_state.items()
                    if key in SHARED_DEFAULTS and state.get(key) != value
                }
                combined_candidate = _evaluate_auto_design_candidate(
                    state,
                    updates=combined_updates,
                    source="shear_combined",
                    label=(
                        f"Combined: {_shear_state_label(combined_state)}"
                        f" + {_bottom_reo_state_label(combined_state)}"
                    ),
                    action_type="apply_shear_recommendation",
                )
                if combined_candidate is None:
                    continue
                combined_candidate["shear_candidate_type"] = "combined"
                combined_candidate["secondary_actions_combined"] = True
                combined_candidate["score"] = _score_auto_design_candidate(combined_candidate, mode_config, seed_candidate)
                candidates.append(combined_candidate)
                existing_keys.add(combined_key)
    if _severe_shear_failure(seed_shear_util) and seed_candidate is not None:
        _log_severe_shear_escalation(
            source="_generate_shear_candidates",
            seed_candidate=seed_candidate,
            severity_band=severity_band,
            candidates=candidates,
            selected=None,
        )
    return candidates


def _shear_governing_fallback_resolved_candidate(state: dict, mode_cfg: dict) -> dict | None:
    """
    When bounded geometry+bottom one-click finds nothing but shear governs, pick the best
    compliant option from the same shear enumeration used elsewhere so the guide can show
    apply_resolved_candidate + post-apply util (not only reduce_link_spacing steps).
    """
    if not isinstance(state, dict):
        return None
    evaluated_list = _generate_shear_candidates(state, mode_cfg)
    compliant = [c for c in evaluated_list if isinstance(c, dict) and bool(c.get("is_compliant"))]
    if not compliant:
        return None

    def _rank(c: dict) -> tuple[float, float]:
        try:
            wu = float(c.get("worst_util", 999.0) or 999.0)
        except (TypeError, ValueError):
            wu = 999.0
        su_raw = ((c.get("overview") or {}).get("utils") or {}).get("shear")
        try:
            su = float(su_raw) if su_raw is not None else wu
        except (TypeError, ValueError):
            su = wu
        return (wu, su)

    best = sorted(compliant, key=_rank)[0]
    merged_updates = dict(best.get("updates") or {})
    if not merged_updates:
        return None
    _annotate_candidate_target_band_metrics(best, mode_cfg)
    resolved = dict(best)
    post_util = best.get("candidate_post_util", best.get("worst_util"))
    try:
        post_util = float(post_util) if post_util is not None else None
    except (TypeError, ValueError):
        post_util = None
    tmin = float(mode_cfg.get("target_util_min", EFFICIENCY_TARGET_UTIL_MIN) or EFFICIENCY_TARGET_UTIL_MIN)
    tmax = float(mode_cfg.get("target_util_max", EFFICIENCY_TARGET_UTIL_MAX) or EFFICIENCY_TARGET_UTIL_MAX)
    reaches_band = bool(post_util is not None and tmin <= post_util <= tmax)
    resolved["candidate_reaches_target_band"] = reaches_band
    resolved["reaches_target_band"] = reaches_band
    resolved["updates"] = merged_updates
    resolved["action_type"] = "apply_resolved_candidate"
    resolved["guidance_change_lines"] = _guidance_change_lines_for_updates(state, merged_updates)
    subfamilies = _compound_subfamilies_from_updates(merged_updates)
    resolved["subfamilies"] = list(subfamilies)
    resolved["recommendation_family_tag"] = _family_tag_from_compound_updates(merged_updates, state)
    title, _, _ = _compound_guidance_title_reasoning_why(
        state,
        merged_updates,
        subfamilies,
        strengthening=True,
    )
    resolved["label"] = str(title or best.get("label") or "Apply shear reinforcement upgrade")
    return resolved


def _best_bottom_candidate_for_state(state: dict, mode_config: dict) -> dict | None:
    candidates = _generate_bottom_reo_candidates(state, mode_config)
    return _select_best_auto_design_candidate(candidates, mode_config, _evaluate_auto_design_candidate(state, source="seed"))


def _generate_geometry_candidates(
    state: dict,
    mode_config: dict,
    current_candidate: dict,
    *,
    bottom_candidates: list[dict] | None = None,
    shear_candidates: list[dict] | None = None,
) -> list[dict]:
    started_at = time.perf_counter()
    if _geometry_lock_enabled(state):
        return []
    goal = _design_optimisation_goal(state)
    if not _geometry_changes_allowed(
        current_candidate,
        goal,
        bottom_candidates=bottom_candidates,
        shear_candidates=shear_candidates,
    ):
        return []

    width_key, _, current_width = _resolve_geometry_width_context(state)
    current_depth = _float_from_state(state, "D", 600.0)
    depth_min = current_depth - (200.0 if goal == "shallower_beam" else 100.0)
    depth_max = current_depth + (150.0 if goal == "shallower_beam" else 200.0)
    width_min = current_width - 100.0
    width_max = current_width + 150.0
    width_start = max(
        int(GUIDANCE_MIN_PRACTICAL_WIDTH_MM),
        int(math.floor(max(GUIDANCE_MIN_PRACTICAL_WIDTH_MM, width_min) / 50.0) * 50),
    )
    width_stop = int(math.ceil(width_max / 50.0) * 50) + 50
    depth_start = max(
        int(GUIDANCE_MIN_PRACTICAL_DEPTH_MM),
        int(math.floor(max(GUIDANCE_MIN_PRACTICAL_DEPTH_MM, depth_min) / 50.0) * 50),
    )
    depth_stop = int(math.ceil(depth_max / 50.0) * 50) + 50

    seed_candidate = _evaluate_auto_design_candidate(state, source="seed")
    candidates: list[dict] = []
    geometry_points_evaluated = 0
    for width in range(width_start, width_stop, 50):
        for depth in range(depth_start, depth_stop, 50):
            geometry_points_evaluated += 1
            geometry_updates = {width_key: float(width), "D": float(depth)}
            if width_key != "b":
                geometry_updates["b"] = float(width)
            combined_updates = dict(geometry_updates)
            candidate = _evaluate_auto_design_candidate(
                state,
                updates=combined_updates,
                source="geometry",
                label=f"{int(width)} x {int(depth)} mm",
                action_type="apply_geometry_recommendation",
            )
            if candidate is None:
                continue
            candidates.append(candidate)
    for candidate in candidates:
        candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
    return candidates


def _recommendation_search_allowed(state: dict) -> bool:
    design_context = _build_design_actions_context(state)
    guidance_state = dict(design_context.get("state") or _guidance_state_snapshot(state))
    overview = _collect_design_overview(guidance_state, context=design_context)
    return not _guidance_not_started(guidance_state, overview)


def _compute_bottom_reo_tightening_recommendation(state: dict) -> dict | None:
    state = _guidance_state_snapshot(state)
    current_bottom = _effective_bottom_design_state(state)
    current_ast = float(current_bottom.get("Ast_bot", 0.0) or 0.0)
    if current_ast <= 0.0:
        return None

    mode_config = _design_mode_config(_design_optimisation_goal(state))
    target_lo, target_hi, _ = _resolved_efficiency_target_band(mode_config, goal=_design_optimisation_goal(state))
    target_mid = (target_lo + target_hi) / 2.0
    seed_candidate = evaluate_candidate_full(state, source="guidance_bottom_seed")
    if not seed_candidate:
        return None
    context = _build_auto_design_context(
        seed_candidate["state"],
        mode_config,
        reference_overview=seed_candidate.get("overview"),
    )
    eval_cache: dict = {}
    metrics = {
        "_reference_overview": seed_candidate.get("overview"),
        "generated_count": 0,
        "unique_eval_count": 0,
        "cache_hits": 0,
        "fast_eval_total_ms": 0.0,
        "cap_hit": False,
    }

    candidates: list[dict] = []
    for band in range(2):
        for arrangement in _generate_local_bottom_arrangements(state, mode_config, band=band, context=context):
            candidate_state = dict(state)
            candidate_state.update(_bottom_arrangement_to_shared_updates(arrangement))
            candidate = _evaluate_candidate_fast(
                candidate_state,
                seed_state=seed_candidate["state"],
                context=context,
                eval_cache=eval_cache,
                metrics=metrics,
                source="guidance_bottom_tighten",
                label=_practical_bottom_reo_label(
                    int(arrangement.get("bot1_count", 0) or 0),
                    int(arrangement.get("bot2_count", 0) or 0),
                    int(arrangement.get("db_bot_1", 0) or 0),
                ),
                action_type="reduce_bottom_reinforcement",
            )
            if candidate is None:
                continue
            actual_ast = float(candidate.get("Ast_bot", 0.0) or 0.0)
            if not bool(candidate.get("is_compliant")) or actual_ast >= current_ast - 1e-6:
                continue
            candidate["actual_ast"] = actual_ast
            candidate["arrangement"] = arrangement
            candidates.append(candidate)

    if not candidates:
        return None

    best = min(
        candidates,
        key=lambda item: (
            0 if target_lo <= float(item.get("overview", {}).get("utils", {}).get("bending", 0.0) or 0.0) <= target_hi else 1,
            abs(float(item.get("overview", {}).get("utils", {}).get("bending", 0.0) or 0.0) - target_mid),
            int(item.get("row_count", 1) or 1),
            int(item.get("bar_count", 0) or 0),
            float(item.get("Ast_bot", 0.0) or 0.0),
        ),
    )
    return {
        "arrangement": dict(best.get("arrangement") or {}),
        "updates": _bottom_arrangement_to_shared_updates(dict(best.get("arrangement") or {})),
        "actual_ast": float(best.get("actual_ast", 0.0) or 0.0),
        "util": float(best.get("overview", {}).get("utils", {}).get("bending", 0.0) or 0.0),
        "label": str(best.get("label") or ""),
        "score": float(best.get("score", 0.0) or 0.0),
        "candidate_summary": _candidate_debug_summary(best),
        "candidate_type": "bottom",
    }


def _compute_shear_tightening_recommendation(state: dict, *, out_debug: dict | None = None) -> dict | None:
    dbg = out_debug if out_debug is not None else {}
    for _k, _v in _initialise_shear_link_optimisation_debug().items():
        dbg.setdefault(_k, _v)

    state = _guidance_state_snapshot(state)
    design_context = _build_design_actions_context(state)
    overview = _collect_design_overview(state, context=design_context)
    actions = design_context.get("actions") or {}
    _annotate_shear_link_state_debug_from_state(state, dbg)
    shear_pack_cur = (((overview or {}).get("packs") or {}).get("shear") or {})
    truth_allow_overdesign_cleanup, _truth_od_detail = _shear_governing_truth_allows_overdesign_cleanup(shear_pack_cur)
    dbg.update(dict(_truth_od_detail))

    # Canonical inactive fixup runs before activation; see docstring on _try_shear_canonical_inactive_fixup_recommendation.
    canon_rec = _try_shear_canonical_inactive_fixup_recommendation(state)
    if canon_rec:
        dbg["shear_tightening_terminal_reason"] = "canonical_inactive_storage_fixup"
        dbg["shear_link_state_is_canonical"] = True
        return canon_rec

    if not _shear_change_is_relevant(overview, actions) and not _shear_cleanup_possible(state):
        dbg["shear_tightening_terminal_reason"] = "not_relevant_no_cleanup"
        return None

    if _shear_demands_negligible(actions) and _shear_reinforcement_is_active(state):
        no_demand_rec = _try_shear_no_demand_cleanup_recommendation(state, overview, actions)
        if no_demand_rec:
            dbg["shear_overdesign_remove_links_candidate_seen"] = True
            dbg["shear_overdesign_remove_links_candidate_committed"] = True
            dbg["shear_tightening_terminal_reason"] = "no_demand_active_links_cleanup"
            return no_demand_rec
        dbg["shear_tightening_terminal_reason"] = "no_demand_not_meaningful_for_final_tightening"
        return None

    if not _shear_reinforcement_is_active(state):
        dbg["shear_underdesign_activation_candidate_seen"] = True
        _gate_payload = _combined_underdesign_shear_strengthening_truth_gate_payload(
            state,
            overview=overview,
            efficiency_classification=None,
        )
        dbg.update(_gate_payload)
        if bool(_gate_payload.get("combined_underdesign_shear_truth_block_active")):
            dbg["shear_underdesign_activation_candidate_committed"] = False
            dbg["shear_tightening_terminal_reason"] = "underdesign_shear_strengthening_truth_blocked"
            return None
        act_rec = _try_shear_activation_for_underdesign_recommendation(state, overview, actions)
        if act_rec:
            dbg["shear_underdesign_activation_candidate_committed"] = True
            dbg["shear_tightening_terminal_reason"] = "underdesign_activation"
            return act_rec
        dbg["shear_tightening_terminal_reason"] = "inactive_no_underdesign_activation"
        return None

    if not truth_allow_overdesign_cleanup:
        dbg["shear_tightening_terminal_reason"] = "overdesign_cleanup_blocked_governing_truth"
        dbg["shear_candidate_family_pure"] = True
        dbg.setdefault("shear_candidate_non_detailing_updates_detected", tuple())
        return None

    remove_rec = _try_shear_remove_links_tightening_recommendation(state, overview, dbg)
    if remove_rec:
        dbg["shear_overdesign_remove_links_candidate_committed"] = True
        dbg["shear_tightening_terminal_reason"] = "overdesign_remove_links"
        return remove_rec

    current_spacing = float(state.get("s_lig", 200.0) or 200.0)
    current_legs = int(state.get("lig_legs", 2) or 2)
    current_dia = int(state.get("lig_d", 10) or 10)
    current_density = (current_legs * max(current_dia, 1) ** 2) / max(current_spacing, 1.0)

    mode_config = _design_mode_config(_design_optimisation_goal(state))
    target_lo, target_hi, _ = _resolved_efficiency_target_band(mode_config, goal=_design_optimisation_goal(state))
    target_mid = (target_lo + target_hi) / 2.0
    seed_candidate = evaluate_candidate_full(state, source="guidance_shear_seed")
    if not seed_candidate:
        dbg["shear_tightening_terminal_reason"] = "no_seed_candidate"
        return None
    context = _build_auto_design_context(
        seed_candidate["state"],
        mode_config,
        reference_overview=seed_candidate.get("overview"),
    )
    eval_cache: dict = {}
    metrics = {
        "_reference_overview": seed_candidate.get("overview"),
        "generated_count": 0,
        "unique_eval_count": 0,
        "cache_hits": 0,
        "fast_eval_total_ms": 0.0,
        "cap_hit": False,
    }

    candidates: list[dict] = []
    for candidate_state in generate_less_shear_reo_variants(seed_candidate, mode_config):
        spacing_try = float(candidate_state.get("s_lig", current_spacing) or current_spacing)
        if abs(spacing_try - current_spacing) > 1e-9:
            dbg["shear_spacing_candidate_seen"] = True
        candidate = _evaluate_candidate_fast(
            candidate_state,
            seed_state=seed_candidate["state"],
            context=context,
            eval_cache=eval_cache,
            metrics=metrics,
            source="guidance_shear_tighten",
            label=_shear_state_label(candidate_state),
            action_type="increase_link_spacing",
        )
        if _invalid_shear_spacing_change_without_activation(
            state,
            candidate_state,
            source="guidance_shear_tighten",
        ):
            if abs(spacing_try - current_spacing) > 1e-9:
                dbg["shear_spacing_candidate_dropped_reason"] = "invalid_spacing_without_activation"
                dbg["shear_spacing_candidate_materiality"] = "guard_reject"
            continue
        if candidate is None or not bool(candidate.get("is_compliant")):
            if abs(spacing_try - current_spacing) > 1e-9:
                dbg["shear_spacing_candidate_dropped_reason"] = "non_compliant_or_failed_eval"
                dbg["shear_spacing_candidate_materiality"] = "compliance"
            _log_shear_candidate_debug(
                source="guidance_shear_tighten",
                candidate_state=candidate_state,
                candidate=candidate,
            )
            continue
        _pure_u, _bad_u = _shear_detailing_updates_pure(dict(candidate.get("updates") or {}))
        if not _pure_u:
            dbg["shear_candidate_family_pure"] = False
            dbg["shear_candidate_non_detailing_updates_detected"] = tuple(_bad_u)
            dbg["shear_candidate_rejected_reason"] = "non_shear_detailing_updates"
            continue
        dbg["shear_candidate_family_pure"] = True
        dbg["shear_candidate_non_detailing_updates_detected"] = tuple()
        dbg["shear_candidate_rejected_reason"] = None
        candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
        _log_shear_candidate_debug(
            source="guidance_shear_tighten",
            candidate_state=candidate_state,
            candidate=candidate,
        )
        spacing = float(candidate_state.get("s_lig", current_spacing) or current_spacing)
        legs = int(candidate_state.get("lig_legs", current_legs) or current_legs)
        dia = int(candidate_state.get("lig_d", current_dia) or current_dia)
        candidate_density = (legs * max(dia, 1) ** 2) / max(spacing, 1.0)
        if candidate_density >= current_density - 1e-9:
            if abs(spacing - current_spacing) > 1e-9 or legs != current_legs or dia != current_dia:
                dbg["shear_spacing_candidate_dropped_reason"] = "no_compliant_density_reduction_candidates"
                dbg["shear_spacing_candidate_materiality"] = "density_ordering"
            continue
        spacing_increase = max(spacing - current_spacing, 0.0)
        leg_reduction = max(current_legs - legs, 0)
        dia_reduction = max(current_dia - dia, 0)
        if spacing_increase <= 0.0 and leg_reduction <= 0 and dia_reduction <= 0:
            continue
        candidate["action_type"] = "increase_link_spacing" if spacing_increase > 0.0 else "reduce_number_of_legs"
        candidate["label"] = f"{legs}-leg N{dia} @ {int(spacing)}"
        candidates.append(candidate)

    if not candidates:
        dbg.setdefault("shear_spacing_candidate_dropped_reason", "no_compliant_density_reduction_candidates")
        dbg["shear_tightening_terminal_reason"] = "no_compliant_density_reduction_candidates"
        return None

    best = min(
        candidates,
        key=lambda item: (
            0 if target_lo <= float(item.get("overview", {}).get("utils", {}).get("shear", 0.0) or 0.0) <= target_hi else 1,
            abs(float(item.get("overview", {}).get("utils", {}).get("shear", 0.0) or 0.0) - target_mid),
            0 if str(item.get("action_type") or "") == "increase_link_spacing" else 1,
            -float(item.get("state", {}).get("s_lig", current_spacing) or current_spacing),
            int(item.get("state", {}).get("lig_legs", current_legs) or current_legs),
            int(item.get("state", {}).get("lig_d", current_dia) or current_dia),
        ),
    )
    _best_pure, _best_bad = _shear_detailing_updates_pure(dict(best.get("updates") or {}))
    if not _best_pure:
        dbg["shear_tightening_terminal_reason"] = "non_shear_detailing_best_rejected"
        dbg["shear_candidate_non_detailing_updates_detected"] = tuple(_best_bad)
        dbg["shear_candidate_family_pure"] = False
        return None
    dbg["shear_overdesign_spacing_candidate_committed"] = str(best.get("action_type") or "") == "increase_link_spacing"
    dbg["shear_overdesign_density_reduction_candidate_committed"] = True
    dbg["shear_tightening_terminal_reason"] = "spacing_or_leg_reduction"
    preview = _shear_preview_for_updates(state, dict(best.get("updates") or {})) or {}
    ct = "no_shear_design_cleanup" if str(best.get("candidate_type") or "") == "no_shear_design_cleanup" else "shear"
    try:
        _annotate_candidate_target_band_metrics(best, mode_config)
    except Exception:
        pass
    return {
        "updates": dict(best.get("updates") or {}),
        "label": str(best.get("label") or ""),
        "util": float(best.get("overview", {}).get("utils", {}).get("shear", 0.0) or 0.0),
        "web_util": float(preview.get("web_util", best.get("overview", {}).get("utils", {}).get("shear", 0.0)) or 0.0),
        "action_type": str(best.get("action_type") or "increase_link_spacing"),
        "score": float(best.get("score", 0.0) or 0.0),
        "candidate_summary": _candidate_debug_summary(best),
        "candidate_type": ct,
        "resolved_candidate": dict(best),
        "resolved_candidate_updates": dict(best.get("updates") or {}),
        "resolved_candidate_label": str(best.get("label") or ""),
        "resolved_candidate_action_type": str(best.get("action_type") or "increase_link_spacing"),
        "resolved_candidate_post_util": best.get("candidate_post_util", best.get("worst_util")),
        "resolved_candidate_reaches_target_band": bool(
            best.get("candidate_reaches_target_band") or best.get("reaches_target_band")
        ),
    }


def _geometry_tightening_trial_updates(state: dict) -> list[dict]:
    goal = _design_optimisation_goal(state)
    width_key, _, current_width = _resolve_geometry_width_context(state)
    current_depth = _float_from_state(state, "D", 600.0)
    unique_updates: dict[tuple[tuple[str, str], ...], dict] = {}

    def _add_trial(width: float, depth: float) -> None:
        rounded_width = float(int(round(max(GUIDANCE_MIN_PRACTICAL_WIDTH_MM, width) / 10.0) * 10))
        rounded_depth = float(int(round(max(GUIDANCE_MIN_PRACTICAL_DEPTH_MM, depth) / 10.0) * 10))
        updates = {width_key: rounded_width, "D": rounded_depth}
        if width_key != "b":
            updates["b"] = rounded_width
        if _updates_match_state(state, updates):
            return
        signature = tuple(sorted((key, str(value)) for key, value in updates.items()))
        unique_updates[signature] = updates

    if goal == "shallower_beam":
        _add_trial(current_width, current_depth - 100.0)
        _add_trial(current_width, current_depth - 50.0)
        _add_trial(current_width - 50.0, current_depth - 50.0)
        _add_trial(current_width - 50.0, current_depth)
    elif goal == "balanced":
        _add_trial(current_width, current_depth - 50.0)
        _add_trial(current_width - 50.0, current_depth)
        _add_trial(current_width - 50.0, current_depth - 50.0)
    elif goal == "less_longitudinal_reinforcement":
        _add_trial(current_width, current_depth - 50.0)
        _add_trial(current_width - 50.0, current_depth)
    else:
        _add_trial(current_width, current_depth - 50.0)

    return list(unique_updates.values())


def _compute_geometry_tightening_recommendation(state: dict) -> dict | None:
    state = _guidance_state_snapshot(state)
    if _geometry_lock_enabled(state):
        return None
    seed_candidate = evaluate_candidate_full(state, source="guidance_geometry_seed")
    if not seed_candidate or not bool(seed_candidate.get("is_compliant")):
        return None

    mode_config = _design_mode_config(_design_optimisation_goal(state))
    current_score = _score_auto_design_candidate(seed_candidate, mode_config, seed_candidate)
    context = _build_auto_design_context(
        seed_candidate["state"],
        mode_config,
        reference_overview=seed_candidate.get("overview"),
    )
    eval_cache: dict = {}
    metrics = {
        "_reference_overview": seed_candidate.get("overview"),
        "generated_count": 0,
        "unique_eval_count": 0,
        "cache_hits": 0,
        "fast_eval_total_ms": 0.0,
        "cap_hit": False,
    }
    candidates: list[dict] = []
    for updates in _geometry_tightening_trial_updates(state):
        width_key, _, _ = _resolve_geometry_width_context(state)
        trial_width = float(updates.get(width_key, updates.get("b", 0.0)) or 0.0)
        trial_depth = float(updates.get("D", 0.0) or 0.0)
        candidate_state = dict(state)
        candidate_state.update(updates)
        candidate = _evaluate_candidate_fast(
            candidate_state,
            seed_state=seed_candidate["state"],
            context=context,
            eval_cache=eval_cache,
            metrics=metrics,
            source="geometry_tighten",
            label=f"{int(trial_width)} x {int(trial_depth)} mm",
            action_type="tighten_geometry",
        )
        if candidate is None or not bool(candidate.get("is_compliant")):
            continue
        candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
        candidates.append(candidate)

    if not candidates:
        return None

    best = min(
        candidates,
        key=lambda item: (
            float(item.get("score", float("inf"))),
            0 if _candidate_in_target_band(item, mode_config) else 1,
            float(item.get("depth", 0.0) or 0.0),
            float(item.get("width", 0.0) or 0.0),
        ),
    )
    if float(best.get("score", float("inf"))) >= current_score - 1e-6:
        return None

    width_key, width_label, _ = _resolve_geometry_width_context(state)
    return {
        "updates": dict(best.get("updates") or {}),
        "width_key": width_key,
        "width_label": width_label,
        "width": float(best.get("width", 0.0) or 0.0),
        "depth": float(best.get("depth", 0.0) or 0.0),
        "util": float(best.get("worst_util", 0.0) or 0.0),
        "score": float(best.get("score", 0.0) or 0.0),
        "label": str(best.get("label") or ""),
        "candidate_summary": _candidate_debug_summary(best),
        "candidate_type": "geometry",
    }


def _guidance_objective_util_from_overview(overview: dict, goal: str) -> float | None:
    utils = dict((overview or {}).get("utils") or {})
    bend_pack = ((overview or {}).get("packs") or {}).get("bending") or {}
    phi_m = float(bend_pack.get("summary_phiMu_kNm", 0.0) or 0.0)
    mu_m = float(bend_pack.get("summary_Mu_star_kNm", 0.0) or 0.0)
    bend_demand = (mu_m / phi_m) if phi_m > 1e-9 else None
    if goal == "less_shear_reinforcement":
        value = utils.get("shear")
        return None if value is None else float(value)
    candidates = [value for value in (bend_demand, utils.get("bending"), utils.get("shear")) if value is not None]
    if not candidates:
        return None
    return max(float(value) for value in candidates)


def _mode_recommendation_expected_bend_util(mode_tighten: dict | None) -> float | None:
    """Mu*/φMu for the recommended trial; avoids stale objective_util / worst_util."""
    if not isinstance(mode_tighten, dict):
        return None
    for key in ("expected_util", "real_util"):
        raw = mode_tighten.get(key)
        if raw is None:
            continue
        try:
            v = float(raw)
        except Exception:
            continue
        if not math.isnan(v):
            return v
    cs = mode_tighten.get("candidate_summary") or {}
    phi_m = float(cs.get("summary_phiMu_kNm", 0.0) or 0.0)
    mu_m = float(cs.get("summary_Mu_star_kNm", 0.0) or 0.0)
    if phi_m > 1e-9:
        return mu_m / phi_m
    return None


def _mode_guidance_focus_from_updates(updates: dict) -> str:
    geometry_keys = {"D", "b", "bw", "tw"}
    bottom_keys = {
        "bot_row_count",
        "bot1_layout_mode",
        "bot1_count",
        "db_bot_1",
        "bot2_layout_mode",
        "bot2_count",
        "db_bot_2",
        "bot_row_1_mode",
        "bot_row_1_bars",
        "bot_row_1_spacing",
        "bot_row_1_dia",
        "bot_row_2_mode",
        "bot_row_2_bars",
        "bot_row_2_spacing",
        "bot_row_2_dia",
    }
    shear_keys = {"lig_d", "lig_legs", "s_lig"}
    if any(key in updates for key in geometry_keys):
        return "geometry"
    if any(key in updates for key in bottom_keys):
        return "bending"
    if any(key in updates for key in shear_keys):
        return "shear"
    return "general"


def _guidance_action_to_payload_name(action_type: str) -> str | None:
    mapping = {
        "apply_mode_recommendation": "mode_tightening",
        "apply_bottom_recommendation": "bottom_tightening",
        "apply_geometry_recommendation": "geometry_tightening",
        "apply_shear_recommendation": "shear_tightening",
        "reduce_bottom_reinforcement": "bottom_tightening",
        "reduce_bar_spacing": "bottom_tightening",
        "tighten_geometry": "geometry_tightening",
        "increase_depth": "geometry_tightening",
        "increase_width": "geometry_tightening",
        "reduce_link_spacing": "shear_tightening",
        "increase_link_spacing": "shear_tightening",
        "reduce_number_of_legs": "shear_tightening",
        "deflection_reduce_sustained_load": "general",
    }
    return mapping.get(str(action_type or ""))


def _is_design_guide_good_utilisation_band(util: object) -> bool:
    if util is None:
        return False
    try:
        u = float(util)
    except (TypeError, ValueError):
        return False
    return (not math.isnan(u)) and 0.80 <= u <= 0.95


def _is_design_guide_terminal_safe_item(item: dict) -> bool:
    _ts = str(item.get("design_guide_terminal_state") or "").strip()
    if _ts in ("optimal", "very_low_demand"):
        return True
    title = str(item.get("title_main") or "")
    primary = str(item.get("primary_action") or "")
    hay = f"{title} {primary}".lower()
    needles = (
        "no further safe local reductions",
        "no further local reductions",
        "no further recommendations",
        "critical case solved",
        "reducing non-critical provisions has reached a safe limit",
        "geometry locked for optimisation",
        "geometry locked. optimisation is limited",
    )
    return any(n in hay for n in needles)


def is_unnecessarily_overdesigned(
    overview: dict | None,
    efficiency_state: dict | None,
    *,
    recommendation_result: dict | None = None,
) -> bool:
    """
    True when checks pass but utilisation / efficiency profile indicates the section is materially
    more conservative than needed (efficiency-tightening candidate). Used for card theme only.
    """
    _ = recommendation_result
    if not isinstance(overview, dict) or not bool(overview.get("all_key_pass")):
        return False
    if bool(overview.get("any_fail")):
        return False
    es = efficiency_state if isinstance(efficiency_state, dict) else {}
    if str(es.get("classification") or "") == "optimal":
        return False
    if str(es.get("classification") or "") == "very_low_demand":
        return False
    if str(es.get("classification") or "") == "inefficient":
        return True
    if bool(es.get("strongly_underutilised")):
        return True
    if bool(es.get("is_efficiency_reduction_mode")):
        try:
            worst = float(overview.get("worst_util", 0.0) or 0.0)
        except (TypeError, ValueError):
            worst = 0.0
        if worst < float(GUIDANCE_TARGET_UTIL_MIN):
            return True
    return False


_ONE_CLICK_CTA_BLOCKING_REASONS = frozenset(
    {
        "partial_failure_coverage",
        "no_full_coverage_candidate",
        "no_multi_domain_target_candidate",
        "candidate_preview_has_fail_status",
    }
)

_RECOMMENDATION_NON_COMMIT_STATUSES = frozenset(
    {
        "blocked",
        "failed",
        "no_action",
        "no_actionable_full_coverage_candidate",
        "rejected",
    }
)


def _recommendation_updates_for_envelope(recommendation: dict | None) -> dict:
    """Return the updates the commit/apply layer would be asked to apply."""
    if not isinstance(recommendation, dict):
        return {}
    updates = recommendation.get("updates")
    if isinstance(updates, dict) and updates:
        return dict(updates)
    resolved = recommendation.get("resolved_candidate")
    if isinstance(resolved, dict) and isinstance(resolved.get("updates"), dict) and resolved.get("updates"):
        return dict(resolved.get("updates") or {})
    payload = recommendation.get("action_payload")
    if isinstance(payload, dict):
        payload_updates = payload.get("resolved_candidate_updates") or payload.get("updates")
        if isinstance(payload_updates, dict) and payload_updates:
            return dict(payload_updates)
    return {}


def _build_recommendation_envelope(
    *,
    updates: dict | None = None,
    source: str = "",
    status: str = "",
    blocked_reason: str | None = None,
    commit_eligible: bool | None = None,
    preview: dict | None = None,
    audit: dict | None = None,
    required_domains: list | tuple | set | None = None,
) -> dict:
    """
    Layer 7/8 boundary for Design Guide actions.

    Guidance may propose updates, but presentation may only render a normal CTA when this
    envelope says the action is commit-eligible.
    """
    updates_d = dict(updates or {}) if isinstance(updates, dict) else {}
    status_norm = str(status or "").strip()
    reason_norm = str(blocked_reason or "").strip()
    if commit_eligible is None:
        commit_eligible = bool(updates_d) and not reason_norm and status_norm not in _RECOMMENDATION_NON_COMMIT_STATUSES
    if isinstance(required_domains, str):
        domains_iter = [required_domains]
    else:
        domains_iter = list(required_domains or []) if required_domains is not None else []
    ordered_domains = [
        str(d or "").strip().lower()
        for d in domains_iter
        if str(d or "").strip()
    ]
    envelope_status = status_norm or ("ready" if commit_eligible else "blocked" if reason_norm else "advisory")
    return {
        "version": 1,
        "source": str(source or "").strip() or None,
        "status": envelope_status,
        "updates": updates_d,
        "commit_eligible": bool(commit_eligible),
        "blocked_reason": reason_norm or None,
        "required_domains": ordered_domains,
        "preview": dict(preview or {}) if isinstance(preview, dict) else {},
        "audit": dict(audit or {}) if isinstance(audit, dict) else {},
    }


def _attach_recommendation_envelope(
    recommendation: dict | None,
    *,
    source: str,
    status: str = "ready",
    blocked_reason: str | None = None,
    commit_eligible: bool | None = None,
    preview: dict | None = None,
    audit: dict | None = None,
    required_domains: list | tuple | set | None = None,
) -> dict | None:
    if not isinstance(recommendation, dict):
        return None
    out = dict(recommendation)
    envelope = _build_recommendation_envelope(
        updates=_recommendation_updates_for_envelope(out),
        source=source,
        status=status,
        blocked_reason=blocked_reason,
        commit_eligible=commit_eligible,
        preview=preview,
        audit=audit,
        required_domains=required_domains,
    )
    out["recommendation_envelope"] = envelope
    out["commit_eligible"] = bool(envelope.get("commit_eligible"))
    out["blocked_reason"] = envelope.get("blocked_reason")
    return out


def _recommendation_envelope_from_pending(recommendation: dict | None) -> dict:
    if not isinstance(recommendation, dict):
        return {}
    envelope = recommendation.get("recommendation_envelope")
    if isinstance(envelope, dict):
        return dict(envelope)
    meta = dict(recommendation.get("meta") or {})
    status = str(meta.get("status") or recommendation.get("status") or "").strip()
    reason = str(
        recommendation.get("blocked_reason")
        or meta.get("blocked_reason")
        or meta.get("reason")
        or ""
    ).strip()
    return _build_recommendation_envelope(
        updates=_recommendation_updates_for_envelope(recommendation),
        source=str(recommendation.get("_source") or recommendation.get("source") or "legacy_pending"),
        status=status,
        blocked_reason=reason or None,
    )


def _recommendation_commit_eligible(recommendation: dict | None) -> bool:
    envelope = _recommendation_envelope_from_pending(recommendation)
    return bool(envelope.get("commit_eligible"))


def _recommendation_blocked_reason(recommendation: dict | None) -> str | None:
    envelope = _recommendation_envelope_from_pending(recommendation)
    reason = str(envelope.get("blocked_reason") or "").strip()
    if reason:
        return reason
    if isinstance(recommendation, dict) and not bool(envelope.get("commit_eligible")):
        status = str(envelope.get("status") or "").strip()
        if status in _RECOMMENDATION_NON_COMMIT_STATUSES:
            return status
    return None


def _design_guide_fail_fingerprints_equivalent(a: dict | None, b: dict | None) -> bool:
    """Treat tiny util drift as equivalent when the failing state is otherwise unchanged."""

    def _norm_keys(v: dict | None) -> list[str]:
        return sorted(str(x or "").strip().lower() for x in list((v or {}).get("fail_keys") or []) if str(x or "").strip())

    def _norm_status(v: dict | None, key: str) -> str:
        return str((v or {}).get(key) or "").strip().upper()

    def _util_close(x: object, y: object) -> bool:
        ux = _parse_util_value(x)
        uy = _parse_util_value(y)
        if ux is None or uy is None:
            return ux is None and uy is None
        if not (math.isfinite(float(ux)) and math.isfinite(float(uy))):
            return ux == uy
        return abs(float(ux) - float(uy)) <= 1e-6

    da = dict(a or {})
    db = dict(b or {})
    return (
        _norm_keys(da) == _norm_keys(db)
        and _norm_status(da, "shear_status") == _norm_status(db, "shear_status")
        and _norm_status(da, "bending_status") == _norm_status(db, "bending_status")
        and _util_close(da.get("shear_util"), db.get("shear_util"))
        and _util_close(da.get("bending_util"), db.get("bending_util"))
    )


def _one_click_feedback_cta_state(
    overview: dict | None,
    *,
    clear_stale: bool = True,
) -> dict:
    feedback = st.session_state.get("_one_click_run_feedback")
    if not isinstance(feedback, dict):
        feedback = {}
    status = str(feedback.get("status") or "").strip()
    reason = str(feedback.get("reason") or "").strip()
    if clear_stale and status in {"blocked", "rejected"} and reason == "stale_primary_design_guide_payload":
        # A stale canonical apply payload is a transient render/payload binding
        # condition, not an engineering blocker. The primary card renderer
        # rebuilds the canonical payload from the final visible card before
        # enabling the CTA, so do not leave a stale-payload warning visible
        # under a fresh enabled action.
        st.session_state.pop("_one_click_run_feedback", None)
        return {
            "feedback": {},
            "status": "",
            "reason": "",
            "feedback_fail_fingerprint": {},
            "current_fail_fingerprint": dict(_current_design_guide_fail_fingerprint(overview)),
            "blocks_primary_cta": False,
            "matches_current_state": False,
            "stale_cleared": True,
            "stale_clear_reason": "stale_primary_design_guide_payload_refreshed",
        }
    feedback_fp = dict(feedback.get("current_fail_fingerprint") or {})
    current_fp = _current_design_guide_fail_fingerprint(overview)
    blocks_primary_cta = bool(reason in _ONE_CLICK_CTA_BLOCKING_REASONS)
    fingerprints_match = bool(
        feedback_fp
        and (
            feedback_fp == current_fp
            or _design_guide_fail_fingerprints_equivalent(feedback_fp, current_fp)
        )
    )
    matches_current_state = bool(
        status in {"blocked", "rejected"}
        and blocks_primary_cta
        and fingerprints_match
    )
    stale_cleared = False
    if (
        clear_stale
        and status in {"blocked", "rejected"}
        and blocks_primary_cta
        and feedback_fp
        and not fingerprints_match
    ):
        st.session_state.pop("_one_click_run_feedback", None)
        feedback = {}
        status = ""
        reason = ""
        feedback_fp = {}
        stale_cleared = True
    return {
        "feedback": dict(feedback),
        "status": status,
        "reason": reason,
        "feedback_fail_fingerprint": dict(feedback_fp),
        "current_fail_fingerprint": dict(current_fp),
        "blocks_primary_cta": bool(blocks_primary_cta),
        "matches_current_state": bool(matches_current_state),
        "stale_cleared": bool(stale_cleared),
        "stale_clear_reason": "fail_fingerprint_changed" if stale_cleared else None,
    }


def _latest_solver_result_cta_state(overview: dict | None) -> dict:
    """
    Presentation-layer guard based on the latest one-click solver result.

    This is intentionally separate from `_one_click_run_feedback` so a blocked solver result
    cannot be visually overwritten by a freshly rebuilt guidance card in the next render.
    """
    result = st.session_state.get("_solver_result")
    if not isinstance(result, dict):
        return {
            "status": "",
            "reason": "",
            "matches_current_state": False,
            "current_fail_fingerprint": {},
            "result_fail_fingerprint": {},
        }

    status = str(result.get("status") or st.session_state.get("auto_design_status") or "").strip()
    stop_reason = str(result.get("stop_reason") or "").strip()
    envelope = dict(result.get("recommendation_envelope") or {})
    blocked_reason = str(envelope.get("blocked_reason") or stop_reason or "").strip()
    commit_eligible = bool(envelope.get("commit_eligible"))

    if commit_eligible:
        return {
            "status": status,
            "reason": blocked_reason,
            "matches_current_state": False,
            "current_fail_fingerprint": {},
            "result_fail_fingerprint": {},
        }

    if blocked_reason not in _ONE_CLICK_CTA_BLOCKING_REASONS and status not in {
        "blocked",
        "no_action",
        "no_actionable_full_coverage_candidate",
        "rejected",
    }:
        return {
            "status": status,
            "reason": blocked_reason,
            "matches_current_state": False,
            "current_fail_fingerprint": {},
            "result_fail_fingerprint": {},
        }

    result_dbg = dict(result.get("one_click_solver_debug") or {})
    result_fp = dict(result_dbg.get("current_fail_fingerprint") or {})
    current_fp = _current_design_guide_fail_fingerprint(overview)
    fingerprints_match = bool(
        result_fp
        and (
            result_fp == current_fp
            or _design_guide_fail_fingerprints_equivalent(result_fp, current_fp)
        )
    )

    return {
        "status": status,
        "reason": blocked_reason,
        "matches_current_state": bool(fingerprints_match),
        "current_fail_fingerprint": dict(current_fp),
        "result_fail_fingerprint": dict(result_fp),
    }


def _build_design_guide_presentation_state(
    *,
    primary_item: dict | None,
    overview: dict | None,
    efficiency_state: dict | None,
    disp_state: dict,
    mode_config: dict | None,
    recommendation_result: dict | None = None,
    pending_recommendation: dict | None = None,
) -> dict:
    """
    Design Guide presentation contract (product rules — do not regress without explicit review).

    - fail beats everything
    - warn / near-limit beats healthy (including utilisation at the upper guidance threshold while
      checks still PASS)
    - healthy means:
        all_key_pass
        no fail
        no warn
        in target band
        not unnecessarily overdesigned
    - efficiency means safe but materially overdesigned
    - the primary recommendation is rendered in one card only (callers must not duplicate titles /
      change lines outside this surface)
    - this function controls card and apply button theme (css_bucket, use_success_style); it does
      not change recommendation semantics or apply payloads

    Evaluation order: fail → warn → healthy → efficiency → info.
    """
    _ = recommendation_result
    ov = overview if isinstance(overview, dict) else {}
    es = efficiency_state if isinstance(efficiency_state, dict) else {}
    mode_cfg = (
        mode_config
        if isinstance(mode_config, dict)
        else _design_mode_config(_design_optimisation_goal(disp_state))
    )
    governing_action, _primary_utils = _guidance_governing_primary_action(ov)

    headline = str((primary_item or {}).get("title_main") or "").strip() or "Design guidance"
    pending = pending_recommendation if isinstance(pending_recommendation, dict) else {}
    pending_commit_eligible = _recommendation_commit_eligible(pending) if pending else False
    pending_blocked_reason = _recommendation_blocked_reason(pending) if pending else None
    feedback_cta_state = _one_click_feedback_cta_state(ov, clear_stale=True)
    feedback_blocks_primary_cta = bool(feedback_cta_state.get("matches_current_state"))
    feedback_blocked_reason = str(feedback_cta_state.get("reason") or "").strip() or None
    solver_result_cta_state = _latest_solver_result_cta_state(ov)
    solver_result_blocks_primary_cta = bool(solver_result_cta_state.get("matches_current_state"))
    solver_result_blocked_reason = str(solver_result_cta_state.get("reason") or "").strip() or None
    button_label = (
        "Apply Auto Design"
        if str(pending.get("_source") or "").strip() == "auto_design"
        else "Apply Recommendation"
    )
    primary_item_has_actionable_updates = bool(_recommendation_updates_for_envelope(primary_item))

    try:
        worst = float(ov.get("worst_util", 0.0) or 0.0)
    except (TypeError, ValueError):
        worst = 0.0

    any_fail = bool(ov.get("any_fail"))
    any_warn = bool(ov.get("any_warn"))
    all_key_pass = bool(ov.get("all_key_pass"))
    overdesigned = is_unnecessarily_overdesigned(ov, es, recommendation_result=recommendation_result)
    in_target_band = _is_in_target_zone_with_eps(ov, mode_cfg, eps=TARGET_BAND_EPS)
    near_limit_util = bool(all_key_pass and worst >= float(GUIDANCE_NEAR_LIMIT_UTIL_THRESHOLD))
    classification_es = str(es.get("classification") or "").strip()
    terminal_optimal = (
        classification_es == "optimal"
        or str((primary_item or {}).get("design_guide_terminal_state") or "") == "optimal"
    )
    terminal_very_low_demand = (
        classification_es == "very_low_demand"
        or str((primary_item or {}).get("design_guide_terminal_state") or "") == "very_low_demand"
    ) and not bool(primary_item_has_actionable_updates)
    guidance_intent = str((primary_item or {}).get("guidance_intent") or "").strip()
    if guidance_intent not in DESIGN_GUIDE_INTENTS and isinstance(primary_item, dict):
        try:
            guidance_intent = _derive_design_guide_guidance_intent(
                primary_item,
                state=disp_state,
                overview=ov,
                efficiency_state=es,
            )
        except Exception:
            guidance_intent = "advisory_warning"
    primary_truth = dict((primary_item or {}).get("display_truth") or {})
    if not primary_truth and isinstance(primary_item, dict):
        primary_truth = _design_guide_display_truth_for_item(
            primary_item,
            state=disp_state,
            overview=ov,
            mode_config=mode_cfg,
        )
    primary_truth_source = str(primary_truth.get("display_truth_source") or "").strip()
    primary_truth_in_target = bool(primary_truth.get("displayed_within_target_band"))
    passive_underband_threshold = max(
        float(mode_cfg.get("target_lo", EFFICIENCY_TARGET_UTIL_MIN)),
        float(EFFICIENCY_TARGET_UTIL_MIN),
    )
    passive_underband_no_action = bool(
        all_key_pass
        and not any_fail
        and not any_warn
        and worst < float(passive_underband_threshold) - float(TARGET_BAND_EPS)
        and not bool(primary_item_has_actionable_updates)
        and not bool(pending_commit_eligible)
    )

    primary_button_contract = dict((primary_item or {}).get("button_contract") or {})
    primary_candidate_search_evidence = dict(
        (primary_item or {}).get("candidate_search_evidence")
        or ((primary_item or {}).get("action_payload") or {}).get("candidate_search_evidence")
        or ((primary_item or {}).get("resolved_candidate") or {}).get("candidate_search_evidence")
        or {}
    )
    engine_decision = resolve_design_guide_decision(
        current_state=dict(disp_state),
        summary=dict(ov),
        raw_items=[dict(primary_item or {})] if isinstance(primary_item, dict) and primary_item else [],
        candidate_evidence=dict(primary_candidate_search_evidence),
        # Transitional candidate preparation only. Final Design Guide decision,
        # target-band winner selection, and outside-target allowance are owned by
        # design_guidance_engine.resolve_design_guide_decision.
        raw_candidates=[dict(primary_item or {})] if isinstance(primary_item, dict) and primary_item else [],
        target_band=target_band_payload(_design_optimisation_goal(disp_state)),
        context={
            "goal": _design_optimisation_goal(disp_state),
            "headline": headline,
            "governing_action": governing_action,
            "pending": bool(pending),
            "pending_commit_eligible": bool(pending_commit_eligible),
            "pending_blocked_reason": pending_blocked_reason,
            "feedback_blocks_primary_cta": bool(feedback_blocks_primary_cta),
            "feedback_blocked_reason": feedback_blocked_reason,
            "solver_result_blocks_primary_cta": bool(solver_result_blocks_primary_cta),
            "solver_result_blocked_reason": solver_result_blocked_reason,
            "button_label": button_label,
            "primary_item_has_actionable_updates": bool(primary_item_has_actionable_updates),
            "worst": worst,
            "any_fail": bool(any_fail),
            "any_warn": bool(any_warn),
            "all_key_pass": bool(all_key_pass),
            "overdesigned": bool(overdesigned),
            "in_target_band": bool(in_target_band),
            "near_limit_util": bool(near_limit_util),
            "terminal_optimal": bool(terminal_optimal),
            "terminal_very_low_demand": bool(terminal_very_low_demand),
            "guidance_intent": guidance_intent,
            "passive_underband_no_action": bool(passive_underband_no_action),
            "candidate_search_evidence": dict(primary_candidate_search_evidence),
            "efficiency_state": dict(es),
        },
    )
    try:
        st.session_state["_design_guide_engine_decision"] = dict(engine_decision)
    except Exception:
        pass
    return dict(engine_decision.get("presentation") or {})


def _design_guide_primary_uses_success_style(item: dict) -> bool:
    """Green 'done' card: resolved safe/complete only, not active fix recommendations."""
    bucket = str(item.get("bucket") or "")
    if bucket == "fail":
        return False
    if bucket == "start":
        return False
    has_apply = bool(item.get("action_type"))
    if has_apply and bucket in ("fail", "warn", "efficiency"):
        return False
    if bucket == "warn" and not _is_design_guide_terminal_safe_item(item):
        return False
    terminal = _is_design_guide_terminal_safe_item(item)
    good_band = _is_design_guide_good_utilisation_band(item.get("util"))
    if terminal:
        return True
    if good_band and bucket == "pass":
        return True
    return False


def _render_guidance_secondary_items(
    guidance_items: list[dict],
    *,
    guidance_disp_state: dict,
    current_overview: dict | None = None,
    inputs_render_audit: dict[str, str] | None = None,
    start_index: int = 0,
    primary_card_presentation: dict | None = None,
) -> None:
    for idx, item in enumerate(guidance_items):
        _render_active_fail_keys: set[str] = set()
        if idx < start_index:
            continue
        if isinstance(item, dict):
            item = normalise_final_visible_design_guide_item(item)
            guidance_items[idx] = item
        button_contract = dict(item.get("button_contract") or {}) if isinstance(item, dict) else {}
        if (
            idx == 0
            and start_index == 0
            and isinstance(item, dict)
            and _design_guide_item_is_visible_blocker(item)
            and _design_guide_presentation_is_green_terminal(primary_card_presentation)
        ):
            # The item is the visible contract.  A stale success presentation
            # must not repaint an exact blocker as "Design is efficient".
            primary_card_presentation = {}
            item["bucket"] = "efficiency"
            if str(item.get("status") or "").strip().upper() in {"PASS", "OPTIMAL", "ACCEPTED"}:
                item["status"] = "INFO"
            _render_bundle = st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY)
            if isinstance(_render_bundle, dict):
                _render_bundle["green_terminal_presentation_suppressed_for_exact_blocker"] = True
                _render_bundle["design_guide_terminal_state"] = None
                _render_bundle["design_guide_terminal_positive"] = False
        if idx == 0 and start_index == 0 and isinstance(item, dict):
            _render_overview_for_active = current_overview if isinstance(current_overview, dict) else {}
            if not dict(_render_overview_for_active.get("statuses") or {}):
                try:
                    _render_overview_for_active = _collect_design_overview(
                        guidance_disp_state,
                        context=_build_design_actions_context(guidance_disp_state),
                    )
                except Exception:
                    _render_overview_for_active = {}
            _render_active_fail_keys = _overview_active_failure_keys(_render_overview_for_active)
            _render_item_text_for_active = " ".join(
                str(item.get(key) or "")
                for key in ("title_main", "title", "primary_action", "secondary_action", "reasoning")
            ).lower()
            _render_contract_for_active = dict(item.get("button_contract") or {})
            _render_updates_for_active = dict(
                _render_contract_for_active.get("updates")
                or item.get("updates")
                or _resolve_recommendation_updates(item, state=guidance_disp_state)
                or {}
            )
            _render_is_active_blocker = bool(
                (_render_active_fail_keys & {"bending", "shear"})
                and (
                    "repair blocked" in _render_item_text_for_active
                    or bool(item.get("active_under_capacity_blocker"))
                    or bool(item.get("exact_blockers_by_family"))
                )
                and not (
                    str(item.get("action_type") or _render_contract_for_active.get("action_type") or "").strip()
                    == "apply_resolved_candidate"
                    and _design_guide_button_contract_enabled(_render_contract_for_active)
                    and _render_updates_for_active
                )
            )
            if _render_is_active_blocker:
                _render_repair_item = None
                try:
                    _render_repair_item = _direct_target_band_guidance_item(
                        guidance_disp_state,
                        dict(_render_overview_for_active),
                        _design_mode_config(_design_optimisation_goal(guidance_disp_state)),
                        strengthening=True,
                        debug_sink=st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY)
                        if isinstance(st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY), dict)
                        else None,
                    )
                except Exception:
                    _render_repair_item = None
                if isinstance(_render_repair_item, dict):
                    try:
                        _render_repair_items = _design_guide_apply_button_contracts_to_items(
                            [_render_repair_item],
                            state=guidance_disp_state,
                        )
                    except Exception:
                        _render_repair_items = [_render_repair_item]
                    if _render_repair_items and isinstance(_render_repair_items[0], dict):
                        _render_repair_item = dict(_render_repair_items[0])
                    _render_repair_contract = dict(_render_repair_item.get("button_contract") or {})
                    _render_repair_updates = dict(
                        _render_repair_contract.get("updates")
                        or _render_repair_item.get("updates")
                        or _resolve_recommendation_updates(_render_repair_item, state=guidance_disp_state)
                        or {}
                    )
                    if (
                        str(_render_repair_item.get("action_type") or _render_repair_contract.get("action_type") or "").strip()
                        == "apply_resolved_candidate"
                        and _design_guide_button_contract_enabled(_render_repair_contract)
                        and _render_repair_updates
                    ):
                        if _render_active_fail_keys >= {"bending", "shear"}:
                            _render_repair_family = "combined"
                            _render_repair_title = "Bending and shear capacity are low"
                        elif "shear" in _render_active_fail_keys:
                            _render_repair_family = "shear"
                            _render_repair_title = "Shear capacity is low"
                        else:
                            _render_repair_family = "bending"
                            _render_repair_title = "Bending capacity is low"
                        _render_repair_contract.update(
                            {
                                "enabled": True,
                                "actionable": True,
                                "action_type": "apply_resolved_candidate",
                                "family": _render_repair_family,
                                "updates": dict(_render_repair_updates),
                                "preview_pass": True,
                                "blocking_reason": None,
                            }
                        )
                        _render_repair_item.update(
                            {
                                "title_main": _render_repair_title,
                                "title": _render_repair_title,
                                "family": _render_repair_family,
                                "check_key": _render_repair_family,
                                "guidance_intent": "required_fix",
                                "primary_card_actionable": True,
                                "final_state_class": "action",
                                "button_contract": dict(_render_repair_contract),
                                "updates": dict(_render_repair_updates),
                            }
                        )
                        for _blocker_only_key in (
                            "exact_blockers_by_family",
                            "post_click_exact_blockers_by_family",
                            "cleanup_evidence_by_family",
                            "post_click_cleanup_evidence_by_family",
                            "local_cleanup_blocked_reasons",
                            "local_cleanup_blocked_reasons_by_family",
                            "exact_blocker_reasons_by_family",
                            "blocker_reasons_by_family",
                            "active_under_capacity_blocker",
                            "active_under_capacity_blocker_reason",
                            "active_under_capacity_blocker_family",
                        ):
                            _render_repair_item.pop(_blocker_only_key, None)
                        _render_repair_item = normalise_final_visible_design_guide_item(_render_repair_item)
                        guidance_items[idx] = dict(_render_repair_item)
                        item = guidance_items[idx]
                        _render_bundle = st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY)
                        if isinstance(_render_bundle, dict):
                            _render_bundle.update(
                                {
                                    "guidance_branch": "render_active_failure_repair_published",
                                    "selected_title": _render_repair_title,
                                    "selected_action_type": "apply_resolved_candidate",
                                    "selected_action_family": _render_repair_family,
                                    "primary_card_title": _render_repair_title,
                                    "primary_guidance_intent": "required_fix",
                                    "button_contract": dict(_render_repair_contract),
                                    "primary_button_contract": dict(_render_repair_contract),
                                    "button_contract_enabled": True,
                                    "button_contract_updates": dict(_render_repair_updates),
                                    "candidate_search_evidence": dict(
                                        _render_repair_item.get("candidate_search_evidence") or {}
                                    ),
                                }
                            )
            if (
                isinstance(item, dict)
                and _design_guide_item_is_visible_blocker(item)
                and not (_render_active_fail_keys & {"bending", "shear"})
            ):
                _render_blocker_evidence = dict(
                    item.get("candidate_search_evidence")
                    or (item.get("action_payload") or {}).get("candidate_search_evidence")
                    or (item.get("resolved_candidate") or {}).get("candidate_search_evidence")
                    or {}
                )
                _render_safe_cleanup_updates = dict(
                    _render_blocker_evidence.get("selected_candidate_updates")
                    or _render_blocker_evidence.get("best_safe_candidate_updates")
                    or _render_blocker_evidence.get("closest_safe_candidate_updates")
                    or {}
                )
                try:
                    _render_post_click_route = bool(
                        _local_cleanup_post_apply_acceptance_matches(guidance_disp_state)
                    )
                except Exception:
                    _render_post_click_route = False
                if (
                    not _render_post_click_route
                    and _render_safe_cleanup_updates
                    and bool(set(_render_safe_cleanup_updates) & _COMPOUND_SHEAR_UPDATE_KEYS)
                    and int(
                        _render_blocker_evidence.get("safe_executor_backed_candidates_count")
                        or _render_blocker_evidence.get("executable_candidate_count")
                        or _render_blocker_evidence.get("executable_cleanup_count")
                        or 0
                    )
                    > 0
                    and not _updates_match_state(guidance_disp_state, _render_safe_cleanup_updates)
                ):
                    _render_safe_cleanup_item = _shear_best_safe_cleanup_item_from_evidence(
                        guidance_disp_state,
                        dict(_render_overview_for_active or {}),
                        _render_blocker_evidence,
                        title=str(
                            _render_blocker_evidence.get("selected_candidate_title")
                            or _render_blocker_evidence.get("closest_safe_candidate_title")
                            or "Shear cleanup - best safe one-click reduction"
                        ),
                    )
                    if isinstance(_render_safe_cleanup_item, dict):
                        _render_safe_cleanup_item = normalise_final_visible_design_guide_item(
                            _render_safe_cleanup_item
                        )
                        _render_safe_cleanup_contract = dict(
                            _render_safe_cleanup_item.get("button_contract") or {}
                        )
                        _render_safe_cleanup_updates = dict(
                            _render_safe_cleanup_contract.get("updates")
                            or _render_safe_cleanup_item.get("updates")
                            or _resolve_recommendation_updates(
                                _render_safe_cleanup_item,
                                state=guidance_disp_state,
                            )
                            or {}
                        )
                        if (
                            _design_guide_button_contract_enabled(_render_safe_cleanup_contract)
                            and _render_safe_cleanup_updates
                        ):
                            _render_safe_cleanup_item.update(
                                {
                                    "primary_card_actionable": True,
                                    "action_type": str(
                                        _render_safe_cleanup_contract.get("action_type")
                                        or "apply_resolved_candidate"
                                    ),
                                    "updates": dict(_render_safe_cleanup_updates),
                                    "selected_action_updates": dict(_render_safe_cleanup_updates),
                                    "button_contract": dict(_render_safe_cleanup_contract),
                                    "final_visible_state_fingerprint": _design_guide_primary_apply_state_fingerprint(guidance_disp_state),
                                    "final_visible_design_guide_item": True,
                                    "final_visible_resolver_reason": "render_safe_cleanup_candidate_before_blocker",
                                }
                            )
                            item = _render_safe_cleanup_item
                            guidance_items[idx] = item
                            primary_card_presentation = {}
                            _render_bundle = st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY)
                            if isinstance(_render_bundle, dict):
                                _render_bundle["safe_cleanup_candidate_from_blocker_evidence"] = True
                                _render_bundle["safe_cleanup_candidate_id"] = _render_safe_cleanup_contract.get("candidate_id")
        if (
            idx == 0
            and start_index == 0
            and _guidance_item_is_active_strength_repair_action(item)
            and bool(_render_active_fail_keys & {"bending", "shear"})
        ):
            # Presentation only: an executor-backed repair for an actively
            # failing strength check must stay in the red/fail visual lane even
            # when its preview utilisation lands safely below 1.0.
            item["bucket"] = "fail"
            item["status"] = "FAIL"
            item["active_strength_repair_display"] = True
        if idx == 0 and start_index == 0:
            _pre_render_debug_sink = st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY)
            if not isinstance(_pre_render_debug_sink, dict):
                _pre_render_debug_sink = {}
                st.session_state[DESIGN_GUIDE_DEBUG_BUNDLE_KEY] = _pre_render_debug_sink
            _pre_render_bound_item = _publish_final_visible_design_guide_contract_binding(
                item=dict(item),
                state=guidance_disp_state,
                debug_sink=_pre_render_debug_sink,
                rec=dict(st.session_state.get("pending_recommendation") or {}),
            )
            _pre_render_bound_contract = dict(
                (_pre_render_bound_item or {}).get("button_contract") or {}
            )
            _pre_render_safe_combined_action = _visible_safe_combined_cleanup_action_from_evidence(
                _pre_render_bound_item,
                current_overview,
                guidance_disp_state,
                debug_sink=_pre_render_debug_sink,
            )
            if isinstance(_pre_render_safe_combined_action, dict):
                item = dict(_pre_render_safe_combined_action)
                guidance_items[idx] = item
                _pre_render_bound_item = dict(item)
                _pre_render_bound_contract = dict(item.get("button_contract") or {})
                button_contract = dict(_pre_render_bound_contract)
                _pre_render_debug_sink["pre_render_safe_combined_cleanup_promoted"] = True
            _pre_render_bound_updates_for_combined = dict(
                _pre_render_bound_contract.get("updates")
                or (_pre_render_bound_item or {}).get("updates")
                or (_pre_render_bound_item or {}).get("selected_action_updates")
                or {}
            )
            _pre_render_bound_candidate_text = " ".join(
                str(value or "")
                for value in (
                    _pre_render_bound_contract.get("candidate_id"),
                    _pre_render_bound_contract.get("source_candidate_id"),
                    (_pre_render_bound_item or {}).get("candidate_id"),
                    (_pre_render_bound_item or {}).get("source_candidate_id"),
                    (_pre_render_bound_item or {}).get("title_main"),
                    (_pre_render_bound_item or {}).get("title"),
                )
            ).lower()
            if (
                isinstance(_pre_render_bound_item, dict)
                and _pre_render_bound_updates_for_combined
                and bool(set(_pre_render_bound_updates_for_combined) & _COMPOUND_SHEAR_UPDATE_KEYS)
                and bool(set(_pre_render_bound_updates_for_combined) & _COMPOUND_BOTTOM_UPDATE_KEYS)
                and "combined" in _pre_render_bound_candidate_text
            ):
                try:
                    _pre_render_combined_preview = _evaluate_auto_design_candidate(
                        guidance_disp_state,
                        updates=dict(_pre_render_bound_updates_for_combined),
                        source="pre_render_combined_cleanup_contract_restamp",
                        label="Shear and bending cleanup - one-click optimisation",
                        action_type="apply_resolved_candidate",
                    )
                except Exception:
                    _pre_render_combined_preview = None
                _pre_render_combined_overview = dict(
                    (_pre_render_combined_preview or {}).get("overview") or {}
                )
                _pre_render_combined_expected = _parse_util_value(
                    dict(_pre_render_combined_overview.get("utils") or {}).get("bending")
                    or _pre_render_combined_overview.get("worst_util")
                    or _pre_render_combined_overview.get("governing_util")
                    or _pre_render_bound_contract.get("expected_util")
                )
                _pre_render_combined_candidate_id = "combined_best_safe_shear_plus_bending_cleanup"
                _pre_render_bound_contract.update(
                    {
                        "enabled": True,
                        "actionable": True,
                        "action_type": "apply_resolved_candidate",
                        "family": "combined",
                        "updates": dict(_pre_render_bound_updates_for_combined),
                        "preview_pass": True,
                        "blocking_reason": None,
                        "source_candidate_id": _pre_render_combined_candidate_id,
                        "candidate_id": _pre_render_combined_candidate_id,
                    }
                )
                if _pre_render_combined_expected is not None:
                    _pre_render_bound_contract["expected_util"] = float(_pre_render_combined_expected)
                _pre_render_evidence = dict(
                    _pre_render_bound_item.get("candidate_search_evidence")
                    or (_pre_render_bound_item.get("action_payload") or {}).get("candidate_search_evidence")
                    or (_pre_render_bound_item.get("resolved_candidate") or {}).get("candidate_search_evidence")
                    or {}
                )
                _pre_render_evidence.update(
                    {
                        "family": "combined",
                        "selected_candidate_id": _pre_render_combined_candidate_id,
                        "selected_candidate_title": "Shear and bending cleanup - one-click optimisation",
                        "selected_candidate_updates": dict(_pre_render_bound_updates_for_combined),
                        "best_safe_candidate_updates": dict(_pre_render_bound_updates_for_combined),
                        "search_scope": "combined_best_safe_shear_plus_bending_cleanup",
                    }
                )
                if _pre_render_combined_expected is not None:
                    _pre_render_evidence["selected_candidate_util"] = float(_pre_render_combined_expected)
                    _pre_render_evidence["best_safe_final_util"] = float(_pre_render_combined_expected)
                _pre_render_bound_item.update(
                    {
                        "title_main": "Shear and bending cleanup - one-click optimisation",
                        "title": "Shear and bending cleanup - one-click optimisation",
                        "family": "combined",
                        "check_key": "combined",
                        "selected_action_family": "combined",
                        "action_type": "apply_resolved_candidate",
                        "primary_card_actionable": True,
                        "updates": dict(_pre_render_bound_updates_for_combined),
                        "selected_action_updates": dict(_pre_render_bound_updates_for_combined),
                        "candidate_id": _pre_render_combined_candidate_id,
                        "source_candidate_id": _pre_render_combined_candidate_id,
                        "button_contract": dict(_pre_render_bound_contract),
                        "candidate_search_evidence": dict(_pre_render_evidence),
                    }
                )
                if _pre_render_combined_expected is not None:
                    _pre_render_bound_item["util"] = float(_pre_render_combined_expected)
                    _pre_render_bound_item["expected_util"] = float(_pre_render_combined_expected)
                    _pre_render_bound_item["candidate_post_util"] = float(_pre_render_combined_expected)
                _pre_render_payload = dict(_pre_render_bound_item.get("action_payload") or {})
                _pre_render_payload.update(
                    {
                        "family": "combined",
                        "updates": dict(_pre_render_bound_updates_for_combined),
                        "resolved_candidate_updates": dict(_pre_render_bound_updates_for_combined),
                        "resolved_candidate_family_tag": "combined",
                        "candidate_id": _pre_render_combined_candidate_id,
                        "source_candidate_id": _pre_render_combined_candidate_id,
                        "candidate_search_evidence": dict(_pre_render_evidence),
                    }
                )
                if _pre_render_combined_expected is not None:
                    _pre_render_payload["expected_util"] = float(_pre_render_combined_expected)
