    def _render_current_inputs_summary() -> None:
        _summary_render_started = time.perf_counter()
        render_timing_mark("inputs_page.summary_render.start", elapsed_ms=_inputs_elapsed_ms())
        with summary_container.container():
            st.title("Inputs")
